// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 응시
// 학자 · 주술사 · 퇴마사 · 관상가 · 탐정
// 응시: 무엇이 진짜인지 본다 — 비 오는 밤, 잠긴 곳, 쫓는 것, 배신, 줄어드는 시간
// ==========================================

// ------------------------------------------
// 학자 · 자원 없음
// ------------------------------------------
kJob('scholar', 'B', [

{ at:'B', t:'빗속 — 번진 쪽지',
  x:`문틈에 쪽지가 끼여 있다. 빗물을 먹었다.<br><br>
    잉크가 번져 글자가 꽃처럼 퍼졌다. 줄마다 아래로 흘렀다.<br>
    먼저 온 누가 남긴 것이다. 첫 줄 첫 글자만 읽힌다. 『오』.<br><br>
    등 뒤 모퉁이에서 발소리가 멈췄다가 다시 난다. 쪽지를 펴 볼 시간은 숨 몇 번이다.`,
  o:[
    { l:'① 번진 방향을 거슬러 읽는다.', k:'gaze', dc:21,
      ok:`잉크는 물을 따라 아래로 번진다. 번진 끝이 아니라 번지기 시작한 자리를 봤다. 획이 제일 진한 데가 처음 쓴 자리다.<br><br>진한 점만 이었다. 『오른쪽 셋째 문. 손잡이 말고 경첩 쪽을 밀 것.』<br>오른쪽 셋째 문 경첩 쪽을 밀었다. 열렸다. 손잡이에는 철사가 감겨 있었다.<br><br>글자가 사라진 자리에서 글자를 읽었다. 남은 것이 아니라 번져 간 길을 읽는 눈. 이제 젖은 종이가 무섭지 않다.`,
      ng:`번진 끝을 따라 읽었다. 『오지 말 것』으로 읽혔다.<br><br>멈칫한 사이 발소리가 모퉁이를 돌았다. 쪽지를 쥔 채 뛰었다. 젖은 바닥에 무릎부터 떨어졌다.<br>쪽지는 손안에서 죽처럼 뭉개졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 }, wake:1 },
    { l:'② 쪽지를 맨살에 붙여 체온으로 말린다.', k:'steady', dc:20,
      ok:`쪽지를 셔츠 안쪽 맨살에 붙였다. 차다. 숨을 고르며 기다렸다.<br><br>체온에 종이가 마르면서 번진 잉크가 조금 가라앉는다. 두 마디가 읽혔다. 『경첩 쪽』. 『철사』.<br><br>그 두 마디로 충분했다. 손잡이는 안 잡았다.`,
      ng:`기다리는 동안 발소리가 다가왔다. 숨을 멈추고 벽에 붙었다.<br><br>오래 참았다. 지나간 뒤 꺼내 보니 종이가 땀에 젖어 더 번졌다.<br>손잡이를 잡았다. 철사가 손바닥을 갈랐다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-12 } },
    { l:'③ 쪽지는 버리고 문을 하나씩 만져 본다.', k:'sense', dc:20,
      ok:`문마다 손등을 대 봤다. 셋째 문 손잡이만 유난히 차다. 쇠가 한 겹 더 감겼다.<br><br>손잡이를 피하고 문짝을 어깨로 밀었다. 경첩 쪽이 헐겁다.<br>쪽지 없이도 문은 말을 한다. 다만 늦게 한다.`,
      ng:`첫 문을 만지는 순간 문 너머에서 누가 같이 손잡이를 쥐었다.<br><br>당긴다. 손을 뺐다. 손톱 하나가 문틈에 남았다.<br>쪽지는 발밑 물웅덩이에서 마저 녹았다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-26, mind:-10 } }
  ] },

{ at:'B', t:'담벼락 — 겹겹이 붙은 전단',
  x:`벽에 종이가 겹겹이 붙었다. 사람 찾는 전단이다.<br><br>
    맨 위 것은 오늘 붙였다. 풀이 아직 하얗다. 비에 가장자리가 들렸다.<br>
    그 밑에 어제 것, 그 밑에 그제 것. 손톱으로 들추면 날짜가 한 장씩 거슬러 간다.<br><br>
    맨 위 전단의 사진이 흐리다. 옷 색이 일행 하나와 같다.`,
  o:[
    { l:'① 한 장씩 들춰 날짜를 맞춘다.', k:'gaze', dc:20,
      ok:`들췄다. 전단마다 찾는 사람이 다르다. 붙인 간격은 같다. 하루에 한 장.<br><br>연락처가 다 같다. 한 번호. 찾는 게 아니라 세는 것이다. 하루에 하나씩 데려간 것을.<br>번호 밑에 작게 『사례함』. 사례는 데려온 사람이 받는다.<br><br>맨 위 전단을 떼어 뒤집어 붙였다. 흰 뒷면이 비를 맞는다. 오늘 몫은 아직 안 찼다.`,
      ng:`들추다 젖은 종이가 손에 감겼다. 서른 장이 한꺼번에 벗겨져 내렸다.<br><br>종이 쏟아지는 소리가 이렇게 크다.<br>골목 끝 창문 하나에 불이 켜졌다. 누가 내려다본다. 오래.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-12 } },
    { l:'② 맨 위 전단만 뜯어 품에 숨긴다.', k:'hide', dc:20,
      ok:`뜯어서 접어 품에 넣었다. 사진이 안쪽으로 가게.<br><br>벽에는 어제 날짜가 맨 위가 됐다. 오늘 붙인 사람은 다시 와야 한다.<br>그 사람이 다시 오는 동안 이쪽은 멀어진다.`,
      ng:`뜯는데 풀이 덜 말라 반이 벽에 남았다. 사진 쪽 반이.<br><br>얼굴만 남은 전단이 비를 맞는다. 누구 얼굴인지 더 잘 보인다.<br>길 건너에서 누가 그 얼굴과 이쪽 일행을 번갈아 본다. 그리고 뛰어온다.`,
      win:{ exp:14, spirit:5 }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B', t:'차양 밑 — 계약서',
  x:`차양 밑에 남자가 서 있다. 젖지 않았다. 서류 한 장을 내민다.<br><br>
    「여기 이름만 쓰면 나가는 길을 알려 드리지.」 펜도 내민다. 뚜껑이 열려 있다.<br>
    서류에는 큰 글씨 다섯 줄, 작은 글씨 스무 줄. 작은 글씨는 빗방울보다 작다.<br><br>
    학자는 큰 글씨를 안 믿는다. 큰 글씨는 읽으라고 쓴 것이다.`,
  o:[
    { l:'① 작은 글씨를 끝까지 읽는다.', k:'gaze', dc:21,
      ok:`남자가 시계를 본다. 상관하지 않고 읽었다. 열일곱째 줄에서 멈췄다.<br><br>『갑은 을의 출구를 보장한다. 단, 을의 정의는 별지에 따른다.』 별지는 없다. 을이 누구인지는 남자가 나중에 정한다.<br>「별지를 주시오.」 남자 입꼬리가 내려갔다. 「깐깐하시네.」 그가 길 하나를 그냥 가리켰다. 서명 없는 쪽이 싸게 먹힌다는 듯이.<br><br>계약은 쓴 글자보다 빠진 글자에서 무서워진다. 빠진 칸을 먼저 찾는 눈이 이번에는 손보다 먼저 움직였다.`,
      ng:`열 줄째에서 빗방울이 글자 위에 떨어졌다. 『아니한다』가 『한다』로 번졌다.<br><br>어느 쪽이었는지 모른다. 남자가 서류를 거둬들였다. 「시간 끝.」<br>그의 뒤에서 젖은 사람 둘이 나왔다. 피하다 어깨를 담벼락에 갈았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 서명란에 지어낸 이름을 적는다.', k:'luck', dc:21,
      doom:{ title:'서명', what:'계약대로 끌려갑니다', dc:17, sec:55,
        text:`펜을 받아 아무 이름이나 적었다. 지어낸 이름이다.<br><br>남자가 서류를 들어 본다. 웃는다. 「이 이름 맞소. 우리 명단에 있소.」<br>젖은 사람 둘이 양팔을 잡는다. 셋째 줄 큰 글씨에 그렇게 쓰여 있었다. 『서명자는 인도된다.』<br><br>발이 바닥에서 뜬다. 차양 밖, 빗속으로.`,
        dieText:`차양 밑에 남자가 서 있다. 젖지 않았다.<br><br>서류 한 장을 내민다. 서명란에 이름이 하나 적혀 있다. 지어낸 이름이다.<br>다음 사람은 그 이름을 지어낼 필요가 없다.` },
      ok:`지어낸 이름을 적었다. 획을 일부러 흐리게.<br><br>남자가 서류를 비에 비춰 본다. 읽히지 않는다. 「다시 쓰시오.」 「펜이 안 나오는데.」 펜을 돌려주었다. 뚜껑을 닫아서.<br>남자가 펜을 흔드는 사이 차양 옆 골목으로 빠졌다. 서명은 끝내 안 됐다. 안 된 서명으로는 아무도 못 끌고 간다.`,
      win:{ exp:20, dream:3 } },
    { l:'③ 펜을 받지 않고 지나친다.', k:'evade', dc:20,
      ok:`고개만 숙여 보이고 지나쳤다. 남자는 따라오지 않았다.<br><br>계약하는 자는 쫓지 않는다. 쫓으면 계약이 아니니까.<br>대신 뒤에서 휘파람이 길게 났다. 누구를 부르는 소리다. 걸음을 빨리했다.`,
      ng:`지나치는데 남자가 펜 끝으로 이쪽 소매를 찍었다.<br><br>잉크 한 점. 빗물에 안 지워진다.<br>그 뒤로 모퉁이마다 누가 소매를 보고 고개를 돌렸다. 뛰다가 발목을 접질렸다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'벽시계 — 두 개의 시각',
  x:`벽에 시계가 둘 걸렸다. 하나는 세 시 십 분, 하나는 세 시 사십 분.<br><br>
    둘 다 간다. 초침이 똑같이 돈다. 삼십 분이 처음부터 벌어져 있다.<br>
    나가는 문은 정해진 시각에 닫힌다고 적혀 있다. 어느 시계로 정하는지는 안 적혀 있다.<br><br>
    삼십 분이면 사는 쪽과 못 사는 쪽이 갈린다.`,
  o:[
    { l:'① 시계 말고 다른 것으로 시각을 잰다.', k:'gaze', dc:21,
      ok:`창밖을 봤다. 처마에서 떨어지는 물을 받쳐 둔 양동이가 있다. 어디나 양동이가 있다.<br><br>물 높이와 떨어지는 박자로 셈했다. 양동이는 자정에 비웠을 것이다. 비우는 사람은 정시에 비운다. 그러면 지금은 세 시 사십 분 쪽이다.<br>쉬려던 걸 그만두고 일어섰다. 다들 투덜댔다.<br><br>문에 닿았을 때 문은 반쯤 닫혀 있었다.`,
      ng:`양동이 셈을 하다 숫자를 놓쳤다. 두 번 셌는데 두 번 다르다.<br><br>세 시 십 분 쪽을 믿었다. 앉아서 숨을 골랐다.<br>문 닫히는 소리가 생각보다 일찍 났다. 다른 길로 돌았다. 다리가 풀릴 때까지 뛰었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 빠른 시계를 믿고 바로 떠난다.', k:'steady', dc:20,
      ok:`빠른 쪽을 믿었다. 틀려도 일찍 닿는 쪽이 낫다.<br><br>숨도 안 고르고 걸었다. 문에 닿았다. 열려 있다.<br>한참 기다렸다. 기다리는 동안 늦은 시계 쪽 복도에서 누가 이쪽을 찾는 소리가 났다. 문은 이쪽이 지난 뒤에 닫혔다.`,
      ng:`서둘러 걷다 계단에서 헛디뎠다.<br><br>정강이가 모서리에 찍혔다. 일어서는 데 숨 열이 걸렸다.<br>빠른 시계를 믿어도 다리가 느리면 소용없다.`,
      win:{ exp:15, hp:6 }, lose:{ hp:-26, spirit:-10 } }
  ] },

{ at:'B', t:'젖은 바닥 — 떨어진 수첩',
  x:`바닥에 수첩이 떨어져 있다. 검은 가죽. 고무줄로 묶였다.<br><br>
    쫓아오는 쪽이 흘린 것이다. 방금 지나간 자리다.<br>
    펴 보니 숫자만 적혔다. 줄마다 넷, 둘, 넷, 둘. 가끔 하나.<br><br>
    숫자가 무엇을 세는지 모르면 학자는 잠을 못 잔다. 오늘은 잘 생각도 없다.`,
  o:[
    { l:'① 숫자가 무엇을 세는지 푼다.', k:'gaze', dc:22,
      ok:`줄마다 끝에 작은 점이 있다. 점 개수와 숫자를 나란히 놓았다. 넷 둘 넷 둘. 걸음이다. 네 걸음 걷고 두 번 멈춘다.<br><br>쫓는 쪽은 이쪽 걸음을 적었다. 언제 멈추고 언제 서두르는지. 가끔 있는 하나는 누가 넘어진 자리다.<br>박자를 바꿨다. 셋, 하나, 다섯. 일행에게도 그렇게 걷게 했다. 등 뒤 발소리가 처음으로 헛디뎠다.<br><br>남이 적은 것을 읽으면 적은 손이 읽힌다. 기록 너머의 손을 보는 법이 하나 몸에 붙었다.`,
      ng:`숫자를 풀다 수첩을 너무 오래 들고 있었다.<br><br>고무줄 튕기는 소리. 이쪽이 낸 소리가 아니다. 바로 뒤다.<br>수첩을 던지고 뛰었다. 뒤통수에 무언가 스쳤다. 머리카락이 한 움큼 뽑혔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-25, mind:-14 }, wake:1 },
    { l:'② 펴 본 흔적 없이 제자리에 둔다.', k:'hide', dc:19,
      ok:`고무줄을 원래 감긴 대로 감았다. 두 번 반. 떨어진 각도 그대로 내려놓았다.<br><br>숨어서 기다렸다. 주인이 돌아와 수첩을 줍는다. 펴 보지 않는다.<br>의심하지 않는 자는 다음 장을 바꾸지 않는다. 이쪽은 그가 적던 박자를 안다.`,
      ng:`고무줄을 한 바퀴 덜 감았다.<br><br>주인이 주워 들다 멈췄다. 고무줄을 본다. 오래.<br>그가 둘레를 돌며 손전등을 비췄다. 빛이 눈을 찔렀다. 굴러서 나왔다. 팔꿈치가 깨졌다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, spirit:-12 } },
    { l:'③ 마지막 장만 찢어 간다.', k:'luck', dc:20,
      ok:`쓴 장 맨 끝을 찢었다. 오늘 날짜가 적힌 장이다.<br><br>찢긴 자리는 표가 안 나게 고무줄 밑으로 갔다.<br>찢어 온 장 뒷면에 약도가 그려져 있다. 쫓는 쪽이 서는 자리들. 거기만 피하면 된다.`,
      ng:`종이가 젖어 소리 없이 찢기지 않았다. 반쯤 붙은 채 늘어졌다.<br><br>그대로 두고 갔다. 주인은 찢긴 장을 볼 것이다.<br>그 뒤로 발소리가 박자를 바꿨다. 이쪽이 모르는 박자로.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B', t:'복도 — 젖은 대피도',
  x:`벽 판자에 대피도가 압정으로 꽂혔다.<br><br>
    천장 물이 떨어져 반이 번졌다. 빨간 화살표가 녹아 흘렀다.<br>
    오른쪽 아래 범례와 축척 막대는 멀쩡하다. 사람들은 그 칸을 안 본다.<br><br>
    『현 위치』 빨간 점만 또렷하다. 거기가 여기다.`,
  o:[
    { l:'① 범례와 축척으로 길을 다시 그린다.', k:'gaze', dc:20,
      ok:`축척 막대로 손가락 마디를 쟀다. 한 마디가 열 걸음.<br><br>번진 선은 버리고 남은 기호만 이었다. 소화전, 계단, 소화전. 소화전은 규정대로 일정한 간격에 둔다. 간격이 빈 데가 막힌 벽이다.<br>손가락으로 길을 그어 일행에게 보였다. 그대로 갔다. 그대로였다.`,
      ng:`축척 단위를 잘못 읽었다. 열 걸음이라 했던 데가 서른 걸음이었다.<br><br>그 사이 불이 꺼졌다.<br>어둠 속에서 벽에 이마를 찧었다. 일행 하나는 발목을 삐었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 도면은 버리고 바람이 오는 쪽으로 간다.', k:'sense', dc:20,
      ok:`도면을 등지고 섰다. 목덜미에 찬 바람이 닿는다. 바깥 공기다.<br><br>그쪽으로 걸었다. 도면은 그린 사람이 아는 길이다. 바람은 지금 열린 길이다.<br>바람 끝에 쪽창이 하나 열려 있다. 창틀 홈에 빗물이 맑게 고였다. 반가운 비다.`,
      ng:`바람을 따라갔는데 바람이 돈다. 환기구에서 나오는 바람이다.<br><br>환기구 앞은 막다른 벽이다. 돌아 나오다 발밑 물에 미끄러졌다.<br>꼬리뼈부터 떨어졌다. 한참 일어나지 못했다.`,
      win:{ exp:15, item:'맑은 물' }, lose:{ hp:-25, spirit:-10 } }
  ] },

{ at:'B', t:'책상 — 찢겨 나간 장',
  x:`책상 위에 메모장이 있다. 맨 윗장이 찢겨 나갔다. 급하게. 가장자리가 들쭉날쭉하다.<br><br>
    아랫장은 비었다. 그런데 비스듬히 비추면 눌린 자국이 보인다. 윗장에 꾹꾹 눌러 쓴 자국.<br>
    옆에 몽당연필이 하나 있다.<br><br>
    복도 끝에서 문이 하나씩 열렸다 닫힌다. 차례로. 이쪽으로 오면서.`,
  o:[
    { l:'① 연필심을 눕혀 비벼 자국을 띄운다.', k:'gaze', dc:21,
      ok:`연필심을 눕혀 살살 비볐다. 회색 바탕에 하얀 글씨가 떠오른다.<br><br>『04:00 뒷문 열림 — 3분』. 그 밑에 『사람 수 확인 후 잠금』.<br>시각을 읽고, 눌림의 깊이를 읽었다. 『3분』만 유난히 깊다. 쓴 사람이 거기에 힘을 줄 만큼 짧다고 여겼다.<br><br>빈 종이에서 사라진 종이를 읽었다. 이제 흰 장이 흰 장으로 안 보인다. 눌린 데, 비벼진 데, 지운 데가 먼저 눈에 걸린다.`,
      ng:`너무 세게 비볐다. 연필심이 부러지며 자국 위를 까맣게 덮었다.<br><br>『04』까지만 보였다. 네 시인지 사 분인지 모른다.<br>문 열리는 소리가 옆방까지 왔다. 책상 밑에 들어가 숨을 너무 오래 참았다. 머리가 깨질 것 같다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-15, spirit:-12 }, wake:1 },
    { l:'② 휴지통에서 찢겨 나간 장을 찾는다.', k:'luck', dc:20,
      ok:`휴지통을 뒤졌다. 구겨진 종이가 열 장쯤이다. 찢긴 가장자리가 맞는 것이 하나 있다.<br><br>펴 보니 같은 메모를 두 번 썼다. 한 번 틀려서 버린 것이다. 틀린 쪽에는 시각이 하나 더 적혀 있다.<br>버린 종이에 더 많이 적혀 있는 법이다.`,
      ng:`휴지통 바닥에서 무언가 찔렀다. 깨진 유리다.<br><br>손바닥이 갈라졌다. 피가 종이들에 번졌다.<br>찾던 장은 없었다. 누가 먼저 가져갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'쇠문 — 규정 제7조',
  x:`두꺼운 쇠문이 천천히 닫힌다. 모터 소리. 한 뼘에 숨 셋.<br><br>
    문 옆에 안내판이 붙었다. 『규정 제7조 3항에 따라 본 문은 자동 폐쇄됩니다.』<br>
    그 밑에 규정 전문이 깨알같이 붙어 있다. 아무도 안 읽은 종이다. 테이프가 누렇게 떴다.<br><br>
    문 너머가 나가는 쪽이다. 문 이쪽으로 발소리가 온다.`,
  o:[
    { l:'① 제7조 3항 단서를 찾아 읽는다.', k:'gaze', dc:21,
      ok:`7조 3항을 찾았다. 『단, 문틀 감지기가 물체를 인식할 경우 폐쇄를 중지하고 재개방한다.』<br><br>감지기는 문틀 아래 손바닥만 한 눈이다. 거기에 젖은 장갑을 던졌다. 문이 멈칫하더니 다시 열린다.<br>규정을 만든 사람은 사람이 끼일 걸 알았다. 그래서 단서를 달았다. 단서는 늘 맨 끝에 있다.`,
      ng:`깨알 글씨를 읽다 7조가 아니라 1조 7항을 읽었다. 쓸데없는 줄이다.<br><br>문은 이미 반이 닫혔다. 억지로 몸을 들이밀었다.<br>어깨가 문짝에 눌렸다. 빠져나오기는 했다. 어깨가 한참 안 올라간다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 문틈에 제일 두꺼운 책을 끼운다.', k:'fix', dc:20,
      ok:`가방에서 제일 두꺼운 책을 꺼냈다. 아끼던 책이다. 문틈 바닥에 세웠다.<br><br>문이 책을 물었다. 모터가 운다. 책등이 우그러진다. 그래도 한 뼘이 남았다.<br>일행이 하나씩 기어 나갔다. 책은 빼 오지 못했다. 거기서 끝까지 버텼다.`,
      ng:`책을 세웠는데 문이 책을 밀고 간다.<br><br>책이 넘어졌다. 다시 세우려다 손가락이 문짝에 물렸다.<br>빼냈다. 손톱 둘이 까맣다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-25, spirit:-12 } },
    { l:'③ 닫히기 전에 뛰어든다.', k:'evade', dc:21,
      doom:{ title:'닫히는 문', what:'쇠문 사이에 끼었습니다', dc:17, sec:50,
        text:`뛰었다. 문틈이 어깨 너비다.<br><br>몸을 옆으로 틀었다. 가방끈이 문틀에 걸렸다. 반은 이쪽, 반은 저쪽.<br>모터가 운다. 문짝이 갈비뼈를 누른다. 숨이 반만 들어간다.<br><br>규정에는 감지기가 있다고 했다. 감지기는 무릎 아래만 본다.`,
        dieText:`쇠문이 끝까지 닫혔다. 모터 소리가 멎는다.<br><br>문 아래로 가방끈 한 가닥이 삐져나와 있다.<br>다음 날 안내판에 종이가 하나 더 붙는다. 『제7조 4항 신설』.` },
      ok:`뛰었다. 가방을 먼저 던졌다. 몸을 옆으로 세웠다.<br><br>문짝이 등을 스쳤다. 빠졌다. 등 뒤에서 문이 끝까지 닫혔다. 쿵.<br>문 너머에서 발소리가 문에 닿아 멈췄다. 규정은 저쪽도 지킨다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'B1', t:'경매장 사무실 — 장부 한 권',
  x:`붉은 네온이 번진 사무실, 책상 위에 장부가 있다. 우산 쓴 남자가 가져오라던 그 한 권이다.<br><br>
    가죽 표지가 기름에 절었다. 펴면 숫자가 빽빽하다. 들어온 상자, 나간 상자, 받은 돈.<br>
    학자는 장부를 펴면 끝까지 맞춰야 직성이 풀린다. 가져가기만 하면 되는 일인데도.<br><br>
    전화가 운다. 열두 번 울고 멎었다가 다시 운다. 벽시계가 한 칸 넘어간다.`,
  o:[
    { l:'① 들어온 쪽과 나간 쪽을 끝까지 맞춘다.', k:'gaze', dc:21,
      ok:`맞췄다. 상자는 맞는다. 돈이 안 맞는다. 매달 같은 날, 같은 금액이 비어 있다.<br><br>빈 금액 옆에 이름 대신 그림이 하나 있다. 우산.<br>그 밑 줄은 오늘 날짜다. 『3번 창고 정리 — 다섯 — 선불 완료』. 정리할 것은 장부가 아니다. 장부를 가지러 올 다섯이다.<br><br>장부를 덮었다. 손이 떨리지 않았다. 숫자가 안 맞는 자리에 사람이 숨어 있다. 그 줄을 짚는 손가락이 처음부터 그 자리에 가 있었다.`,
      ng:`맞추다 페이지를 하나 건너뛰었다. 다시 처음부터.<br><br>세 번째로 맞추는데 철계단에서 고무장화 소리가 났다. 뽀득.<br>책상 밑으로 들어갔다. 소리가 문 앞에서 오래 머물렀다. 기침을 참다 입술을 깨물었다. 피 맛이 났다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-15 }, wake:1 },
    { l:'② 장부를 통째로 품에 넣고 나간다.', k:'hide', dc:20,
      ok:`장부를 외투 안에 넣었다. 단추를 끝까지 잠갔다.<br><br>무겁다. 숫자는 무겁다. 걸을 때마다 가슴을 친다.<br>읽는 건 나중이다. 나가서 읽어도 숫자는 안 바뀐다. 불을 끄고 나왔다. 아무도 못 봤다.`,
      ng:`품에 넣는데 장부 사이에서 무언가 떨어졌다. 열쇠다. 쨍그랑.<br><br>계단 아래 소리가 멎었다. 그리고 올라온다.<br>창으로 나갔다. 젖은 차양에서 미끄러져 옆구리로 떨어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 오늘 장만 외우고 장부는 둔다.', k:'steady', dc:21,
      ok:`오늘 날짜 장을 세 번 읽었다. 눈을 감고 한 번 더 읽었다. 머릿속에서.<br><br>장부는 원래대로 덮어 두었다. 가져가면 가져간 줄 안다. 두고 가면 아직 아무도 안 온 줄 안다.<br>외운 것은 아무도 못 빼앗는다. 무겁기는 똑같다.`,
      ng:`외우는 동안 시계가 두 칸 넘어갔다.<br><br>세 번 읽은 것이 네 번째에 엉켰다. 숫자 하나가 자꾸 다른 숫자로 바뀐다.<br>전화벨이 멎었다. 그 대신 철계단이 울린다. 뛰었다. 계단 모서리에 무릎을 찧었다.`,
      win:{ exp:18, mind:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'수로 — 물때표의 빨간 줄',
  x:`벽에 물때표가 붙었다. 다섯 시 십 분 만조에 빨간 줄.<br><br>
    방파제 밑 배수 수로로 가면 정문까지 안 보이고 간다. 다만 밀물이 수로를 채운다.<br>
    표를 읽을 줄 안다. 만조와 간조 사이 물은 고르게 오르지 않는다. 처음과 끝은 느리고 가운데가 빠르다.<br><br>
    지금은 두 시 반이다. 수로 입구 물이 정강이에 찰랑인다.`,
  o:[
    { l:'① 물 오르는 셈을 맞춰 수로에 든다.', k:'gaze', dc:21,
      doom:{ title:'밀물', what:'수로에 물이 천장까지 찼습니다', dc:17, sec:55,
        text:`셈대로라면 세 시 반까지는 가슴이다. 그렇게 믿고 들어갔다.<br><br>물이 허리에서 가슴으로, 가슴에서 목으로 오른다. 셈보다 빠르다. 비다. 빗물이 강을 불렸고 강물이 수로로 거꾸로 밀려든다.<br>표에는 비가 없었다. 천장 판자와 수면 사이가 한 뼘. 반 뼘.<br><br>판자 틈으로 손가락을 넣었다. 숨 한 모금이 남았다.`,
        dieText:`밀물이 빠졌다. 수로 바닥에 진흙이 고르게 깔렸다.<br><br>쇠창살에 걸린 그물에 무언가 하나 더 걸려 있다.<br>물때표는 그대로다. 비 오는 날 칸은 없다.` },
      ok:`표의 셈에 비를 더했다. 처마 물이 떨어지는 박자로 빗물을 어림했다. 삼십 분을 깎았다.<br><br>세 시까지만 수로에 있었다. 세 시에 쇠창살 앞 사다리로 올라왔다. 내려다보니 물이 방금 있던 자리를 넘어 판자 밑까지 찼다.<br>표는 바다를 적는다. 하늘은 읽는 쪽이 보태야 한다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 수로 대신 판자 위 그늘로 숨어 간다.', k:'hide', dc:20,
      ok:`부두 판자 위로 갔다. 컨테이너 그늘에서 그늘로.<br><br>탐조등이 지나갈 때마다 바닥에 붙었다. 판자 틈으로 아래 수로가 보인다. 물이 빠르게 오른다. 저기 있었으면.<br>젖은 판자에 배를 대고 기었다. 배가 얼었다. 대신 숨은 쉬었다.`,
      ng:`그늘 사이가 생각보다 넓다. 건너는 순간 탐조등이 멈췄다.<br><br>하얀 빛 한가운데 섰다. 호루라기 소리.<br>판자 틈으로 수로에 뛰어내렸다. 물이 가슴까지 찼다. 기어 나오는 데 한참 걸렸다. 손톱이 판자에 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 『한 시간』',
  x:`냉동 창고 안이다. 문은 밖에서만 열린다. 온도계는 영하 이십 도.<br><br>
    문 안쪽에 누가 손톱으로 그어 놓았다. 『한 시간.』<br>
    책에서 읽었다. 이 추위에 젖은 옷이면 손끝이 먼저 가고, 그다음 말이 느려지고, 그다음 졸음이 온다. 졸음이 오면 끝이다.<br><br>
    다들 비에 젖었다. 벌써 일행 하나 말이 느리다.`,
  o:[
    { l:'① 몸이 무너지는 순서를 셈해 시간을 다시 잰다.', k:'gaze', dc:20,
      ok:`『한 시간』은 마른 옷 기준이다. 젖은 옷이면 절반이다. 삼십 분.<br><br>말이 느린 사람을 가운데 세우고 넷이 둘러섰다. 젖은 겉옷은 벗겨 걸었다. 젖은 천은 몸보다 빨리 언다.<br>매달린 고기 사이에서 얼어붙은 짐승 고기 한 덩이를 떼어 품에 넣었다. 나가면 먹는다. 나갈 수 있으면.<br><br>이십오 분째에 밖에서 문이 열렸다. 지게차가 짐을 넣으러 왔다. 그 틈으로 빠졌다.`,
      ng:`셈은 맞았다. 다만 이쪽 손이 먼저 갔다.<br><br>손가락이 안 굽는다. 고기 갈고리를 붙잡았다가 살갗이 쇠에 붙었다. 떼어 내며 피가 났다. 피가 바로 얼었다.<br>문이 열렸을 때 이쪽 혀가 굳어 일행을 부르지 못했다.`,
      win:{ exp:18, item:'짐승 고기' }, lose:{ hp:-28, mind:-12 } },
    { l:'② 냉각기 뒤 온기를 찾아 고기 사이로 숨는다.', k:'sense', dc:21,
      ok:`냉각기는 안을 차게 하는 대신 뒤로 열을 뱉는다. 기계는 그렇게 생겼다.<br><br>고기 사이를 지나 안쪽 벽으로 갔다. 냉각기 뒤 틈이 미지근하다. 다섯이 다 들어가지는 못한다. 셋씩 번갈아 들어갔다.<br>말이 느리던 사람이 먼저 몸을 녹였다. 말이 다시 빨라졌다. 투덜거릴 만큼.`,
      ng:`냉각기 뒤로 가다 레일이 움직였다. 매달린 고기가 한 칸씩 밀려온다.<br><br>얼어붙은 고기 덩이가 어깨를 쳤다. 돌처럼 단단하다.<br>쓰러진 채 한참 못 일어났다. 바닥이 등에서 열을 빨아 갔다.`,
      win:{ exp:16, hp:8 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B1', t:'쪽문 밖 — 양동이 순서',
  x:`쪽문 옆에 양동이와 대걸레가 놓였다. 물이 아직 따뜻하다.<br><br>
    양동이 옆에 세제 통이 셋 서 있다. 라벨이 반듯하게 앞을 본다. 산성 세정제, 표백제, 맹물.<br>
    통마다 『섞지 마시오』. 쓰는 사람은 그 말을 지킨다. 지키는 사람은 순서가 있다.<br><br>
    골목 끝 손전등이 바닥을 훑는다. 뽀득, 뽀득.`,
  o:[
    { l:'① 세제 통의 줄어든 양으로 청소한 곳을 읽는다.', k:'gaze', dc:21,
      ok:`산성 통은 거의 비었다. 표백제는 반. 맹물은 그대로.<br><br>산성은 기름과 녹을 먼저 벗긴다. 표백제는 그다음, 남은 것을 지운다. 맹물로 헹구면 끝이다. 이 사람은 헹구지 않은 곳이 반이다.<br>표백제 냄새가 짙은 쪽은 이미 끝난 곳이다. 끝난 곳에는 다시 안 온다. 일하는 사람은 지운 데를 다시 밟지 않는다.<br><br>일행을 표백제 냄새 나는 쪽으로 이끌었다. 손전등은 반대쪽에서 돌았다. 남이 쓰는 물건의 줄어든 양에서 그 사람의 하루를 읽는다. 이 밤에는 그게 지도가 됐다.`,
      ng:`통을 기울여 양을 보다가 뚜껑이 굴러떨어졌다.<br><br>플라스틱 뚜껑이 골목 돌바닥을 굴러간다. 손전등이 멈췄다. 그리고 이쪽을 향했다.<br>쪽문 안으로 뛰어들다 문틀에 이마를 박았다. 눈앞이 하얗다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 양동이를 엎어 물자국을 흐린다.', k:'break', dc:20,
      ok:`양동이를 발로 찼다. 따뜻한 물이 골목 바닥에 퍼졌다.<br><br>대걸레가 그어 둔 줄이 지워졌다. 이 사람은 줄을 보고 다닌다. 지운 데와 안 지운 데를.<br>손전등이 멈춰 바닥을 오래 비췄다. 그 사이 반대쪽으로 빠졌다.`,
      ng:`찼는데 양동이가 무겁다. 물만 든 게 아니다.<br><br>엎어지지 않고 덜컹 소리만 났다. 손전등이 바로 이쪽을 찾았다.<br>뛰었다. 등 뒤에서 무언가 날아와 종아리를 쳤다. 대걸레 자루였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 대걸레 자국을 밟지 않고 골목을 지난다.', k:'evade', dc:20,
      ok:`젖은 자국은 피하고 마른 돌만 밟았다. 한 칸씩, 건너뛰며.<br><br>자국을 밟으면 자국이 남는다. 이 사람은 그걸 본다.<br>골목 끝까지 갔다. 뒤를 보니 대걸레 줄이 하나도 안 흐트러졌다. 아무도 안 지나간 골목이다.`,
      ng:`마른 돌이 생각보다 미끄럽다. 기름이 배어 있었다.<br><br>미끄러지며 대걸레 줄 한가운데 손을 짚었다. 손바닥 자국이 선명하다.<br>손전등이 그 자국에 멈췄다. 숨어 있는 내내 표백제가 손바닥을 태웠다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'간호사실 — 차트의 약어',
  x:`간호사실 책상에 차트가 꽂혀 있다. 침대 번호순이다.<br><br>
    이쪽 침대 번호 차트를 뽑았다. 이름 칸에는 처음 보는 이름. 처방 칸에는 약어가 줄줄이 적혔다.<br>
    약어는 아는 사람만 읽으라고 쓴다. 학자는 그런 글을 제일 좋아한다.<br><br>
    유리 너머 복도 끝에서 딸깍 소리가 다가온다.`,
  o:[
    { l:'① 약어를 풀어 처방을 읽는다.', k:'gaze', dc:21,
      ok:`하나씩 풀었다. 『정각마다』. 『인원 대조』. 『불일치 시 진정 후 재계수』.<br><br>재계수. 다시 센다는 뜻이다. 진정시킨 다음에. 세는 동안 움직이지 않게.<br>맨 아래 줄 약어가 낯설다. 앞 차트들을 넘겨 같은 약어를 찾았다. 퇴원한 사람 차트에만 있다. 퇴원 날짜 옆에 『보관실 이관』.<br><br>차트를 원래 칸에 꽂았다. 이 층에서 나가는 길은 보관실을 지난다.`,
      ng:`약어 하나를 잘못 풀었다. 『재계수』를 『재검사』로 읽었다.<br><br>검사쯤이야 하고 침대로 돌아갔다. 정각에 간호사가 와서 이쪽 팔에 무언가를 놓았다.<br>한참 손발이 남의 것 같았다. 셀 때마다 고개만 끄덕였다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 처방 칸 한 줄을 지운다.', k:'fix', dc:21,
      ok:`볼펜을 들었다. 『진정 후』를 두 줄로 긋고 옆에 같은 글씨체로 『관찰』을 적었다.<br><br>남의 글씨를 흉내 내는 건 남의 글을 오래 읽은 사람이 잘한다.<br>정각에 간호사가 차트를 봤다. 고개를 갸웃했다. 그리고 그냥 셌다. 계수기만 눌렀다.`,
      ng:`긋는 줄이 한 줄이었다. 두 줄로 그어야 정정이다. 한 줄은 낙서다.<br><br>간호사가 차트를 보고 계수기를 내려놓았다. 낙서한 사람을 찾는다.<br>다들 침대에 누워 눈을 감았다. 이쪽 침대 옆에서 간호사가 오래 서 있었다. 숨소리를 세는 것 같았다.`,
      win:{ exp:18, spirit:6 }, lose:{ mind:-14, spirit:-14 } },
    { l:'③ 차트는 두고 약장 이름표를 훑는다.', k:'sense', dc:20,
      ok:`약장 칸마다 이름표가 붙었다. 대부분 읽을 필요 없는 약이다.<br><br>맨 아래 칸 이름표만 손글씨다. 『환자 개인 물품 — 반환 대기』. 열자 종이봉투가 있다. 말린 풀 냄새.<br>누가 들고 들어왔다가 못 받아 간 약초 뭉치다. 대신 받아 간다.`,
      ng:`약장 문이 삐걱했다. 작은 소리였다.<br><br>복도의 딸깍 소리가 멈췄다. 방향을 바꾼다.<br>책상 밑에 웅크렸다. 무릎이 바닥에 오래 눌려 저렸다. 일어서다 휘청해 모서리에 옆머리를 찧었다.`,
      win:{ exp:15, item:'약초 뭉치' }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B2', t:'기록 보관실 — 분류 번호',
  x:`서가가 바닥 레일 위에 붙어 섰다. 손잡이를 돌리면 옆으로 밀려 통로가 열린다.<br><br>
    서가 옆구리마다 분류 번호가 붙었다. 숫자, 점, 숫자. 아는 체계다. 학자는 도서관에서 자랐다.<br>
    이쪽 일행 이름이 적힌 기록철이 어딘가에 있다. 아침이면 세단기로 간다.<br><br>
    열린 통로는 하나뿐이다. 레일 위에 슬리퍼 한 짝이 반쯤 납작하게 끼어 있다.`,
  o:[
    { l:'① 분류 번호를 따라 일행의 철을 찾아 뺀다.', k:'gaze', dc:22,
      doom:{ title:'움직이는 서가', what:'서가 사이에 끼었습니다', dc:17, sec:50,
        text:`번호를 거슬렀다. 입원 연도, 병동, 침대. 이 서가 셋째 칸이다.<br><br>손잡이를 돌려 통로를 열고 들어갔다. 철을 찾았다. 다섯 권. 품에 안았다.<br>등 뒤에서 손잡이 도는 소리가 난다. 이쪽이 안 돌렸다. 양쪽 서가가 천천히 다가온다.<br><br>통로가 어깨 너비가 됐다. 레일 위 슬리퍼가 왜 납작한지 알았다.`,
        dieText:`서가가 다 붙었다. 통로는 다시 하나만 열린다. 다른 데에.<br><br>아침에 직원이 셋째 칸 철을 찾으러 온다. 다섯 권이 없다.<br>대신 레일 위에 신발 한 짝이 끼어 있다. 반쯤 납작하게.` },
      ok:`번호를 거슬렀다. 입원 연도, 병동, 침대. 셋째 칸이다.<br><br>통로를 열기 전에 반대편 손잡이에 허리띠를 감아 묶었다. 서가는 손잡이로 움직인다. 손잡이가 묶이면 못 온다.<br>들어가 철 다섯 권을 뺐다. 나오는 사이 묶은 손잡이가 한 번 덜컥 당겨졌다. 저쪽에서 누가 돌리려 했다.<br><br>철은 환기구에 밀어 넣었다. 장부에서 빠질 것은 이쪽이 정한다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 철은 두고 열린 통로 끝까지만 간다.', k:'steady', dc:20,
      ok:`욕심을 버렸다. 열린 통로로만 걸었다. 끝 책상에 오늘 날짜 철이 쌓였다.<br><br>맨 위 철 표지만 읽었다. 이쪽 이름이 아니다. 7층 휴게실 노인 이름이다.<br>철을 들어 책상 밑에 밀어 넣었다. 하나라도 늦게 가면 늦게 찾으러 온다.`,
      ng:`통로 끝에 닿았는데 등 뒤 통로가 좁아졌다.<br><br>누가 손잡이를 돌린다. 뛰어서 빠져나왔다. 서가 모서리에 어깨가 찍혔다.<br>열린 통로가 하나 줄었다. 나머지는 다 닫혔다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B2', t:'점검 장부 — 늘 맞는 숫자',
  x:`독서대에 장부가 펼쳐졌다. 시각, 들어옴, 나감.<br><br>
    매 정각 한 줄씩. 수천 줄이다. 들어옴과 나감이 늘 같다. 한 줄도 어긋나지 않았다.<br>
    사람이 적은 숫자는 어긋난다. 안 어긋나는 숫자는 맞춰 놓은 숫자다.<br><br>
    오늘 밤 줄이 비었다. 볼펜 뚜껑이 열려 있다.`,
  o:[
    { l:'① 같아지는 까닭을 셈한다.', k:'gaze', dc:21,
      ok:`줄을 거슬러 올라갔다. 나감이 하나 늘면 같은 시각 들어옴도 하나 는다. 늘 같은 시각에.<br><br>누가 나가면 누가 들어온다. 들어온 사람은 나간 사람 침대에 눕는다. 침대 명패의 처음 보는 이름이 그래서 붙었다.<br>나가는 법은 둘이다. 대신 누울 사람을 남기거나, 장부가 셈을 마치기 전에 나가거나.<br><br>장부를 덮지 않았다. 덮으면 셈이 끝난다. 숫자가 맞는 까닭을 보면 숫자가 맞지 않게 할 틈도 보인다. 틈이 보이는 데까지 읽는 버릇이 오늘 생겼다.`,
      ng:`거슬러 올라가다 줄을 잃었다. 천 줄이 다 똑같이 생겼다.<br><br>눈이 시큰거린다. 줄이 겹쳐 보인다.<br>정신을 차리니 볼펜을 쥐고 있다. 오늘 밤 들어옴 칸에 무언가 적으려던 참이었다. 손목이 떨렸다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'② 오늘 밤 줄을 먼저 채워 둔다.', k:'fix', dc:21,
      ok:`볼펜을 들어 오늘 줄에 적었다. 들어옴 0, 나감 0. 시각은 다음 정각.<br><br>장부는 이미 적힌 줄을 다시 안 센다. 적힌 대로 믿는다.<br>정각이 됐다. 복도의 딸깍 소리가 이쪽 층을 건너뛰었다.`,
      ng:`0을 쓰는데 볼펜 잉크가 끊겼다. 동그라미가 반만 그려졌다.<br><br>반 동그라미는 6처럼 보인다.<br>정각에 딸깍 소리가 여섯 번 더 났다. 이쪽 일행 옆에서.`,
      win:{ exp:18, mind:6 }, lose:{ mind:-14, spirit:-16 } },
    { l:'③ 볼펜만 챙겨 간다.', k:'hide', dc:19,
      ok:`볼펜을 주머니에 넣었다. 뚜껑을 닫아서.<br><br>적을 것이 없으면 오늘 줄은 비어 있다. 빈 줄은 셈이 끝나지 않은 줄이다.<br>보관실을 나오는 동안 등 뒤에서 누가 독서대 둘레를 더듬는 소리가 났다.`,
      ng:`주머니에 넣는 순간 독서대 밑에서 손이 나와 손목을 잡았다.<br><br>차다. 볼펜을 쥔 손을 놓지 않는다.<br>볼펜을 놓고서야 풀렸다. 손목에 손가락 자국이 다섯 줄 남았다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B2', t:'한방 처치실 — 서랍의 이름',
  x:`벽 한 면이 작은 서랍이다. 서랍마다 한자로 약재 이름이 적혔다.<br><br>
    당귀, 감초, 박하. 아는 이름이다. 학자는 약초 도감을 끝까지 읽은 사람이다.<br>
    방 가운데 침술 인형이 여럿 서 있다. 세면 일곱, 다시 세면 여덟.<br><br>
    서랍 이름 가운데 하나가 약재 이름이 아니다. 사람 이름이다.`,
  o:[
    { l:'① 서랍 이름을 읽어 쓸 약재를 고른다.', k:'gaze', dc:20,
      ok:`약재 서랍만 골라 열었다. 박하, 감초, 말린 쑥. 한 줌씩 집어 손수건에 쌌다.<br><br>사람 이름 서랍은 안 열었다. 서랍 순서가 가나다순이 아니라 획순이다. 사람 이름이 끼어든 자리는 획수가 안 맞는다. 나중에 넣은 것이다.<br>읽을 줄 알면 열지 않아도 된다.`,
      ng:`급히 읽다가 획이 비슷한 두 글자를 헷갈렸다.<br><br>연 서랍에서 쓴 가루가 피어올랐다. 들이마셨다. 목이 타고 눈물이 쏟아진다.<br>기침 소리에 인형 하나가 이쪽으로 고개를 돌렸다.`,
      win:{ exp:16, item:'약초 뭉치' }, lose:{ hp:-22, mind:-14 } },
    { l:'② 인형 수가 바뀌는 까닭을 끝까지 센다.', k:'steady', dc:21,
      ok:`인형마다 몸에 그려진 점의 수를 셌다. 일곱 인형은 점이 같다. 여덟째만 점이 하나 모자란다.<br><br>그려진 점이 아니다. 단추 자국이다. 여덟째는 가운을 입고 섰다.<br>그쪽을 등지지 않고 뒷걸음으로 방을 나왔다. 문을 닫는 순간 안에서 침 꽂는 소리가 일곱 번 났다.`,
      ng:`세다 보니 아홉이다. 열이다.<br><br>세는 걸 멈추지 못했다. 열하나에서 누가 어깨를 짚었다. 일행이었다. 아니었을지도 모른다.<br>방을 나와서도 한참 손가락이 숫자를 접었다.`,
      win:{ exp:18, mind:6 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B3', t:'9호차 — 빈 종착역 칸',
  x:`객차 끝 문 위에 시간표가 붙었다. 역 이름 여섯 줄. 맨 아래 종착 04:44, 이름 칸은 비었다.<br><br>
    역마다 도착 시각만 있고 거리는 없다. 그래도 학자는 셈을 안다. 이음매 넘는 소리로 속도를 잰다. 덜컹 한 번이 레일 한 토막이다.<br>
    서지 않는 열차라도 굽은 데서는 느려진다. 느려지는 데가 내릴 수 있는 데다.<br><br>
    시계는 01:20. 덜컹, 덜컹.`,
  o:[
    { l:'① 이음매 박자로 느려질 곳을 셈한다.', k:'gaze', dc:21,
      ok:`덜컹 사이를 맥박으로 쟀다. 역과 역 사이 시각 차를 곱했다. 거리가 나온다. 그다음 역 사이 거리가 유난히 짧은 구간을 찾았다. 짧은데 오래 걸린다. 굽은 길이다. 아니면 서는 척하는 길이다.<br><br>『가는골』 앞이다. 두 시 반쯤.<br>일행에게 그 시각을 일러 두었다. 그때 창가에 서라고. 문이 안 열리면 창이라도.<br><br>표에 없는 것을 표에서 꺼냈다. 시각만 적힌 종이에서 길의 모양을 읽는 법. 덜컹 소리가 이제 숫자로 들린다.`,
      ng:`맥박으로 재는데 맥이 빠르다. 겁이 나서 그렇다.<br><br>셈이 두 배로 틀렸다. 일러 둔 시각에 아무 일도 없었다.<br>창가에 서 있던 일행이 지나가던 검표원 눈에 띄었다. 표를 다시 보자고 했다. 표를 내밀 때까지 등줄기가 젖었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-12 }, wake:1 },
    { l:'② 안내 방송이 부르는 역 이름을 받아 적는다.', k:'sense', dc:20,
      ok:`방송이 역을 부를 때마다 표 뒷면에 적었다. 물안. 저녁재.<br><br>시간표 순서와 대 봤다. 방송이 시간표보다 한 역씩 빠르다. 방송은 다음 역이 아니라 다다음 역을 부른다.<br>그러면 『가는골』이라 부를 때 진짜 가는골은 한 역 뒤다. 그렇게 적어 두었다.`,
      ng:`받아 적는데 방송 소리가 빗소리에 묻혔다.<br><br>되물으려고 고개를 드니 스피커 밑에 검표원이 서 있다. 이쪽 표를 본다.<br>표를 감추다 손가락이 좌석 틈에 끼어 꺾였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } },
    { l:'③ 시간표를 떼어 품에 넣는다.', k:'luck', dc:20,
      ok:`압정 네 개를 뽑았다. 시간표가 손에 떨어졌다.<br><br>뒷면에 연필 글씨가 있다. 먼저 탄 사람이 남긴 것이다. 『04:20 젖은다리. 다리 끝에서 느려짐.』<br>시간표를 뗀 자리에 같은 시간표가 하나 더 붙어 있다. 그것도 종착 칸이 비었다.`,
      ng:`압정 하나가 손가락을 찔렀다. 뽑으려다 시간표가 찢어졌다.<br><br>찢긴 반쪽이 바닥에 떨어져 통로로 쓸려 갔다.<br>그걸 주우러 몸을 숙였다. 자던 사람들 발이 다 이쪽으로 향해 있었다. 언제 돌렸는지 모른다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B3', t:'우편 분류칸 — 내일 소인',
  x:`분류함 칸마다 편지가 꽂혔다. 맨 위 칸에 일행 이름이 적힌 편지가 있다.<br><br>
    소인이 내일 날짜다. 소인 옆에 분류 번호가 찍혔다. 숫자 넷.<br>
    우편은 번호로 간다. 번호를 읽으면 편지가 어디로 가는지 안다.<br><br>
    바닥의 우편 자루가 숨 쉬듯 부풀었다 꺼진다.`,
  o:[
    { l:'① 분류 번호로 편지가 갈 곳을 읽는다.', k:'gaze', dc:21,
      ok:`분류함 칸마다 번호가 붙었다. 앞 두 자리가 역이다. 뒤 두 자리가 칸이다.<br><br>일행 편지 번호의 앞 두 자리는 어느 역에도 없다. 종착이다. 뒤 두 자리는 9호차.<br>편지가 9호차로 간다. 다음 운행 맨 끝 칸. 일행은 내일 이 열차의 맨 끝 칸에 앉아 있게 된다.<br><br>편지를 칸에서 빼 분류 직원 의자에 올려 두었다. 분류 안 된 편지는 아무 데도 못 간다.`,
      ng:`번호를 읽으려 편지를 빼는데 봉투가 따뜻하다.<br><br>쥔 손이 저려 온다. 떨어뜨렸다. 편지가 우편 자루 위로 떨어졌다. 자루가 그걸 삼키듯 꺼졌다.<br>무엇이 적혔는지 모른 채 남은 길을 갔다. 내내 등이 차가웠다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-15, spirit:-14 } },
    { l:'② 이쪽 이름 편지를 다른 칸에 꽂는다.', k:'fix', dc:21,
      ok:`편지를 빼서 첫 역 칸에 꽂았다. 이미 지나간 역이다.<br><br>지나간 역으로 가는 편지는 되돌아온다. 되돌아오는 데 하루가 걸린다.<br>하루면 된다. 이쪽은 오늘 밤만 버티면 된다.`,
      ng:`꽂는데 분류함 칸이 편지를 밀어낸다. 다시 꽂았다. 또 밀어낸다.<br><br>편지가 바닥에 떨어졌다. 집으려는데 우편 자루 하나가 이쪽 발목 위로 넘어졌다.<br>자루는 사람 무게다. 빼내는 데 한참 걸렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B3', t:'식당칸 — 차림표',
  x:`식탁마다 차림표가 놓였다. 두꺼운 종이, 금박 글씨.<br><br>
    요리 이름 옆에 값이 적혔다. 쓰지 않는 지 오래된 돈 단위다.<br>
    맨 아래 날짜가 인쇄돼 있다. 차림표를 찍은 날. 아주 오래전이다.<br><br>
    웨이터가 다가와 고개를 숙인다. 「주문하시겠습니까.」`,
  o:[
    { l:'① 값과 날짜를 맞춰 무엇이 진짜인지 가른다.', k:'gaze', dc:20,
      ok:`인쇄된 날짜와 돈 단위가 맞는다. 그 무렵 차림표다.<br><br>그런데 셋째 줄만 활자가 다르다. 덧인쇄다. 『오늘의 수프 — 무료. 한 분 더.』<br>무료라는 말은 그 시절 차림표에 없었다. 나중에 누가 넣었다.<br><br>「셋째 줄 빼고 주시오.」 웨이터가 오래 서 있다가 물러갔다. 빵과 물이 나왔다. 물은 맑았다.`,
      ng:`날짜를 읽다가 웨이터를 기다리게 했다.<br><br>「손님께서 정하지 않으시면 저희가 정해 드립니다.」<br>셋째 줄이 나왔다. 김이 오른다. 숟가락을 든 손을 일행이 쳤다. 수프가 엎어지며 손등을 데었다.`,
      win:{ exp:16, item:'맑은 물' }, lose:{ hp:-24, mind:-12 } },
    { l:'② 주문하는 척하며 주방 소금 단지를 챙긴다.', k:'hide', dc:20,
      ok:`이것저것 묻는 척 웨이터를 붙잡아 두었다. 일행 하나가 주방 쪽으로 갔다.<br><br>요리사는 등을 보이고 도마질을 한다. 칼만 오르내린다. 선반의 소금 단지에서 덩어리 하나를 꺼내 왔다.<br>소금은 썩지 않는다. 이 열차에서 썩지 않는 것은 드물다.`,
      ng:`웨이터가 질문에 다 대답한다. 대답이 끝나지 않는다.<br><br>그 사이 주방에서 도마질이 멎었다. 일행이 뛰어나왔다. 팔뚝에 칼자국이 하나.<br>소금은 못 챙겼다. 피가 하얀 식탁보에 번졌다.`,
      win:{ exp:15, item:'소금 덩이' }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B3', t:'등기 금고 — 시각 다이얼',
  x:`우편칸 끝에 무쇠 금고가 있다. 볼트가 반쯤 풀려 열차가 휠 때마다 한 치씩 미끄러진다.<br><br>
    다이얼에 숫자 대신 시각이 적혔다. 시와 분.<br>
    문틈에 운행 일지 표지가 삐죽 나왔다. 일지에는 종착역 이름이 있을 것이다.<br><br>
    열차가 굽은 길에 들어선다. 금고가 이쪽으로 기운다.`,
  o:[
    { l:'① 시간표로 다이얼 시각을 맞춘다.', k:'gaze', dc:22,
      doom:{ title:'미끄러지는 금고', what:'금고에 깔렸습니다', dc:18, sec:50,
        text:`첫 시각은 출발, 둘째는 종착일 것이다. 04:44로 돌렸다.<br><br>찰칵. 하나가 맞았다. 셋째를 돌리는데 열차가 크게 휜다.<br>볼트가 마저 빠지는 소리. 금고가 이쪽으로 미끄러진다. 무릎을 친다. 넘어진 다리 위로 무쇠가 얹힌다.<br><br>다이얼이 눈앞에서 멈췄다. 셋째 칸이 비어 있다. 아직 아무도 그 시각에 안 내렸다.`,
        dieText:`금고는 우편칸 끝에 다시 서 있다. 볼트가 반쯤 풀린 채로.<br><br>다이얼 둘째 칸이 04:44에 맞춰져 있다.<br>운행 일지에 한 줄이 늘었다. 『등기 1건 — 수취인 탑승 확인』.` },
      ok:`첫 칸은 출발 시각, 둘째는 종착. 셋째는 시간표에 없다. 표에 없는 시각은 아직 오지 않은 시각이다.<br><br>금고가 미끄러지는 박자를 먼저 쟀다. 굽은 길에서만 온다. 곧은 길에서 다이얼을 돌리고, 휠 때는 비켜섰다.<br>셋째 칸을 04:43으로 맞췄다. 종착 일 분 전. 문이 열렸다.<br><br>일지 맨 끝에 종착역 이름이 있다. 읽고 나서 다시 닫았다. 소리 내어 읽을 이름이 아니다. 대신 그 일 분 전이 내릴 시각인 건 알았다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 볼트를 조여 금고부터 붙든다.', k:'steady', dc:21,
      ok:`분류칸 공구함에서 스패너를 찾았다. 곧은 길에서 볼트를 조이고 휠 때 손을 뗐다.<br><br>네 개를 다 조였다. 금고가 더는 안 미끄러진다.<br>열지는 못했다. 대신 아무도 이걸 이쪽으로 밀어 보낼 수 없다.`,
      ng:`조이는데 스패너가 미끄러졌다. 손등이 볼트에 갈렸다.<br><br>그 순간 열차가 휘었다. 금고가 한 치 와서 정강이를 쳤다.<br>뼈가 울린다. 일어서지 못하고 기어서 비켰다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-30, mind:-10 } },
    { l:'③ 문틈의 일지 표지만 뽑아 본다.', k:'luck', dc:21,
      ok:`표지 끝을 손톱으로 잡고 휠 때를 기다렸다. 금고가 기울면 문틈이 조금 벌어진다.<br><br>그때 당겼다. 표지 한 장이 찢겨 나왔다. 뒷면에 지난 운행 기록이 있다. 『04:43 비상 제동 — 1명 하차』.<br>한 명은 내렸다. 그 일 분 전에.`,
      ng:`당기는데 표지가 안 나온다. 문틈이 도로 닫히며 손가락을 물었다.<br><br>열차가 반대로 휠 때까지 기다려야 했다. 숨 서른 번.<br>빼냈을 때 손톱 하나가 금고 문에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] }
]);

// ------------------------------------------
// 주술사 · 마력
// ------------------------------------------
kJob('hexer', 'B', [

{ at:'B', t:'빗속 — 불어 터진 매듭',
  x:`손목에 감아 둔 실이 젖었다. 지키는 매듭이다. 일곱 번 감고 세 번 묶었다.<br><br>
    실이 물을 먹어 불었다. 불은 매듭은 헐거워진다. 벌써 한 바퀴가 풀려 손등으로 흘러내렸다.<br>
    주술사는 안다. 이 매듭이 풀리면 그동안 막고 있던 것이 한꺼번에 들어온다.<br><br>
    등 뒤에서 누가 빗속을 걸어온다. 서두르지 않는다. 이쪽 매듭이 풀리기를 기다리는 걸음이다.`,
  o:[
    { l:'① 마력을 실 한 올에 실어 젖어도 안 풀리는 매듭을 짓는다.', k:'gaze', dc:21, cost:{ mana:25 },
      ok:`실을 다 풀었다. 한 올만 남겼다. 마력을 그 한 올에만 실었다. 가늘게, 끝까지.<br><br>젖은 실은 굵게 묶으면 불어서 풀린다. 가늘게 묶으면 물이 들 틈이 없다. 매듭 하나를 손톱 크기로 지었다.<br>등 뒤 걸음이 멈췄다. 그리고 돌아갔다. 기다릴 것이 없어졌다.<br><br>매듭은 굵을수록 세다고 배웠다. 오늘 밤 그 배움이 반대로 뒤집혔다. 손이 먼저 알고 손가락이 저절로 가늘게 묶는다.`,
      ng:`마력을 한 올에 몰다 실이 끊어졌다. 너무 가늘었다.<br><br>손목이 비었다. 그 순간 등줄기로 찬 것이 들어왔다. 빗물보다 차다.<br>무릎이 꺾였다. 일어서는 동안 등 뒤 걸음이 한 걸음 더 왔다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-18, mind:-12 }, wake:1 },
    { l:'② 젖은 매듭을 이로 물어 조인다.', k:'steady', dc:20,
      ok:`손목을 입에 대고 매듭을 이로 물었다. 당겼다. 실이 이 사이에서 삐걱댄다.<br><br>불은 실도 꽉 물면 조여진다. 침이 묻은 매듭은 주인 것으로 안다.<br>풀리던 한 바퀴가 도로 감겼다. 등 뒤 걸음이 그 자리에서 맴돌다 멀어졌다.`,
      ng:`물고 당기는데 실이 앞니 사이에 끼었다. 당기다 잇몸이 찢어졌다.<br><br>피가 매듭에 묻었다. 피 묻은 매듭은 주인을 헷갈린다.<br>한 바퀴가 더 풀렸다. 귀 뒤가 차갑다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 매듭은 포기하고 소금을 혀 밑에 문다.', k:'luck', dc:20,
      ok:`주머니 깊은 데 소금이 한 줌 남아 있다. 젖지 않았다. 기름종이에 싸 둔 덕이다.<br><br>혀 밑에 한 알 물었다. 짜다. 짠 입으로는 아무것도 안 들어온다.<br>매듭이 다 풀려 떨어졌다. 상관없었다. 입안이 쓰린 동안은.`,
      ng:`기름종이가 찢겨 소금이 다 녹았다. 손바닥에 짠물만 남았다.<br><br>핥았다. 모자란다.<br>매듭이 풀리자 귀에서 누가 숨을 쉬었다. 한참 고개를 흔들어도 안 떨어졌다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'일행 등 — 붉은 실 한 올',
  x:`앞서가는 일행 외투 등판에 붉은 실이 한 올 붙어 있다.<br><br>
    보풀이 아니다. 실 끝이 매듭으로 박혔다. 다른 끝은 빗속 어딘가로 길게 늘어져 있다.<br>
    이 표시를 안다. 쫓는 쪽이 쫓을 사람에게 달아 두는 것이다. 개 목줄처럼.<br><br>
    본인은 모른다. 모퉁이마다 뒤쪽 발소리가 정확히 그 사람 쪽으로 꺾인다.`,
  o:[
    { l:'① 실이 어디로 이어지는지 거슬러 본다.', k:'gaze', dc:20,
      ok:`실을 손가락 사이에 걸고 눈으로만 따라갔다. 당기지 않았다. 당기면 저쪽이 안다.<br><br>실은 골목 셋을 건너 낮은 창 하나로 들어간다. 창 안에 불 꺼진 방. 거기 앉아 실을 쥔 사람이 있다. 쫓는 자가 아니다. 쫓는 자에게 길을 대 주는 사람이다.<br>창 아래를 크게 돌아 지났다. 실은 이쪽이 지나간 길을 그대로 그렸다. 틀린 길을.`,
      ng:`따라가다 손가락에 걸린 실이 팽팽해졌다. 저쪽에서 당긴 것이다.<br><br>일행이 뒤로 휘청했다. 실에 끌려 한 걸음. 붙잡았다.<br>그 순간 실 끝 창문에 불이 켜졌다. 뛰었다. 젖은 계단에서 둘이 같이 굴렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } },
    { l:'② 실을 끊지 않고 다른 데로 옮겨 맨다.', k:'hide', dc:21,
      ok:`매듭째 떼어 냈다. 끊지 않았다. 끊으면 저쪽 손이 가벼워져서 안다.<br><br>골목 배수관 쇠고리에 옮겨 맸다. 실이 팽팽한 채 그대로다.<br>한참 뒤 발소리가 배수관 앞에서 멈췄다. 오래 멈춰 있었다. 이쪽은 그동안 두 골목을 갔다.`,
      ng:`떼어 내는데 매듭이 외투 천을 물고 안 놓는다.<br><br>억지로 뜯었다. 실이 끊겼다. 저쪽 손이 가벼워졌다.<br>발소리가 뛰기 시작했다. 이쪽을 향해 곧게.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'게시판 — 바늘 꽂힌 얼굴',
  x:`벽 코르크판에 사진이 다섯 장 꽂혀 있다. 일행 얼굴이다. 언제 찍었는지 모른다.<br><br>
    사진마다 바늘이 하나씩. 이마에, 목에, 가슴에. 둘은 아직 바늘이 없다.<br>
    바늘 꽂는 자리는 아무 데나가 아니다. 이마는 길을 잃게 하고 목은 소리를 막고 가슴은 숨을 줄인다.<br><br>
    판 옆 쟁반에 바늘이 두 개 남았다.`,
  o:[
    { l:'① 바늘이 꽂힌 순서를 읽는다.', k:'gaze', dc:21,
      ok:`바늘 머리 녹을 봤다. 녹이 먼저 슨 것이 먼저 꽂힌 것이다. 이마, 가슴, 목.<br><br>순서가 곧 쫓는 쪽의 계획이다. 길을 잃게 하고, 지치게 하고, 소리 못 지르게 하고. 남은 둘은 마지막이다. 잡히는 사람이다.<br>남은 바늘 둘을 쟁반째 하수구에 쏟았다. 바늘이 없으면 순서도 끝까지 못 간다.`,
      ng:`녹을 보다 판에 손이 닿았다. 바늘 하나가 더 깊이 들어갔다.<br><br>가슴에 꽂힌 사진이다. 그 사진의 일행이 숨을 들이켜다 기침을 했다. 멈추지 않는다.<br>한참 등을 두드려 주었다. 기침이 멎었을 때 둘 다 진이 빠져 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 마력을 실어 바늘을 거꾸로 꽂는다.', k:'gaze', dc:22, cost:{ mana:25 },
      ok:`바늘을 하나씩 뽑았다. 뽑힌 자리에 마력을 눌러 넣고 바늘 끝을 바깥으로 돌려 다시 꽂았다.<br><br>바늘귀가 사진 쪽, 끝이 바깥쪽. 이제 이 판 앞에 서는 사람이 찔린다.<br>뽑을 때 손이 떨리지 않았다. 남이 놓은 바늘을 한 손에 거꾸로 세우는 데 숨 한 번이면 됐다. 바늘의 앞뒤가 손끝에서 구별된다. 그 구별이 이제 생각보다 빠르다.`,
      ng:`돌려 꽂는 순간 마력이 바늘을 타고 손끝으로 거슬러 왔다.<br><br>손가락 끝이 하얗게 질린다. 감각이 없다. 사진 속 일행이 아니라 이쪽 이마가 지끈거린다.<br>길이 두 갈래로 보였다. 한참 벽을 짚고 섰다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'③ 사진을 몽땅 뜯어 빗물에 담근다.', k:'break', dc:20,
      ok:`다섯 장을 다 뜯었다. 바늘이 판에 남았다.<br><br>골목 물웅덩이에 사진을 담갔다. 인화지가 일어나 얼굴이 흐려진다. 얼굴 없는 사진에는 바늘이 안 먹는다.<br>판에 남은 바늘들이 빈 구멍만 찌르고 있다.`,
      ng:`뜯는데 바늘이 사진째 같이 딸려 나와 손바닥에 박혔다.<br><br>깊다. 뽑자 피가 흐른다. 그 피가 사진 한 장에 떨어졌다.<br>이쪽 얼굴 사진이다. 그 뒤로 손바닥 상처가 오래 안 아물었다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'뒷방 — 피로 찍는 약속',
  x:`길을 안다는 사내가 있다. 젖은 모자, 금니. 탁자에 종이를 펴고 칼을 놓는다.<br><br>
    「돈은 필요 없소. 엄지에 피 한 방울. 나가서 한 번만 나를 도와주면 되오.」<br>
    피로 찍는 약속을 안다. 돈 약속은 어기면 그만이다. 피 약속은 어기면 몸이 갚는다.<br><br>
    사내 등 뒤 문틈에 누가 서 있다. 둘. 숨을 죽였다.`,
  o:[
    { l:'① 도장 찍는 척하고 다른 피를 쓴다.', k:'luck', dc:21,
      doom:{ title:'피의 약속', what:'약속에 묶여 끌려갑니다', dc:17, sec:55,
        text:`엄지를 베는 척하고 손바닥에 숨긴 붉은 잉크를 묻혔다. 종이에 눌렀다.<br><br>사내가 종이를 들어 냄새를 맡는다. 웃는다. 「잉크 약속은 잉크가 갚지.」<br>종이 위 붉은 자국이 번지며 손가락 끝으로 기어 올라온다. 손목에 감긴다. 문틈의 둘이 들어와 그 손목을 잡는다.<br><br>어디로 가는지 모른 채 끌린다. 약속은 이미 되었다.`,
        dieText:`탁자 위에 종이가 펼쳐져 있다. 붉은 엄지 자국이 하나.<br><br>사내가 다음 사람에게 칼을 내민다. 「돈은 필요 없소.」<br>문틈에 셋이 서 있다. 하나는 젖은 외투 소매에 잉크가 묻었다.` },
      ok:`엄지를 베는 척하고 손바닥에 숨긴 붉은 잉크를 묻혔다. 종이에 누르기 직전, 종이 귀퉁이를 접었다.<br><br>접힌 종이는 약속이 반만 닿는다. 사내가 눈치채기 전에 귀퉁이를 펴서 내밀었다.<br>사내는 길을 알려 주었다. 진짜 길이었다. 반쪽짜리 약속은 반쪽짜리 빚이다. 갚을 일은 나중에 있다. 지금은 나간다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 약속의 문구를 읽어 빈 매듭을 찾는다.', k:'gaze', dc:21,
      ok:`종이를 끌어당겨 읽었다. 『나가서 한 번 돕는다.』 무엇을, 어디서, 언제가 없다.<br><br>빈 데가 많은 약속은 쓰는 쪽에게 유리하다. 대신 빈 데를 먼저 채우는 쪽이 이긴다.<br>칼끝으로 종이 끝에 한 줄을 더 그었다. 『이 방 안에서, 지금.』 그리고 엄지를 찍고 사내의 젖은 모자를 집어 그의 머리에 씌워 주었다. 「도왔소.」<br><br>사내 얼굴이 굳었다. 약속은 채워졌다. 매듭에 빈 고리가 있으면 그 고리로 먼저 묶는다. 손이 이제 그 고리를 먼저 찾는다.`,
      ng:`읽는 동안 사내가 칼을 집었다. 「글 읽는 손님은 비싸.」<br><br>문틈의 둘이 들어왔다. 탁자가 엎어졌다.<br>창으로 빠져나가며 유리에 팔뚝을 그었다. 종이는 바닥에 떨어졌다. 아무도 안 찍은 채로.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'③ 칼을 사내 쪽으로 돌려놓고 일어선다.', k:'steady', dc:20,
      ok:`칼자루를 사내 쪽으로 돌려놓았다. 칼날이 이쪽을 보지 않게.<br><br>「다음에.」 일어섰다. 사내는 붙잡지 않았다. 칼을 돌려놓는 손님은 피 약속을 아는 손님이다.<br>문틈의 둘이 길을 비켜 주었다. 길은 스스로 찾았다. 오래 걸렸다.`,
      ng:`일어서는데 문틈의 하나가 문을 막았다.<br><br>사내가 칼을 다시 돌려놓는다. 이쪽을 향해.<br>밀치고 나왔다. 어깨를 문틀에 세게 부딪쳤다. 등 뒤에서 사내가 휘파람을 불었다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'길바닥 — 떨어진 동전',
  x:`젖은 길 한가운데 동전이 떨어져 있다. 반짝인다. 네온 불빛을 받아서.<br><br>
    둘레에 빗물이 고였는데 동전 위에만 물이 안 맺힌다.<br>
    주술사는 길에 떨어진 돈을 줍지 않는다. 남이 떨어뜨린 것이 아니라 남이 버린 것일 수 있다. 무언가를 실어서.<br><br>
    일행 하나가 벌써 허리를 굽힌다.`,
  o:[
    { l:'① 동전에 무엇이 실렸는지 본다.', k:'gaze', dc:20,
      ok:`일행 팔을 잡고 동전을 봤다. 테두리에 실 한 올이 감겼다. 머리카락이다.<br><br>앓던 사람이 제 병을 실어 버린 것이다. 주운 사람이 앓는다.<br>신발 뒤축으로 동전을 하수구 쇠창살 사이로 밀어 넣었다. 땡그랑. 물 아래서 한 번 더 울렸다.`,
      ng:`보는 사이 일행이 동전을 집었다. 놓으라고 했을 때는 이미 주머니였다.<br><br>그 사람 얼굴이 금세 붉어진다. 열이다.<br>동전을 빼앗아 던졌다. 열은 그대로 남았다. 둘이 번갈아 부축하며 걸었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-14 } },
    { l:'② 동전을 차서 쫓는 쪽 길로 보낸다.', k:'luck', dc:20,
      ok:`발끝으로 동전을 툭 찼다. 동전이 젖은 길을 굴러 뒤쪽 모퉁이로 갔다.<br><br>쫓는 쪽은 바닥을 보며 온다. 이쪽 자국을 찾느라.<br>한참 뒤 모퉁이에서 누가 크게 재채기를 했다. 또 했다. 발소리가 느려졌다.`,
      ng:`찬 동전이 벽에 맞고 되돌아왔다. 이쪽 신발 코에 멈췄다.<br><br>그날 밤 내내 발이 무거웠다. 신발에 물이 들어찬 것처럼.<br>계단을 오를 때마다 한 칸씩 헛디뎠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'모퉁이 — 씻겨 가는 소금 선',
  x:`모퉁이 바닥에 소금으로 그은 원이 있다. 비에 씻겨 반쯤 녹았다.<br><br>
    원 안에 사람이 웅크렸다. 젖은 양복. 무릎을 끌어안고 떤다. 이쪽을 보고 손가락을 입에 댄다.<br>
    원 밖 빗속에서 무언가가 원 둘레를 돈다. 보이지 않는다. 물웅덩이만 차례로 파문이 인다.<br><br>
    녹은 자리가 한 뼘이다. 원 안 사람이 그 틈을 손으로 막고 있다.`,
  o:[
    { l:'① 마력으로 젖은 소금 선을 다시 묶는다.', k:'fix', dc:21, cost:{ mana:22 },
      ok:`원 밖에 무릎을 꿇었다. 녹은 자리에 손바닥을 대고 마력을 흘렸다.<br><br>녹은 소금이 물속에서 다시 엉긴다. 선이 아니라 매듭으로. 물에 풀리지 않게 한 번 꼬아서.<br>파문이 원 앞에서 멈췄다. 한참 있다가 멀어졌다.<br><br>원 안 사람이 숨을 내쉬었다. 품에서 무언가를 꺼내 내밀었다. 말린 고기 한 줄. 「이거밖에 없소.」`,
      ng:`마력을 흘리는데 빗물이 더 세게 쏟아졌다. 엉기던 소금이 도로 풀린다.<br><br>파문이 이쪽 무릎 앞까지 왔다. 차가운 것이 손등을 핥고 지나갔다.<br>손을 뗐다. 손등이 퍼렇게 얼었다. 원 안 사람은 다시 틈을 손으로 막았다.`,
      win:{ exp:20, item:'말린 고기' }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 원 안 사람에게 누가 그었는지 묻는다.', k:'bond', dc:20,
      ok:`원 밖에서 쪼그려 앉아 낮게 물었다. 그가 고개를 저었다. 자기가 아니라고. 지나가던 사람이 그어 주고 갔다고.<br><br>그어 준 사람은 소금을 넉넉히 두고 갔다. 원 안에 자루가 있다.<br>자루에서 한 줌을 받아 녹은 데를 덧그었다. 서툴러도 소금은 소금이다. 파문이 물러났다.`,
      ng:`묻는 소리에 파문이 이쪽으로 돌았다.<br><br>원 안 사람이 이쪽을 노려본다. 말을 하지 말라고 그렇게 손가락을 댔는데.<br>뒤로 물러나다 웅덩이에 넘어졌다. 웅덩이가 이쪽 발목을 오래 붙들었다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'창틀 — 머리카락 인형',
  x:`길가 2층 창틀에 작은 인형이 앉아 있다. 머리카락을 꼬아 만들었다. 단추 눈 둘.<br><br>
    인형은 길을 내려다본다. 지나가는 사람마다 고개가 아주 조금 따라 돈다.<br>
    이건 안다. 보는 인형이다. 이 인형이 본 것을 다른 누가 본다.<br><br>
    이 길 말고는 돌아갈 길이 없다.`,
  o:[
    { l:'① 인형 눈을 가리고 지나간다.', k:'hide', dc:20,
      ok:`벽에 붙어 창 밑까지 갔다. 젖은 손수건을 창틀로 던졌다. 인형 머리에 얹혔다.<br><br>손수건 밑에서 인형이 고개를 흔든다. 떨어지지 않는다. 젖은 천은 무겁다.<br>그 사이 다 지나갔다. 마지막 사람이 지날 때 손수건이 떨어졌다. 인형은 빈 길을 봤다.`,
      ng:`던진 손수건이 빗나가 창틀 밑으로 떨어졌다.<br><br>인형이 고개를 돌려 손수건을, 그다음 이쪽을 봤다.<br>멀리서 문 열리는 소리. 뛰는 발소리. 이쪽이 지난 길을 정확히 밟고 온다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 인형의 매듭을 읽어 보는 쪽을 바꾼다.', k:'gaze', dc:21,
      ok:`창 밑에서 올려다봤다. 목 매듭이 왼쪽으로 감겼다. 매듭이 감긴 쪽이 인형이 보는 쪽이다.<br><br>돌을 하나 집어 창틀을 맞혔다. 인형이 떨어지며 목 매듭이 반 바퀴 돌았다. 이제 오른쪽으로 감겼다. 담벼락을 본다.<br>담벼락에는 아무도 없다. 인형 너머의 누가 한동안 담벼락만 봤을 것이다.<br><br>매듭의 감긴 방향만 보고 무엇이 무엇을 향하는지 안다. 그걸 돌 하나로 돌렸다. 매듭을 손 안 대고 고치는 법이 하나 생겼다.`,
      ng:`던진 돌이 창을 깼다. 유리 소리가 빗소리를 뚫었다.<br><br>인형은 그대로다. 이쪽을 본다. 창 안에서 불이 켜졌다.<br>뛰었다. 깨진 유리를 밟았다. 신발 바닥을 뚫고 들어왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-25, spirit:-12 }, wake:1 }
  ] },

{ at:'B', t:'손목 — 길잡이가 매 준 실',
  x:`처음 만난 길잡이가 손목에 실을 매 주었다. 길 잃지 말라고. 다들 하나씩.<br><br>
    길잡이는 모퉁이에서 사라졌다. 실은 남았다.<br>
    지금 실이 조인다. 왼쪽으로 가려 할 때만. 오른쪽으로 가면 느슨해진다.<br><br>
    오른쪽 골목은 막다른 데서 셔터가 반쯤 올라가 있다. 그 아래가 어둡다.`,
  o:[
    { l:'① 실이 무엇을 위해 매인 것인지 읽는다.', k:'gaze', dc:21,
      ok:`실을 비벼 결을 봤다. 지키는 매듭은 안쪽으로 감는다. 이건 바깥쪽이다. 끄는 매듭이다.<br><br>실은 길을 잃지 말라는 게 아니라 정해진 길로 오라는 것이다. 오른쪽 셔터 밑으로.<br>왼쪽으로 갔다. 손목이 아프게 조였다. 참았다. 셔터 밑 어둠에서 누가 일어서는 소리가 났다. 이쪽은 이미 다음 모퉁이였다.`,
      ng:`결을 보는 사이 일행 둘이 느슨한 쪽으로 걸어갔다. 편한 쪽으로.<br><br>불러 세웠다. 돌아오는 동안 실이 그 둘을 셔터 쪽으로 당겼다.<br>끌어오느라 셋이 엉켜 넘어졌다. 손목마다 실 자국이 붉게 패였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 실을 이로 끊고 일행 것도 끊는다.', k:'break', dc:20,
      ok:`이로 끊었다. 질기다. 어금니로 갈아서 끊었다. 다섯 개를 다.<br><br>끊긴 실들이 빗물에 쓸려 오른쪽 골목으로 흘러간다. 셔터 밑으로 다 들어갔다.<br>그 안에서 누가 실을 당기다 헛손질하는 소리가 났다.`,
      ng:`셋째 실을 끊다 이가 시렸다. 실이 이 사이에 엉켰다.<br><br>그사이 남은 실 둘이 세게 당겨졌다. 일행 둘이 오른쪽으로 몇 걸음 끌려갔다.<br>쫓아가 손목을 잡았다. 셔터 앞에서였다. 셔터 밑에서 젖은 손가락이 나와 있었다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 자루의 매듭',
  x:`창고 벽을 따라 자루 다섯이 줄지어 섰다. 빈 자루다. 입이 열려 있다.<br><br>
    끈은 배 사람들 매듭으로 묶였다. 하역부들이 쓰는 것이다. 그런데 다섯째 자루 끈만 다르다.<br>
    그 매듭을 안다. 채워 두는 매듭이다. 빈 것을 빈 채로 두지 않는다.<br><br>
    칠판 글씨가 떠오른다. 『모자라면 채울 것.』`,
  o:[
    { l:'① 다섯째 매듭이 무엇을 기다리는지 읽는다.', k:'gaze', dc:21,
      ok:`매듭에 손을 안 대고 봤다. 고리가 다섯이다. 넷은 조여졌다. 하나만 열렸다.<br><br>조여진 넷은 이미 채워진 자루들이다. 이 창고에서 전에. 열린 하나가 오늘 밤 몫이다. 누구 몫이든 상관없다. 숫자만 맞으면 된다.<br>열린 고리에 창고 쥐덫에 걸려 죽은 쥐 꼬리를 꿰어 조였다. 하나가 채워졌다. 숫자는 맞았다.<br><br>매듭이 세는 것이 사람인지 숫자인지 가려 보는 법. 숫자만 세는 매듭은 다른 것으로 속는다. 그 틈이 눈에 먼저 들어온다.`,
      ng:`보는 사이 일행 하나가 다섯째 자루에 등을 기댔다. 지쳐서.<br><br>열린 고리가 조여드는 소리. 자루 입이 그 사람 어깨를 물었다.<br>둘이 붙어 끌어냈다. 그 사람 어깨에 끈 자국이 깊게 남았다. 한참 숨을 못 쉬었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 },
    { l:'② 마력으로 매듭을 고쳐 매 다섯을 채운 척한다.', k:'fix', dc:21, cost:{ mana:25 },
      ok:`매듭을 풀지 않고 그 위에 마력으로 한 바퀴를 더 감았다. 열린 고리를 닫는 바퀴.<br><br>다섯째 자루가 저절로 부풀었다. 빈 채로. 무게도 없이.<br>칠판 앞을 지나는데 분필 글씨 『다섯』 옆에 누가 체크를 한 것처럼 금이 생겼다. 셈이 끝났다고 믿는 쪽은 더 세지 않는다.`,
      ng:`감는데 아래 매듭이 이쪽 마력을 먹었다. 먹고 더 열렸다.<br><br>자루 입이 크게 벌어진다. 이쪽 쪽으로.<br>손을 뗐다. 손가락 셋이 끈에 감겨 살갗이 벗겨졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'경매장 — 경매판 17번',
  x:`경매장 칠판에 오늘 새벽 목록이 적혔다. 맨 아래 한 줄. 『17번 — 3번 창고분. 다섯. 낙찰 완료.』<br><br>
    분필 글씨다. 그런데 분필 가루가 젖어도 안 흐른다. 이 글씨만.<br>
    주술사는 안다. 써서 팔면 팔린 것이 된다. 칠판이 계약서다.<br><br>
    칠판 옆 놋쇠 종이 바람도 없이 한 번 흔들렸다.`,
  o:[
    { l:'① 마력을 실어 분필 글씨를 고쳐 쓴다.', k:'gaze', dc:22, cost:{ mana:28 },
      ok:`손가락에 마력을 모아 『낙찰 완료』 위를 문질렀다. 글씨가 지워지지 않는다. 지우는 게 아니라 고쳐야 한다.<br><br>분필을 집어 『낙찰』 앞에 한 글자를 넣었다. 『유』. 유찰 완료. 아무도 사지 않았다.<br>놋쇠 종이 흔들리다 멈췄다. 경매장 반대편 문에서 들어오던 노란 비옷들이 발을 멈추고 서로를 봤다. 살 사람이 없으면 가져갈 이유도 없다.<br><br>남이 써 놓은 매듭을 끊지 않고 글자 하나로 뒤집었다. 한 글자에 얼마만큼 마력을 실어야 하는지 손가락이 정확히 안다.`,
      ng:`『유』를 쓰는데 분필이 부러졌다. 획이 반만 들어갔다.<br><br>반쪽 글자는 아무 뜻도 아니다. 아니, 다른 뜻이다. 칠판이 그 글자를 『재』로 읽었다. 재경매.<br>종이 울렸다. 노란 비옷들이 장대를 들고 이쪽으로 왔다. 숨을 데까지 뛰다 얼음물에 무릎을 찧었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'② 종 추를 끈으로 묶어 둔다.', k:'fix', dc:20,
      ok:`종 안에 손을 넣어 추를 붙잡았다. 신발 끈을 풀어 추를 종 안벽에 묶었다.<br><br>경매는 종이 울려야 시작한다. 종이 안 울리면 낙찰된 것도 넘겨지지 않는다.<br>한참 뒤 누가 종을 쳤다. 둔탁한 소리만 났다. 노란 비옷들이 고개를 갸웃했다.`,
      ng:`추를 잡는 순간 종이 저절로 흔들렸다. 손이 안에 있는 채로.<br><br>추가 손가락을 쳤다. 손가락 뼈가 울린다. 종소리는 이쪽 손에 먹혀 작게 났다.<br>그래도 났다. 반대편 문이 열렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 목록 옆 빈칸에 다른 물건을 적어 넣는다.', k:'luck', dc:21,
      ok:`17번 밑에 한 줄을 더 적었다. 『18번 — 회색 밴. 하나. 낙찰 완료.』<br><br>젖은 분필 글씨가 흐르다 멈췄다. 칠판이 받아들였다.<br>잠시 뒤 바깥에서 밴 문이 열렸다 닫히는 소리가 났다. 노란 비옷 둘이 그쪽으로 뛰어갔다. 팔린 것은 가져가야 한다.`,
      ng:`적은 글씨가 빗물에 흘러내렸다. 칠판이 안 받았다.<br><br>대신 흘러내린 분필 물이 17번 줄에 섞였다. 『다섯』이 『여섯』처럼 번졌다.<br>노란 비옷들이 이쪽 일행을 세다 고개를 갸웃했다. 그리고 더 찾으러 흩어졌다. 숨을 곳이 줄었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'방파제 — 우산이 준 쪽지',
  x:`주머니 속 쪽지가 따뜻하다. 처음에 우산 쓴 남자가 준 것이다. 3번 창고 위치가 적혔다.<br><br>
    비에 다 젖었는데 이 쪽지만 젖지 않았다. 접힌 모양이 이상하다. 네 번 접고 끝을 안으로 밀어 넣었다.<br>
    그 접는 법을 안다. 종이 매듭이다. 가진 사람이 어디 있는지 접은 사람에게 알려 준다.<br><br>
    방파제 끝 꺼진 등대 밑에 우산이 서 있다. 이 바람에도 안 뒤집힌다. 그가 손을 흔든다.`,
  o:[
    { l:'① 접힌 결을 읽어 무엇을 알려 주는지 본다.', k:'gaze', dc:21,
      ok:`펴지 않고 결을 봤다. 접힌 금마다 마력이 얇게 배었다. 금 하나가 끝까지 남자 쪽을 가리킨다.<br><br>그는 이쪽이 어디 있는지 밤새 알았다. 그래서 늘 서두르지 않았다. 청소부에게 알려 준 것도 그 금이다.<br>쪽지를 젖은 돌 틈에 박아 넣었다. 금이 가리키는 쪽이 돌이 됐다. 우산이 한참 그 돌을 보고 서 있었다.`,
      ng:`결을 보려 손가락으로 금을 쓸다가 한 번 폈다.<br><br>펴진 쪽지는 더 크게 알린다. 우산이 이쪽으로 걸어오기 시작했다.<br>뒤로 물러나다 파도가 방파제를 넘었다. 발목을 쓸어 갔다. 블록 모서리에 정강이를 찍었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 쪽지를 남자 손에 되돌려 쥐여 준다.', k:'bond', dc:21,
      doom:{ title:'돌려준 쪽지', what:'우산 밑으로 끌려갑니다', dc:17, sec:55,
        text:`다가가 쪽지를 내밀었다. 「돌려드리오.」<br><br>남자가 받지 않고 이쪽 손목을 잡는다. 장갑이 차다. 「받은 건 돌려주는 게 아니지.」<br>우산이 기울어 이쪽 머리 위로 온다. 우산 밑은 비가 안 온다. 바람도 안 분다. 소리도 안 난다.<br><br>우산 밑에서 남자가 처음으로 얼굴을 보인다. 웃고 있다. 발이 방파제 끝으로 끌린다.`,
        dieText:`방파제 끝 꺼진 등대 밑에 우산이 서 있다.<br><br>이 바람에도 안 뒤집힌다. 그가 손을 흔든다.<br>그의 다른 손에 접힌 쪽지가 하나 있다. 다음 손님에게 줄 것이다.` },
      ok:`다가가 쪽지를 내밀었다. 남자가 받지 않으려 손을 뺀다.<br><br>그 틈에 쪽지를 그의 우산 살 사이에 끼웠다. 손이 아니라 우산에. 접은 사람이 제 우산을 가리키는 쪽지를 들고 섰다.<br>남자가 처음으로 우산을 접었다. 빗속에서 쪽지를 떼어 내느라. 그동안 등대 쪽 계단으로 빠졌다. 그는 젖은 얼굴로 한참 이쪽을 찾았다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'B1', t:'수로 — 꿈틀하는 자루',
  x:`수로 안쪽에서 자루 하나가 떠내려온다. 물살을 따라 이쪽으로. 한 번 꿈틀한다.<br><br>
    입구 끈이 매듭으로 묶였다. 배 사람 매듭이 아니다. 열지 말라는 매듭이다. 연 사람에게 안의 것이 옮아간다.<br>
    자루 겉에 모자 하나가 같이 걸려 떠 온다. 아까 야적장에서 사라진 노인의 모자다.<br><br>
    밀물이 허리에서 가슴으로 오른다.`,
  o:[
    { l:'① 마력으로 매듭을 거꾸로 푼다.', k:'gaze', dc:21, cost:{ mana:24 },
      ok:`자루를 쇠창살에 기대 세웠다. 매듭 끝을 찾아 마력을 거꾸로 흘렸다. 맨 감은 순서의 반대로.<br><br>매듭이 풀렸다. 옮아올 것이 갈 길을 잃고 물에 흩어졌다.<br>자루 안에서 노인이 숨을 몰아쉬었다. 입에 재갈. 손이 하얗게 얼었다. 재갈을 빼자 첫마디가 이랬다. 「정문 기계실. 톱니 셋째.」<br><br>노인은 조끼 안주머니를 끝까지 지키고 있었다.`,
      ng:`거꾸로 흘리다 순서를 하나 건너뛰었다. 매듭이 더 조였다.<br><br>자루 안 꿈틀거림이 멎었다. 그리고 매듭에서 찬 것이 이쪽 손목으로 기어올랐다.<br>손을 물에 처박아 떨어냈다. 손목에 끈 자국이 하얗게 남았다. 자루는 물살에 밀려 멀어졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 매듭은 두고 자루째 높은 데로 끌어 올린다.', k:'steady', dc:21,
      ok:`자루를 어깨에 걸고 쇠창살을 붙잡았다. 물이 가슴까지 왔다. 버텼다.<br><br>창살 위 턱에 자루를 올렸다. 물이 거기까지는 안 찬다.<br>매듭은 안 풀었다. 안에서 노인이 숨 쉬는 소리가 들린다. 밖에 나가면 다른 사람이 풀 것이다. 지금은 숨만 붙여 놓았다.`,
      ng:`자루가 물을 먹어 무겁다. 어깨에 걸자 무릎이 꺾였다.<br><br>둘이 같이 물에 잠겼다. 짠물을 들이켰다.<br>창살을 붙잡고 올라왔을 때 자루는 손에 없었다. 한참 기침했다. 목구멍이 쓰라리다.`,
      win:{ exp:18, spirit:6 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B2', t:'7층 — 가죽 띠의 박음질',
  x:`눈을 뜨니 손목이 침대 난간에 묶였다. 가죽 띠다.<br><br>
    버클은 손 닿지 않는 쪽이다. 대신 띠 안쪽 박음질이 손가락에 닿는다. 촘촘하다. 한 땀마다 실이 한 번씩 꼬였다.<br>
    그 꼬임을 안다. 묶인 사람이 당길수록 조이는 바느질이다.<br><br>
    복도 시계는 정각 칠 분 전.`,
  o:[
    { l:'① 박음질 순서를 읽어 거꾸로 뜯는다.', k:'gaze', dc:21,
      ok:`손가락으로 한 땀씩 셌다. 꼬임이 왼쪽, 왼쪽, 오른쪽. 세 땀마다 한 번 반대로 꼰다. 반대로 꼰 땀이 매듭의 쐐기다.<br><br>쐐기 땀만 손톱으로 뜯었다. 셋째, 여섯째, 아홉째. 나머지 땀이 저절로 느슨해졌다.<br>손목이 빠졌다. 띠는 겉보기에 멀쩡하다. 손목을 도로 띠 안에 넣어 두었다. 정각에 간호사가 묶인 사람을 셌다. 하나도 안 틀렸다.`,
      ng:`세다가 꼬임 방향을 헷갈렸다. 엉뚱한 땀을 뜯었다.<br><br>띠가 한 칸 더 조였다. 손끝이 하얘진다.<br>정각이 됐다. 간호사가 이쪽 띠를 보고 아무 말 없이 한 칸 더 조였다. 손등이 퍼렇게 부었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 띠를 당기지 않고 손을 비틀어 땀으로 미끄러뜨린다.', k:'evade', dc:20,
      ok:`당기지 않았다. 당기면 조인다. 손목을 아주 천천히 돌렸다. 땀이 가죽 안쪽을 적신다.<br><br>젖은 가죽은 늘어난다. 조이는 바느질도 젖으면 꼬임이 무뎌진다.<br>숨 백 번쯤에 엄지 뿌리가 빠졌다. 나머지는 금방이었다.`,
      ng:`돌리다 저도 모르게 한 번 당겼다. 팔이 저려서.<br><br>띠가 확 조였다. 손목뼈가 눌린다. 비명을 이로 삼켰다.<br>정각까지 그대로 있었다. 간호사가 세고 지나갔다. 손이 한참 남의 것 같았다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-25, spirit:-12 } }
  ] },

{ at:'B2', t:'휴게실 — 약 봉투 종이학',
  x:`창가 노인이 약 봉투를 펴서 학을 접는다. 창틀에 스무 마리쯤 줄지어 앉았다.<br><br>
    학마다 날개 안쪽에 이름이 적혔다. 봉투에 인쇄된 환자 이름이다.<br>
    주술사는 접는 손을 본다. 접는 것도 묶는 것이다. 종이로 묶으면 실보다 오래간다.<br><br>
    노인이 이쪽을 보고 빈 봉투 하나를 내민다. 처음 보는 이름이 인쇄돼 있다. 이쪽 침대 명패의 그 이름이다.`,
  o:[
    { l:'① 노인이 접는 순서를 끝까지 지켜본다.', k:'gaze', dc:21,
      ok:`노인 손이 느리다. 그래서 다 보였다. 이름이 날개 안쪽으로 들어가게 접고, 마지막에 목을 꺾는다.<br><br>목을 꺾은 학은 세어지지 않는다. 장부에서 사람이 아니라 종이가 된다. 노인은 이 병동 사람들을 하나씩 접어 숨겨 왔다.<br>내민 봉투를 받아 노인 손 그대로 따라 접었다. 마지막 목에서 손이 떨렸다. 노인이 이쪽 손을 감싸 꺾어 주었다.<br><br>실 없이 종이 하나로 묶는 법이 손에 남았다. 접는 금 하나하나가 매듭이다. 이제 종이를 보면 어디를 꺾어야 할지가 먼저 보인다.`,
      ng:`보다가 순서를 놓쳤다. 목을 꺾기 전에 날개를 폈다.<br><br>펴진 학은 그냥 봉투다. 이름이 바깥으로 드러났다.<br>복도에서 딸깍 소리가 이쪽 문 앞에 멈췄다. 노인이 학을 품에 감췄다. 둘이 숨을 죽이고 오래 앉아 있었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-15, spirit:-14 }, wake:1 },
    { l:'② 노인에게 한 마리 접어 달라고 한다.', k:'bond', dc:20,
      ok:`봉투를 도로 내밀었다. 「접어 주시겠소.」<br><br>노인이 고개를 끄덕였다. 느리게, 정성껏. 마지막에 목을 꺾었다.<br>학을 받아 품에 넣었다. 노인은 다시 창밖 약국 간판을 봤다. 그는 자기 학은 접지 않는다.`,
      ng:`노인이 접다 말고 손을 멈췄다. 기침이 터졌다.<br><br>봉투가 노인 침에 젖었다. 젖은 종이는 목이 안 꺾인다.<br>노인이 미안하다는 듯 고개를 숙였다. 이쪽 이름은 그대로 장부에 남았다. 정각에 딸깍 소리가 이쪽 앞에서 유난히 길었다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-14, spirit:-12 } },
    { l:'③ 창틀의 학 한 마리를 몰래 품에 넣는다.', k:'luck', dc:20,
      ok:`노인이 고개를 돌린 사이 끝에 앉은 학 하나를 집었다.<br><br>날개 안 이름이 지워져 있다. 빈 학이다. 노인이 일부러 비워 둔 것이다. 누가 가져가라고.<br>노인이 돌아보고 창틀을 셌다. 한 마리가 비었다. 그는 웃었다.`,
      ng:`집은 학 날개 안에 이름이 있었다. 남의 이름이다.<br><br>그 학을 집자 복도 끝 병실에서 누가 깨어 소리를 질렀다. 숨어 있던 사람이 장부에 돌아왔다.<br>얼른 제자리에 놓았다. 소리는 멎었다. 노인이 오래 이쪽을 봤다. 슬픈 얼굴로.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-12, spirit:-16 } }
  ] },

{ at:'B2', t:'침대 — 처음 보는 이름의 명패',
  x:`침대 발치 명패에 처음 보는 이름이 적혔다. 이쪽 침대다.<br><br>
    명패 뒷면에 실이 감겼다. 명패를 침대 쇠틀에 묶은 실이다. 나사도 있는데 굳이 실로 묶었다.<br>
    이건 안다. 이름을 자리에 묶는 매듭이다. 이 침대에 누운 사람은 이 이름이 된다.<br><br>
    옆 침대 사람은 제 이름을 잊었다. 명패 이름으로 대답한다.`,
  o:[
    { l:'① 뒷면 매듭을 읽어 이름이 어디서 왔는지 본다.', k:'gaze', dc:20,
      ok:`매듭 꼬리에 오래된 실이 섞였다. 다른 명패 실이다. 이 이름은 전에 다른 침대에 묶여 있다가 옮겨 왔다.<br><br>이름이 사람을 따라온 게 아니라 침대를 갈아탔다. 이 이름의 주인은 오래전에 나갔다. 이름만 남아 다음 사람을 기다린다.<br>매듭 꼬리를 손톱으로 끊었다. 이름이 침대에 묶이지 않은 채로 덜렁거린다. 그날 밤 그 이름으로 불렸을 때 몸이 대답하지 않았다.`,
      ng:`매듭을 읽으려고 명패를 뒤집었다. 앞면이 이쪽 눈에 들어왔다.<br><br>이름을 소리 없이 읽었다. 입술이 움직였다. 그 순간 그게 이쪽 이름 같았다.<br>일행이 이쪽 진짜 이름을 세 번 부르고서야 돌아봤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 명패를 떼어 빈 침대에 옮겨 묶는다.', k:'luck', dc:21,
      doom:{ title:'명패', what:'침대에 묶였습니다', dc:17, sec:55,
        text:`실을 풀어 명패를 뗐다. 빈 침대 쇠틀에 옮겨 묶으려 몸을 숙였다.<br><br>빈 침대 시트가 따뜻하다. 비어 있지 않았다. 누가 방금까지 누워 있었다.<br>매듭을 짓는 손을 시트 밑에서 누가 잡는다. 당긴다. 이쪽 몸이 침대 위로 넘어간다. 가죽 띠가 저절로 손목을 찾는다.<br><br>명패가 이쪽 발치에서 덜렁거린다. 매듭은 이미 지어졌다. 이쪽 손으로.`,
        dieText:`정각이다. 간호사가 병실 문 앞에 선다. 계수기를 누른다.<br><br>침대 하나에 사람이 하나씩. 명패 이름을 부른다. 대답이 다 돌아온다.<br>숫자가 맞는다. 옆 침대 사람이 오늘따라 제 이름을 기억해 냈다.` },
      ok:`실을 풀어 명패를 뗐다. 빈 침대로 가기 전에 시트를 손등으로 짚어 봤다. 차다. 진짜 빈 침대다.<br><br>명패를 쇠틀에 묶었다. 매듭은 일부러 거꾸로 감았다. 이름이 빈 침대에서 사람을 기다리되 오지 않게.<br>정각에 간호사가 그 이름을 불렀다. 빈 침대가 대답하지 않았다. 간호사는 그 침대 앞에서 한참 계수기를 쥔 채 서 있었다. 그 사이 이쪽 침대는 건너뛰었다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B2', t:'세단실 — 기록철의 실',
  x:`세단기 입이 기록철을 한 권씩 문다. 직원이 표지를 입술로 읽고 넣는다.<br><br>
    다음 철 표지 사진은 7층 휴게실의 여자다. 달력에 금을 긋던 사람.<br>
    이쪽 눈에는 보인다. 철 등에서 가는 실이 위층으로 이어진다. 저 철이 갈리면 실 끝의 사람이 장부에서 빠진다.<br><br>
    빠진 사람은 찾으러 온다. 직원이 그 철을 집는다.`,
  o:[
    { l:'① 마력으로 철과 사람 사이 실을 풀어 둔다.', k:'gaze', dc:22, cost:{ mana:26 },
      ok:`문틀 그늘에서 실 끝을 손가락에 걸었다. 마력을 실에 흘려 철 등에 박힌 매듭을 풀었다.<br><br>직원이 철을 넣었다. 세단기가 문다. 종이가 갈려 나온다. 실은 이미 이쪽 손가락에 감겨 있다.<br>위층에서 아무 일도 없었다. 갈린 건 종이다. 사람은 장부에서 안 빠졌다. 장부가 그 사람을 모를 뿐이다.<br><br>실을 감아 주머니에 넣었다. 나가면 그 사람에게 돌려줄 것이다.`,
      ng:`풀던 매듭이 반쯤에서 엉켰다. 세단기가 철을 물었다.<br><br>실이 팽팽하게 당겨졌다. 손가락에 감긴 채. 세단기 쪽으로.<br>손가락을 빼냈다. 살갗이 실에 쓸려 벗겨졌다. 위층에서 짧은 비명이 한 번 났다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-18 } },
    { l:'② 세단기 전선을 뽑는다.', k:'break', dc:20,
      ok:`벽 콘센트까지 기어갔다. 직원은 표지를 읽느라 이쪽을 안 본다.<br><br>플러그를 뽑았다. 세단기가 철을 반쯤 문 채 멈췄다.<br>직원이 계수기를 내려다본다. 누른 숫자와 갈린 숫자가 안 맞는다. 그는 처음부터 다시 셌다. 오래 걸릴 것이다.`,
      ng:`플러그가 안 빠진다. 잡아당기는 사이 직원이 이쪽을 봤다.<br><br>표지를 읽던 입술이 멈췄다. 이번엔 이쪽 얼굴을 읽는다.<br>문으로 뛰었다. 서가 모서리에 허리를 찧었다. 등 뒤에서 세단기가 다시 돌았다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B3', t:'9호차 — 편도의 구멍',
  x:`손에 쥔 표에 개찰 구멍이 뚫렸다. 밑에 작게 『편도』.<br><br>
    구멍 가장자리가 안으로 말렸다. 집게로 뚫으면 바깥으로 말린다. 이건 안에서 무언가가 빠져나간 구멍이다.<br>
    주술사는 안다. 뚫는 것도 묶는 것이다. 돌아오는 길을 표에서 뽑아냈다.<br><br>
    일행 표도 다 같다. 검표원이 앞 칸에서 집게를 딸깍거린다.`,
  o:[
    { l:'① 구멍의 결을 읽어 무엇이 빠졌는지 본다.', k:'gaze', dc:21,
      ok:`구멍을 등불에 비췄다. 말린 종이 결에 실밥 같은 것이 걸렸다. 표의 실이다. 표마다 돌아오는 실 한 올이 섞여 있다.<br><br>그 실이 뽑혔다. 그런데 일행 하나의 표에는 실밥 끝이 남았다. 덜 뽑혔다.<br>그 실밥을 이쪽 표 구멍에 대 꼬았다. 둘이 반씩 나눠 가졌다. 반쪽 실이라도 길이 아주 끊긴 건 아니다.`,
      ng:`비추는데 등불 열기에 구멍이 더 커졌다. 종이가 그을렸다.<br><br>표가 가벼워진다. 손이 저절로 표를 놓으려 한다. 꽉 쥐었다.<br>검표원이 이쪽 앞에 섰다. 그을린 표를 보고 집게를 한 번 더 딸깍였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-14 } },
    { l:'② 마력과 머리카락으로 구멍을 기워 막는다.', k:'fix', dc:22, cost:{ mana:25 },
      ok:`머리카락 한 올을 뽑았다. 마력을 실어 바늘처럼 세웠다. 구멍 가장자리를 한 땀씩 기웠다.<br><br>안으로 말린 결을 바깥으로 되말며. 다섯 장을 다 기웠다. 손끝이 떨렸다.<br>검표원이 표를 받아 들었다. 구멍을 본다. 구멍이 없다. 「이 표는 아직 안 뚫렸군요.」 그는 집게를 들었다가 내려놓고 지나갔다.<br><br>머리카락 한 올로 종이를 꿰매는 데 마력이 얼마나 드는지, 이제 손가락이 정확히 잰다. 실이 없어도 묶을 것은 몸에 늘 붙어 있다.`,
      ng:`셋째 표를 기우다 머리카락이 끊겼다. 마력이 끊긴 자리로 샜다.<br><br>표가 손안에서 차갑게 식는다. 구멍이 하나 더 생겼다.<br>검표원이 그 표를 보고 웃었다. 「왕복이시네.」 그 웃음이 등을 오래 따라왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-20, spirit:-18 }, wake:1 }
  ] },

{ at:'B3', t:'8호차 — 『다음』',
  x:`침대칸 끝에서 두 번째 침대. 머리맡에 일행 하나의 이름표가 꽂혔다.<br><br>
    이름 밑에 작은 글씨로 한 줄 더. 『다음』.<br>
    이 글씨를 안다. 순서를 매기는 글씨다. 이름 위에 쓴 말은 이름보다 세다.<br><br>
    시트가 아직 따뜻하다. 누가 방금 일어났거나, 누가 기다리고 있다.`,
  o:[
    { l:'① 이름표 글씨를 읽어 누가 썼는지 본다.', k:'gaze', dc:21,
      ok:`획을 봤다. 이름은 반듯하다. 『다음』은 삐뚤다. 다른 손이다.<br><br>이름은 이 열차가 썼고 『다음』은 열차에 탄 그것이 썼다. 그것은 순서를 제 손으로 매긴다. 남이 매긴 순서로는 안 움직인다.<br>『다음』 위에 침을 묻혀 손가락으로 문질렀다. 잉크가 아니라 연필이다. 지워졌다. 그것은 다시 써야 한다. 다시 쓰려면 다시 와야 한다.`,
      ng:`획을 보는데 삐뚤어진 글씨가 조금씩 움직인다.<br><br>『다음』이 이름 위로 올라간다. 이름을 덮는다.<br>이름표를 뽑으려다 손가락을 베였다. 종이에. 피가 『다음』에 스몄다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-14, spirit:-16 } },
    { l:'② 이름표를 빼서 차장실 쪽 빈 침대에 꽂는다.', k:'hide', dc:20,
      ok:`이름표를 뺐다. 통로 맨 앞 빈 침대 머리맡에 꽂았다. 커튼을 쳤다.<br><br>그것은 이름표를 보고 온다. 사람을 보고 오지 않는다.<br>한참 뒤 맨 앞 커튼이 아주 조금 벌어졌다 닫혔다. 그 사이 일행은 반대쪽 끝에서 7호차로 넘어갔다.`,
      ng:`옮겨 꽂는데 그 침대 커튼 안에서 숨소리가 났다. 비어 있지 않았다.<br><br>커튼이 걷혔다. 면도하던 남자 얼굴이 누워서 웃는다.<br>이름표를 놓고 뛰었다. 통로 신발들을 걷어차며. 넘어져 턱을 찧었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } },
    { l:'③ 따뜻한 시트에 소금을 뿌려 식힌다.', k:'luck', dc:20,
      ok:`주머니 소금을 시트 위에 고르게 뿌렸다.<br><br>기다리는 자리는 따뜻해야 한다. 소금 뿌린 자리는 금방 식는다.<br>손등을 대 봤다. 차다. 이제 이 침대는 아무도 안 기다린다. 이름표 『다음』이 가리킬 자리가 없어졌다.`,
      ng:`소금이 시트에 닿자 지글거렸다. 시트 밑이 너무 뜨겁다.<br><br>김이 올라 얼굴을 덮었다. 숨을 들이켜다 목이 탔다.<br>기침이 멎지 않는다. 커튼들이 하나씩 이쪽으로 벌어졌다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'특실 3호실 — 승객 명단',
  x:`가죽 트렁크 손잡이에 승객 명단이 묶였다. 트렁크 안에서 두드리는 소리. 셋, 셋, 셋.<br><br>
    명단 위에서부터 붉은 줄이 그어졌다. 서른여섯째에서 멈췄다. 그 밑은 일행 이름이다.<br>
    붉은 줄을 본다. 펜으로 그은 게 아니다. 실이다. 이름 하나에 한 올씩 꿰었다.<br><br>
    맨 끝 한 줄은 번져서 안 읽힌다. 거기 꿰인 실만 검다.`,
  o:[
    { l:'① 붉은 실과 검은 실의 매듭을 읽는다.', k:'gaze', dc:21,
      ok:`붉은 실들은 다 한 매듭으로 모인다. 트렁크 손잡이다. 이름을 꿰어 트렁크에 묶었다.<br><br>검은 실만 반대로 간다. 손잡이가 아니라 객실 문 밖으로. 기관실 쪽으로. 번진 이름은 이 명단을 묶은 자의 이름이다. 제 이름도 명단에 넣어 두었다. 끝에.<br>검은 실을 건드리지 않았다. 대신 일행 이름 밑에 꿰일 빈 바늘구멍들을 침으로 문질러 막았다. 막힌 구멍에는 실이 안 들어간다.`,
      ng:`매듭을 따라가다 손가락이 검은 실에 닿았다.<br><br>실이 떨었다. 멀리서 누가 그 떨림을 느꼈다. 복도 벽등이 하나씩 꺼져 온다.<br>손을 뗐지만 늦었다. 손끝이 검게 물들었다. 오래 안 지워졌다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 트렁크 걸쇠를 열어 안의 사람을 꺼낸다.', k:'break', dc:21,
      doom:{ title:'트렁크', what:'트렁크 안으로 끌려 들어갑니다', dc:17, sec:50,
        text:`걸쇠를 비틀어 열었다. 뚜껑이 들린다.<br><br>안은 어둡다. 트렁크 크기보다 깊다. 두드리던 손이 나와 이쪽 손목을 잡는다. 사람 손이다. 젖었다.<br>그 손이 당긴다. 구해 달라는 손이 아니다. 같이 있자는 손이다. 어깨가 트렁크 안으로 들어간다.<br><br>명단의 붉은 실 하나가 이쪽 이름 위로 저절로 꿰인다.`,
        dieText:`3호실 문이 열려 있다. 가죽 트렁크 하나.<br><br>안에서 두드리는 소리가 난다. 셋, 셋, 셋.<br>명단의 붉은 줄이 한 줄 더 내려왔다.` },
      ok:`걸쇠를 열기 전에 명단 실을 손잡이에서 풀어 바닥에 늘어놓았다. 트렁크는 명단에 묶였다. 명단이 떨어지면 그냥 가방이다.<br><br>뚜껑을 열었다. 안에 사람이 아니라 젖은 외투 한 벌과 빈 구두. 두드리던 것은 구두 굽이었다. 바닥에 붙어 열차 박자로 두드렸다.<br>외투 주머니에 마른 빵과 말린 고기가 있다. 누군가 내리기 전에 챙겨 둔 것이다.`,
      win:{ exp:22, dream:3, item:'말린 고기' } }
  ] },

{ at:'B3', t:'보일러 옆 — 사슬 묶인 안전판',
  x:`압력계 바늘이 빨간 칸에서 떤다. 배관 이음새마다 김이 샌다.<br><br>
    안전판 밸브 손잡이가 사슬로 묶였다. 자물쇠가 없다. 사슬 끝이 매듭으로 묶였다.<br>
    주술사는 그 매듭을 본다. 쇠사슬을 실처럼 묶었다. 사람 손으로는 못 하는 일이다. 마력이 배어 있다.<br><br>
    종착까지 14분. 바늘이 한 칸 더 간다.`,
  o:[
    { l:'① 마력을 흘려 사슬 매듭을 푼다.', k:'gaze', dc:22, cost:{ mana:28 },
      ok:`사슬에 두 손을 얹었다. 뜨겁다. 손바닥이 탄다. 마력을 매듭 결대로 흘렸다.<br><br>쇠고리가 하나씩 헐거워진다. 묶은 자가 감은 순서가 손바닥으로 읽힌다. 마지막 고리가 풀렸다.<br>밸브 손잡이를 돌렸다. 하얀 김이 굴뚝처럼 솟는다. 바늘이 빨간 칸에서 내려왔다. 열차가 처음으로 숨을 쉬듯 느려졌다.`,
      ng:`마력이 사슬을 타다 막혔다. 매듭 안에 다른 마력이 더 세게 앉아 있다.<br><br>이쪽 마력이 튕겨 손바닥으로 돌아왔다. 데었다. 물집이 순식간에 부풀었다.<br>바늘이 한 칸 더 갔다. 이음새 하나가 터지며 김이 팔을 덮었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 소매로 손을 싸고 맨손으로 사슬을 푼다.', k:'steady', dc:21,
      ok:`소매를 손에 감았다. 사슬을 쥐었다. 뜨거움이 천을 뚫고 온다. 참았다.<br><br>매듭은 마력으로 묶었지만 쇠는 쇠다. 고리 하나를 비틀어 벌렸다. 매듭이 거기서 끊겼다.<br>밸브를 돌렸다. 김이 솟았다. 소매가 손바닥에 눌어붙었다. 떼어 내는 건 나중이다.`,
      ng:`쥐는 순간 소매가 탔다. 탄 천이 손바닥에 붙었다.<br><br>놓을 수가 없다. 붙었다. 억지로 떼었다. 살갗이 같이 왔다.<br>사슬은 그대로다. 바늘이 떤다.`,
      win:{ exp:18, spirit:6 }, lose:{ hp:-32, mind:-12 } },
    { l:'③ 매듭에 남은 손버릇으로 묶은 자를 읽는다.', k:'sense', dc:20,
      ok:`매듭 끝을 봤다. 마지막 고리를 늘 한 번 더 감는 버릇이 있다. 겁 많은 손이다. 자기가 묶은 걸 못 믿는다.<br><br>그런 손은 묶은 것 옆에 늘 풀 것을 숨겨 둔다. 보일러 밑을 더듬었다. 쇠꼬챙이 하나.<br>꼬챙이를 고리 사이에 넣고 비틀었다. 매듭이 열렸다. 묶은 자가 제 몫으로 숨긴 것이다.`,
      ng:`읽는 사이 이음새 하나가 터졌다. 김이 정면으로 왔다.<br><br>얼굴을 돌렸다. 귀와 목덜미가 데었다.<br>한참 눈을 못 떴다. 그 사이 바늘이 한 칸 갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] }
]);

// ------------------------------------------
// 퇴마사 · 마력
// ------------------------------------------
kJob('exorcist', 'B', [

{ at:'B', t:'빗속 — 번지는 부적',
  x:`품 안 부적이 젖었다. 외투를 뚫고 비가 들었다.<br><br>
    붉은 획이 번져 종이 밖으로 흐른다. 번진 부적은 아무것도 못 막는다. 아무것도 아닌 종이다.<br>
    퇴마사는 부적이 몇 장 남았는지 셌다. 일곱. 일곱 다 번졌다.<br><br>
    뒤쪽 어둠에서 무언가가 이쪽 냄새를 맡는다. 부적 냄새가 사라진 걸 안다.`,
  o:[
    { l:'① 마력을 모아 손바닥 안쪽에 작은 부적을 쓴다.', k:'gaze', dc:21, cost:{ mana:24 },
      ok:`종이는 버렸다. 엄지손톱으로 왼손바닥 안쪽에 획을 그었다. 마력을 손톱 끝에 모아 한 획씩 눌렀다.<br><br>손바닥은 젖어도 번지지 않는다. 살 안쪽에 쓴 것은 비가 못 닿는다. 주먹을 쥐면 부적이 숨는다.<br>뒤쪽 냄새 맡던 것이 멈칫했다. 주먹을 펴 보였다. 그것이 물러났다.<br><br>종이 일곱 장보다 손바닥 하나가 낫다. 획을 반으로 줄여도 뜻이 선다는 것을 손톱이 먼저 알았다. 부적을 쓰는 자리가 이제 종이에만 있지 않다.`,
      ng:`획을 긋다 마력이 손톱 끝에서 흩어졌다. 손바닥에 붉은 자국만 남았다.<br><br>자국은 부적이 아니다. 상처다. 상처 냄새는 더 멀리 간다.<br>뒤쪽 것이 빨라졌다. 목덜미에 찬 숨이 닿을 때까지 돌아보지 못했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-20, spirit:-18 }, wake:1 },
    { l:'② 남은 부적을 기름종이에 싸 겨드랑이에 끼운다.', k:'steady', dc:20,
      ok:`번진 일곱 장 사이에서 덜 번진 한 장을 골랐다. 기름종이에 싸 겨드랑이에 끼웠다.<br><br>체온에 종이가 마른다. 번진 획이 조금 가라앉는다. 반쯤은 부적이다.<br>반쪽 부적으로도 냄새는 돌아온다. 뒤쪽 것이 망설이며 따라오다 멈췄다.`,
      ng:`겨드랑이 땀에 기름종이가 젖었다. 부적이 마저 녹았다.<br><br>그사이 뒤쪽 것이 바짝 붙었다. 어깨를 무언가 핥고 갔다.<br>그 자리가 얼음처럼 차다. 오래 팔이 안 올라갔다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 번진 부적을 그대로 문짝에 붙이고 지나간다.', k:'luck', dc:20,
      ok:`번진 부적 일곱 장을 지나는 문마다 하나씩 붙였다.<br><br>번진 획이 문짝에 흘러 이상한 무늬가 됐다. 뜻은 없다. 뒤쪽 것은 뜻을 읽지 않는다. 냄새를 맡는다.<br>일곱 문에서 일곱 번 멈췄다. 일곱 번 멈추는 동안 이쪽은 멀어졌다.`,
      ng:`붙인 부적이 빗물에 미끄러져 바닥에 떨어졌다. 줄줄이.<br><br>바닥에 깔린 일곱 장이 이쪽 간 길을 그대로 그렸다.<br>뒤쪽 것이 그 길을 따라 똑바로 왔다. 뛰다 모퉁이에서 무릎이 꺾였다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'모퉁이 — 먼저 도는 그림자',
  x:`모퉁이 저쪽에서 그림자가 먼저 돈다. 가로등을 등지고 길게 늘어진다.<br><br>
    그림자가 다 돌고 나서 한참 뒤에 사람이 돈다. 걸음이 느리다. 고개가 숙었다.<br>
    순서를 본다. 사람이 그림자를 끌고 다니는 게 아니다. 그림자가 사람을 끌고 다닌다.<br><br>
    그림자 끝이 이쪽 발끝까지 닿았다.`,
  o:[
    { l:'① 그림자와 사람 사이 이음매를 본다.', k:'gaze', dc:21,
      ok:`발목을 봤다. 사람 발목과 그림자가 붙은 자리. 거기가 흐리다. 꿰매 붙인 것처럼 들떠 있다.<br><br>사람은 끌려다니는 몸이다. 무서운 건 그림자다. 그림자는 빛을 따라 움직인다.<br>가로등 쪽으로 걷지 않고 가로등을 등지고 걸었다. 그림자가 이쪽 그림자 위로 겹치려 해도 겹칠 수 없는 쪽으로. 모퉁이를 크게 돌아 빠졌다.`,
      ng:`이음매를 보는 사이 그림자 끝이 이쪽 그림자에 닿았다.<br><br>발이 무거워진다. 한 걸음 늦게 따라온다. 이쪽 발이 저쪽 박자로 걷는다.<br>일행이 등을 밀어 빛 속으로 넣었다. 그림자가 떨어졌다. 다리가 한참 떨렸다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-14, spirit:-16 } },
    { l:'② 등불을 그림자 쪽 바닥에 놓아 빛을 뒤집는다.', k:'fix', dc:20,
      ok:`등불을 모퉁이 앞 바닥에 내려놓았다. 빛이 아래에서 위로 친다.<br><br>그림자가 사람 뒤로 넘어갔다. 그림자는 앞에 있어야 끈다. 뒤로 가면 끌려간다.<br>사람이 처음으로 고개를 들었다. 놀란 얼굴. 그림자가 그 사람 등 뒤에서 버둥대는 사이 지나갔다.`,
      ng:`등불을 놓는데 바람에 꺼졌다. 어둠이다.<br><br>어둠에서는 그림자가 어디에나 있다. 이쪽 발목이 얼었다.<br>다시 불을 켜는 데 손이 떨려 성냥 다섯 개를 버렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-20, spirit:-16 } },
    { l:'③ 그림자 끝을 밟고 버틴다.', k:'steady', dc:21,
      ok:`발끝까지 온 그림자 끝을 뒤꿈치로 꾹 밟았다. 체중을 실었다.<br><br>그림자가 당긴다. 사람이 휘청한다. 밟힌 그림자는 앞으로 못 간다.<br>그림자가 끊어지듯 짧아졌다. 사람이 그 자리에 주저앉았다. 그림자는 모퉁이 뒤로 숨었다.`,
      ng:`밟았는데 그림자가 신발 밑으로 파고든다. 발바닥이 언다.<br><br>발을 뗐다. 신발 바닥이 하얗게 성에가 꼈다.<br>한참 절뚝이며 걸었다. 그림자는 다음 모퉁이에서 또 먼저 돌았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'물웅덩이 — 비친 사람 수',
  x:`길 가운데 큰 물웅덩이. 네온 불빛이 번진다.<br><br>
    일행이 웅덩이 가장자리를 돌아간다. 웅덩이에 비친 것을 센다. 습관이다.<br>
    다섯이 지나가는데 웅덩이에는 여섯이 비친다. 하나는 맨 뒤에 바짝 붙어 걷는다.<br><br>
    돌아보면 아무도 없다. 웅덩이를 보면 있다.`,
  o:[
    { l:'① 비친 것들을 하나씩 짚어 무엇이 붙었는지 본다.', k:'gaze', dc:21,
      ok:`웅덩이에 비친 얼굴을 하나씩 봤다. 다섯은 젖은 얼굴. 여섯째만 마른 얼굴이다. 비를 안 맞는다.<br><br>여섯째는 맨 뒷사람 등에 바짝 붙어 걷는다. 업힌 게 아니다. 걸음을 빌린다. 그 사람 걸음이 조금씩 느려진다.<br>맨 뒷사람 손을 잡아 맨 앞으로 끌어냈다. 순서를 바꿨다. 웅덩이 속 여섯째가 갑자기 붙을 데를 잃었다. 맨 뒤에 아무도 없다.<br><br>사람을 보지 않고 사람의 그림자와 비친 것을 먼저 세는 버릇. 버릇이 아니라 순서가 되었다. 눈이 웅덩이부터 간다.`,
      ng:`짚는데 여섯째가 웅덩이 속에서 고개를 들었다. 이쪽을 본다.<br><br>눈이 마주쳤다. 물속에서. 웅덩이가 발목을 당긴다.<br>뒷걸음질 치다 넘어졌다. 등이 젖었다. 젖은 등이 오래 무거웠다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-20, spirit:-18 }, wake:1 },
    { l:'② 웅덩이를 밟아 깨고 지나간다.', k:'evade', dc:20,
      ok:`웅덩이 한가운데를 세게 밟았다. 물이 튀어 비친 것들이 다 깨졌다.<br><br>깨진 물이 다시 고이기 전에 일행을 몰아 지나갔다.<br>다음 웅덩이에서 셌다. 다섯. 깨진 물에 비친 것은 길을 잃는다.`,
      ng:`밟았는데 웅덩이가 생각보다 깊다. 정강이까지 빠졌다.<br><br>물속에서 무언가 발목을 스쳤다. 손가락 같았다.<br>빼내다 신발이 벗겨졌다. 신발 한 짝은 웅덩이에 두고 왔다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'일행 어깨 — 얹힌 손',
  x:`일행 하나가 자꾸 왔던 길을 돌아본다. 돌아가자고 한다. 거기가 더 안전했다고.<br><br>
    퇴마사 눈에는 보인다. 그 사람 오른쪽 어깨에 손 하나가 얹혀 있다. 하얗고 길다. 손끝이 쇄골을 쥐었다.<br>
    손이 얹힌 사람은 손이 원하는 쪽을 제 생각인 줄 안다.<br><br>
    왔던 길 쪽에서 장화 소리가 난다. 뽀득.`,
  o:[
    { l:'① 마력으로 어깨의 손을 떼어 낸다.', k:'gaze', dc:21, cost:{ mana:22 },
      ok:`그 사람 어깨에 손을 겹쳐 얹었다. 하얀 손 위에. 마력을 손바닥으로 밀었다.<br><br>하얀 손가락이 하나씩 펴진다. 쇄골에서 떨어진다. 마지막 손가락이 떨어질 때 그 사람이 숨을 크게 쉬었다.<br>「내가 왜 돌아가자고 했지.」 왔던 길 쪽 장화 소리가 기다리다 멀어졌다.`,
      ng:`겹쳐 얹는 순간 하얀 손이 이쪽 손을 쥐었다. 손가락 사이로 깍지를 낀다.<br><br>마력이 거꾸로 빨려 나간다. 팔이 차갑다.<br>뿌리쳤다. 하얀 손은 여전히 어깨에 있다. 그 사람은 이제 이쪽을 노려본다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 그 사람 이름을 크게 세 번 부른다.', k:'bond', dc:20,
      ok:`정면에 서서 이름을 불렀다. 크게. 한 번, 두 번, 세 번.<br><br>세 번째에 그 사람 눈이 이쪽을 봤다. 제 눈으로.<br>얹힌 손이 미끄러져 내렸다. 이름이 불린 몸에는 남의 손이 오래 못 얹힌다.`,
      ng:`두 번째에 장화 소리가 멈췄다. 이름 부르는 소리를 들었다.<br><br>그리고 빨라졌다. 이쪽으로.<br>그 사람을 끌고 뛰었다. 그 사람은 끝까지 뒤를 돌아봤다. 둘이 같이 계단에서 굴렀다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 손이 이끄는 쪽에 무엇이 있는지 먼저 본다.', k:'sense', dc:20,
      ok:`손끝이 가리키는 방향을 따라 봤다. 왔던 길이 아니다. 왔던 길 옆 쪽문이다.<br><br>쪽문 앞 바닥이 유난히 깨끗하다. 누가 방금 닦았다.<br>그쪽만 빼고 갔다. 손은 거기 데려가려 했다. 닦인 자리에 다음 것이 놓일 참이었다.`,
      ng:`보는 사이 그 사람이 손을 따라 몇 걸음 갔다.<br><br>쪽문 손잡이를 잡았다. 붙잡아 끌어왔다. 손잡이가 덜컥 돌아갔다가 멈췄다.<br>안에서 누가 반대로 손잡이를 쥐고 있었다. 셋이 같이 넘어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'허리춤 — 발소리에 맞춰 우는 방울',
  x:`허리춤 방울이 운다. 바람이 없는데.<br><br>
    가만히 들으니 박자가 있다. 딸랑, 쉬고, 딸랑. 뒤쪽 어딘가의 발소리와 같은 박자다.<br>
    방울은 가까운 것을 알린다. 소리가 커지면 가깝다. 방울 소리로 거리를 잰다.<br><br>
    지금은 아직 작다. 그런데 박자가 빨라진다.`,
  o:[
    { l:'① 방울 소리 간격으로 거리와 걸음을 잰다.', k:'gaze', dc:20,
      ok:`세 번 들었다. 소리 크기는 그대로인데 간격이 준다. 가까워지는 게 아니라 서두르는 것이다. 무언가를 찾았다.<br><br>이쪽을 찾은 게 아니다. 크기가 그대로니까. 다른 무언가를 쫓아 옆길로 간다.<br>그 옆길과 반대로 갔다. 방울이 점점 작아지다 그쳤다.`,
      ng:`간격을 세는데 소리가 한꺼번에 커졌다. 바로 뒤다.<br><br>재는 동안 그것은 이미 와 있었다.<br>돌아볼 새도 없이 뛰었다. 방울이 미친 듯이 운다. 넘어지며 손목을 접질렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 방울을 손으로 감싸 소리를 죽인다.', k:'hide', dc:20,
      ok:`방울을 쥐고 혀를 손가락으로 눌렀다. 소리가 손안에서 죽었다.<br><br>방울이 우는 걸 저쪽도 듣는다. 둘 다 서로를 듣는 셈이다.<br>소리 없이 벽에 붙어 기다렸다. 발소리가 지나갔다. 방울을 놓아준 건 한참 뒤였다.`,
      ng:`누르는데 방울이 손바닥 안에서 떨었다. 떨림이 손을 타고 팔로 온다.<br><br>손이 저려 놓쳤다. 방울이 바닥에 떨어져 크게 울었다.<br>발소리가 멈췄다. 그리고 이쪽으로 왔다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'잠긴 방 — 향 연기가 눕는 쪽',
  x:`문이 다 잠긴 방이다. 창도 없다. 갇혔다.<br><br>
    향을 하나 피웠다. 불붙은 끝에서 연기가 오른다. 곧게 오르다 한쪽으로 눕는다.<br>
    향 연기는 두 가지에 눕는다. 바람, 그리고 붙은 것.<br><br>
    연기가 두 갈래로 갈렸다. 하나는 벽 쪽으로, 하나는 일행 쪽으로.`,
  o:[
    { l:'① 두 갈래 연기를 읽어 바람과 붙은 것을 가른다.', k:'gaze', dc:21,
      ok:`벽 쪽 연기는 가늘게 빨려 들어간다. 틈이 있다. 바람이다.<br><br>일행 쪽 연기는 둥글게 감긴다. 한 사람 목에. 바람은 감기지 않는다. 그건 붙은 것이다.<br>그 사람 목에 소금 한 알을 문질렀다. 연기가 풀려 위로 올랐다. 벽 쪽 틈을 손톱으로 파니 판자 한 장이 들렸다. 밖이다.<br><br>향 한 대로 길과 귀신을 같이 읽었다. 연기가 휘는 각도만 보고 둘을 가르는 눈이 생겼다.`,
      ng:`두 갈래가 섞였다. 어느 쪽이 바람인지 모른다.<br><br>일행 쪽으로 다가가 벽을 더듬었다. 틈이 없다. 그 사이 감기던 연기가 이쪽 목에도 감겼다.<br>숨이 가빠진다. 향을 꺼뜨려서야 풀렸다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-14, spirit:-18 }, wake:1 },
    { l:'② 향을 꺼 냄새부터 지운다.', k:'hide', dc:20,
      ok:`향을 손가락으로 비벼 껐다. 냄새가 방 안에 고인다. 손으로 부채질해 틈 쪽으로 몰았다.<br><br>향 냄새는 문밖까지 간다. 쫓는 쪽은 그 냄새를 안다.<br>냄새가 빠지자 문밖 발소리가 머뭇거리다 지나갔다. 그 사이 벽을 더듬어 틈을 찾았다.`,
      ng:`끄는데 향이 부러져 불씨가 바닥에 떨어졌다.<br><br>마른 걸레에 옮겨붙었다. 연기가 방에 찬다. 기침이 멈추지 않는다.<br>밟아 껐다. 문밖에서 누가 문손잡이를 돌려 본다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'젖은 유리 — 업힌 뒷모습',
  x:`불 꺼진 진열창에 일행이 비친다. 빗물이 흘러 일렁인다.<br><br>
    퇴마사는 제 뒷모습을 본다. 등이 굽었다. 무언가를 업은 것처럼.<br>
    진짜 등은 곧다. 짐도 없다. 그런데 걸을수록 다리가 무겁다.<br><br>
    진열창 속 등 위의 것이 고개를 돌려 이쪽 귀에 입을 댄다.`,
  o:[
    { l:'① 유리 속 등에 업힌 것을 똑바로 본다.', k:'gaze', dc:21,
      ok:`유리에서 눈을 떼지 않았다. 업힌 것의 얼굴. 젖은 머리카락, 하얀 귀.<br><br>지쳐 쓰러진 것이다. 여기서 쓰러진 누군가의 넋이 다음 등을 찾았다. 해칠 생각은 없다. 다만 내려오지 않는다.<br>유리 앞에서 허리를 깊이 숙였다. 업힌 것이 미끄러져 진열창 안쪽으로 떨어졌다. 다리가 가벼워졌다.`,
      ng:`똑바로 보자 업힌 것도 이쪽을 똑바로 봤다. 유리 속에서.<br><br>귀에 대고 무어라 속삭인다. 알아들을 수 없다. 그런데 무섭다.<br>유리에서 눈을 떼고 뛰었다. 등은 끝까지 무거웠다. 숨이 찼다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 등을 벽에 대고 세게 문지른다.', k:'steady', dc:20,
      ok:`젖은 벽에 등을 대고 위아래로 문질렀다. 외투가 벽에 긁힌다.<br><br>짐승이 진드기 떨듯이. 부적 쓰는 손이 할 짓은 아니다. 그래도 된다.<br>등이 가벼워졌다. 벽에 젖은 자국이 둘 남았다. 하나는 이쪽 등 모양, 하나는 그보다 작다.`,
      ng:`문지르는데 등 위의 것이 더 꽉 매달렸다. 목을 감는다.<br><br>숨이 막힌다. 벽에 머리를 부딪치며 겨우 떨어냈다.<br>이마가 찢어졌다. 피가 빗물에 섞여 눈으로 들어간다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'잠긴 문 — 열어 달라는 목소리',
  x:`쇠문 너머에서 일행 목소리가 난다. 「나야. 먼저 넘어왔어. 문 좀 열어 줘.」<br><br>
    그 목소리 주인은 이쪽 바로 옆에 서 있다. 입을 다물고. 얼굴이 하얗다.<br>
    목소리를 듣지 않는다. 목소리 밑을 듣는다. 숨소리. 목소리가 쉴 때 숨이 들어가는지.<br><br>
    문 너머 목소리는 숨을 안 쉰다. 쉬지 않고 말한다.`,
  o:[
    { l:'① 대답 대신 문틈으로 소금을 민다.', k:'gaze', dc:21,
      ok:`대답하지 않았다. 소금 한 줌을 문 밑 틈으로 밀어 넣었다.<br><br>문 너머 목소리가 끊겼다. 끊긴 자리에서 지글거리는 소리. 그리고 다른 목소리가 났다. 아무의 것도 아닌 목소리. 그것이 원래 목소리다.<br>그 목소리가 멀어졌다. 옆에 선 일행이 무릎을 꺾고 앉았다. 자기 목소리를 남이 쓰는 걸 들은 사람의 얼굴이었다.`,
      ng:`소금을 밀다 손가락이 문틈에 닿았다. 저쪽에서 무언가 그 손가락을 쥐었다.<br><br>당긴다. 손가락 두 마디가 틈으로 들어갔다. 뼈가 문짝에 눌린다.<br>빼냈다. 손가락 끝이 퍼렇다. 문 너머 목소리가 웃었다. 이쪽 목소리로.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 문에 귀를 대고 숨소리를 센다.', k:'sense', dc:20,
      ok:`귀를 댔다. 차다. 목소리 사이사이를 들었다. 숨이 없다.<br><br>대신 아주 먼 데서 다른 숨이 들린다. 진짜 사람 숨. 문 너머 더 안쪽에서. 갇힌 사람이다.<br>문을 안 열었다. 문 옆 벽을 따라 다른 길을 찾았다. 갇힌 사람에게 가는 길은 목소리 쪽이 아니다.`,
      ng:`귀를 대는 순간 문 너머 목소리가 귀에 바로 붙었다.<br><br>「들리지? 나야.」 고막이 울린다.<br>귀를 떼도 소리가 남는다. 한참 일행 목소리를 믿지 못했다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 옆의 일행에게 문 너머에 대고 말하게 한다.', k:'bond', dc:21,
      ok:`옆의 일행 어깨를 잡고 고개를 끄덕였다. 그 사람이 문에 대고 말했다. 「나는 여기 있어.」<br><br>문 너머 목소리가 멈췄다. 같은 목소리 둘이 부딪쳤다. 진짜 쪽이 이긴다. 숨이 섞인 쪽이.<br>문 너머가 조용해졌다. 일행 얼굴에 핏기가 돌았다.`,
      ng:`그 사람이 말을 꺼내려다 목이 막혔다. 소리가 안 나온다.<br><br>문 너머 목소리만 남았다. 「빨리. 빨리 열어.」<br>그 사람이 문고리로 손을 뻗었다. 붙잡아 끌어냈다. 둘 다 숨이 턱까지 찼다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'3번 창고 — 너무 깨끗한 자리',
  x:`창고 구석 의자에 중절모 쓴 사람이 벽을 보고 앉았다. 비옷 어깨가 아직 젖었다.<br><br>
    죽은 지 얼마 안 됐다. 그런데 이쪽 눈에 아무것도 안 보인다. 죽은 자리에는 늘 남는 것이 있는데.<br>
    의자 둘레 바닥만 유난히 깨끗하다. 표백제 냄새가 코를 찌른다.<br><br>
    의자 다리 옆에 하얀 고무장갑 한 짝. 손가락을 가지런히 모은 채로.`,
  o:[
    { l:'① 의자 둘레의 빈 기운을 읽는다.', k:'gaze', dc:21,
      ok:`둘레를 천천히 돌았다. 깨끗한 원 안에는 넋이 없다. 남은 원한도, 놀람도, 미련도.<br><br>원 밖 한 걸음 너머, 바닥 틈에 아주 작은 것이 웅크렸다. 넋 조각이다. 닦이다 튀어 나간 것. 나머지는 닦였다.<br>이 청소부는 몸만 치우지 않는다. 남는 것까지 지운다. 그래서 일이 깨끗하다. 그래서 아무도 쫓아오지 않는다.<br><br>넋 조각에게 고개를 숙였다. 그것이 쪽문 쪽을 가리키다 사라졌다. 남은 것이 없는 자리에서 사라진 것의 모양을 읽었다. 빈 데를 보는 눈이 하나 늘었다.`,
      ng:`원 안에 발을 들였다. 표백제가 신발 밑창으로 스몄다.<br><br>발바닥이 화끈하다. 그리고 차갑다. 무언가 이쪽 기운까지 닦아 간다.<br>물러났을 때 머리가 텅 비어 이름 하나를 잠깐 잊었다. 일행의 이름이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'② 가지런한 고무장갑을 주워 품에 넣는다.', k:'luck', dc:20,
      ok:`장갑을 집었다. 안쪽이 아직 따뜻하다. 표백제 냄새가 짙다.<br><br>넋을 닦는 냄새다. 이쪽에게도 쓸모가 있다. 씐 것이 붙으면 이걸로 닦으면 된다.<br>장갑을 접어 품에 넣었다. 주인은 한 짝을 잃은 걸 알 것이다. 손가락을 가지런히 모아 둔 사람은 그런 걸 안다.`,
      ng:`집는 순간 장갑 손가락이 이쪽 손가락 사이로 깍지를 꼈다. 주인의 버릇이 남았다.<br><br>떼어 냈다. 손가락 사이 살갗이 표백제에 탔다.<br>쪽문 밖에서 장화 소리가 났다. 뽀득. 한 짝을 찾으러 오는 걸음이다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B1', t:'냉동 창고 — 고기 사이 입김',
  x:`냉동 창고 천장 레일에 고기가 매달려 한 칸씩 움직인다.<br><br>
    고기 사이에서 하얀 입김이 한 줄 새어 나온다. 가늘게, 끊겼다 이어진다.<br>
    퇴마사는 입김을 가린다. 산 사람 입김은 아래로 깔리며 퍼진다. 산 것이 아닌 것의 입김은 위로 곧게 선다.<br><br>
    이 입김은 반쯤 깔리고 반쯤 선다.`,
  o:[
    { l:'① 입김의 주인을 끝까지 가린다.', k:'gaze', dc:21,
      ok:`오래 봤다. 깔리는 입김은 고기 뒤 사람 무릎 높이에서. 서는 입김은 그보다 위에서.<br><br>둘이다. 산 사람 하나가 웅크렸고, 그 사람 머리 위에 무언가가 서서 같이 숨을 쉰다. 숨을 맞추면 들킬 일이 없다.<br>고기를 밀어 젖혔다. 웅크린 사람은 하역부 차림의 젊은이. 이쪽을 보고 입을 틀어막는다. 그 머리 위 것에게 소금을 뿌렸다. 위로 서던 입김이 흩어졌다.<br><br>젊은이가 떨며 품에서 언 고기 한 덩이를 내밀었다. 레일에서 몰래 떼어 둔 것이다. 「먹고 버티려고.」`,
      ng:`가리는 사이 레일이 움직였다. 고기가 밀려와 입김을 가렸다.<br><br>다시 찾았을 때 입김은 이쪽 등 뒤에 있었다. 위로 곧게.<br>돌아서다 언 고기에 얼굴을 부딪쳤다. 광대가 터졌다. 피가 바로 얼었다.`,
      win:{ exp:20, item:'짐승 고기' }, lose:{ hp:-26, spirit:-12 } },
    { l:'② 마력을 내려 고기 사이를 비춘다.', k:'sense', dc:21, cost:{ mana:22 },
      ok:`손바닥에 마력을 모아 낮게 펼쳤다. 빛은 아니다. 산 것과 아닌 것이 다르게 드러나는 기운.<br><br>고기 사이로 기운을 흘렸다. 고기는 아무 빛도 안 낸다. 한 자리만 따뜻하게 떴다. 사람 하나. 그 위로 차갑게 뜬 것 하나.<br>찬 것이 기운에 닿자 움츠러들었다. 레일 끝 어둠으로 미끄러져 갔다. 웅크린 사람이 처음으로 크게 숨을 내쉬었다.`,
      ng:`마력을 펼치는데 추위에 손이 곱아 기운이 흩어졌다.<br><br>흩어진 기운이 찬 것을 깨웠다. 레일 끝에서 사슬이 세게 당겨졌다.<br>고기들이 한꺼번에 밀려왔다. 갈고리 하나가 어깨를 찍었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'야적장 — 노인의 모자',
  x:`방금까지 맨 뒤에 있던 늙은 하역부가 없다. 골목 바닥에 그의 모자만 떨어져 있다.<br><br>
    모자 둘레가 깨끗하다. 빗물조차 고이지 않았다. 표백제 냄새. 대걸레 폭만큼 깨끗한 줄이 컨테이너 사이로 이어진다.<br>
    모자를 본다. 사람이 끌려가면 겁이 떨어진다. 겁은 표백제로도 잘 안 지워진다. 가장 늦게 마른다.<br><br>
    모자 안감에 아직 무언가 떨고 있다.`,
  o:[
    { l:'① 모자에 남은 겁을 따라간다.', k:'gaze', dc:21,
      ok:`모자를 들고 눈을 가늘게 떴다. 안감에서 떨던 것이 한쪽으로 쏠린다. 깨끗한 줄이 아니라 그 반대쪽으로.<br><br>깨끗한 줄은 보라고 낸 길이다. 노인의 겁은 다른 데로 갔다. 컨테이너 밑 틈으로.<br>틈을 들여다봤다. 노인의 신발 한 짝. 그리고 끌린 자국이 수로 쪽으로. 줄을 따라갔으면 기다리던 손전등 다섯 앞에 섰을 것이다.`,
      ng:`겁을 따라가다 이쪽 겁이 섞였다. 어느 게 노인 것인지 모른다.<br><br>깨끗한 줄을 따라갔다. 줄 끝에서 손전등이 켜졌다. 셋.<br>컨테이너 사이로 뛰어들다 녹슨 모서리에 옆구리가 찢겼다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-12 } },
    { l:'② 마력으로 모자에 남은 넋을 불러 길을 묻는다.', k:'gaze', dc:22, cost:{ mana:26 },
      ok:`모자를 두 손으로 받쳐 들고 마력을 안감에 흘렸다. 부르지 않고 기다렸다. 떨던 것이 이쪽 손바닥으로 기어 나온다.<br><br>노인의 넋 한 조각. 아직 살아 있는 사람의 것이다. 살아 있는 사람의 넋은 몸 쪽으로 당긴다. 손바닥이 수로 쪽으로 기운다.<br>그 쪽으로 걸었다. 넋 조각이 손바닥에서 길을 짚는다. 걸을 때마다 조금 따뜻해진다. 몸에 가까워진다는 뜻이다.<br><br>죽은 것만 불러 봤다. 산 사람의 떨어진 조각을 손에 얹어 나침반처럼 쓰기는 처음이다. 손이 그 무게를 기억했다.`,
      ng:`흘린 마력이 너무 셌다. 넋 조각이 놀라 흩어졌다.<br><br>모자 안감이 텅 비었다. 손에 남은 건 젖은 천이다.<br>그 순간 깨끗한 줄 저쪽에서 손전등이 이쪽 손을 비췄다. 모자를 떨어뜨리고 숨었다. 숨을 너무 오래 참았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-15, spirit:-18 }, wake:1 }
  ] },

{ at:'B1', t:'방파제 — 꺼진 등대',
  x:`파도가 방파제를 넘는다. 넘을 때마다 발목까지 쓸어 간다.<br><br>
    이쪽 눈에는 물마루마다 손이 보인다. 하얀 손들. 블록 사이 검은 물에서 올라와 방파제 위를 더듬는다.<br>
    이 항구에서 빠진 것들이다. 등대가 꺼진 밤에는 올라온다. 길을 잃어서.<br><br>
    등대 문은 쇠문. 계단 위 꼭대기에 커다란 유리 렌즈가 있다.`,
  o:[
    { l:'① 마력으로 렌즈에 불을 켜 손들을 돌려보낸다.', k:'fix', dc:21, cost:{ mana:25 },
      ok:`계단을 뛰어 올라갔다. 렌즈 가운데 심지는 말라 있다. 손바닥을 대고 마력을 불씨로 눌러 넣었다.<br><br>작은 불이 렌즈를 지나며 커진다. 빛이 바다로 길게 누웠다.<br>방파제를 더듬던 하얀 손들이 하나씩 빛 쪽으로 돌아선다. 물로 내려간다. 길을 찾았다.<br><br>아래를 보니 방파제 위가 비었다. 파도만 넘는다. 손은 없다. 대신 항구 쪽 손전등 줄이 등대 불빛에 놀라 멈춰 섰다.`,
      ng:`마력을 눌러 넣는데 바람이 렌즈 틈으로 들이쳤다. 불씨가 꺼졌다. 두 번.<br><br>세 번째에 겨우 붙었다. 그 사이 방파제 아래로 내려간 일행 하나의 발목을 손이 잡았다.<br>뛰어 내려가 끌어 올렸다. 둘 다 짠물을 뒤집어썼다. 그 사람 발목에 손가락 자국이 다섯.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 물마루 사이를 골라 건너뛴다.', k:'evade', dc:21,
      doom:{ title:'물마루', what:'물속 손들에 끌려갑니다', dc:17, sec:55,
        text:`파도가 빠지는 틈을 셌다. 하나, 둘, 뛰었다.<br><br>둘째 틈이 짧았다. 물마루가 발목을 덮는다. 하얀 손이 하나, 둘, 다섯. 발목에서 무릎으로 감아 오른다.<br>방파제 가장자리로 미끄러진다. 블록 사이 검은 물이 입을 벌린다.<br><br>손들은 해칠 생각이 없다. 같이 있고 싶을 뿐이다. 그게 더 무섭다.`,
        dieText:`등대는 꺼진 채다. 파도가 방파제를 넘는다.<br><br>물마루마다 하얀 손이 보인다. 하나가 늘었다.<br>그 손은 아직 소매를 입고 있다.` },
      ok:`파도가 빠지는 틈을 셌다. 손들이 내려가는 틈도 같이 셌다. 둘은 박자가 같다.<br><br>손이 물로 내려가는 순간에만 뛰었다. 하나, 쉬고, 둘, 쉬고. 셋째 틈에서 등대 문을 잡았다.<br>돌아보니 일행이 같은 박자로 따라온다. 하얀 손들이 그 사이 방파제 위를 더듬다가 빈손으로 물러갔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B2', t:'처치실 복도 — 흔들리는 커튼',
  x:`처치실마다 문 대신 커튼이다. 커튼 밑으로 바퀴 달린 침대 다리가 보인다.<br><br>
    바람이 없는데 커튼 하나가 흔들린다. 안에서 누가 숨을 쉬는 박자로.<br>
    퇴마사는 커튼 밑 그림자를 본다. 침대 다리 그림자가 넷이면 침대 하나. 여섯이면 누가 침대 옆에 섰다.<br><br>
    흔들리는 커튼 밑 그림자는 여덟이다.`,
  o:[
    { l:'① 그림자 여덟을 하나씩 가려 본다.', k:'gaze', dc:21,
      ok:`쪼그려 앉아 셌다. 침대 다리 넷. 사람 다리 둘. 남은 둘은 굽지 않는다. 바퀴도 없다. 발목이 너무 가늘다.<br><br>사람 하나가 누웠고, 사람 하나가 그 옆에 섰고, 무언가 하나가 그 서 있는 사람 뒤에 붙어 섰다. 서 있는 사람은 직원 옷을 입었다. 직원이 아니다. 붙은 것이 그를 세워 두었다.<br>그 커튼 앞을 지나지 않았다. 반대편 벽에 붙어 지났다. 커튼이 이쪽 쪽으로 한 번 크게 흔들렸다가 멈췄다.`,
      ng:`세다가 그림자 하나가 움직였다. 커튼 밑으로 손이 나왔다. 하얗고 길다.<br><br>이쪽 신발 끈을 쥐었다. 당긴다.<br>끈을 끊고 물러났다. 커튼 안으로 신발 끈이 빨려 들어갔다. 신발이 벗겨진 채 걸었다. 발이 얼었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 방울을 커튼 사이로 굴려 안을 흔든다.', k:'luck', dc:20,
      ok:`방울을 떼어 커튼 밑으로 굴렸다.<br><br>안에서 방울이 크게 운다. 그리고 다른 소리. 누가 놀라 침대에서 굴러떨어지는 소리. 진짜 사람이다. 묶여 있다가 깼다.<br>깬 사람은 씐 것이 다시 덮기 어렵다. 커튼이 흔들림을 멈췄다. 숨 쉬는 박자가 사람 박자로 돌아왔다.`,
      ng:`방울이 굴러가다 커튼 안에서 멈췄다. 울지 않는다.<br><br>안의 무언가가 방울을 쥐었다. 이쪽 방울이 저쪽 손에 있다.<br>그날 밤 방울 소리는 이쪽이 아니라 저쪽이 낼 때만 났다. 들릴 때마다 등골이 섰다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'당직실 — 받을 사람을 찾는 전화',
  x:`당직실 전화가 운다. 다섯 번 울고 끊긴다. 열을 세면 다시 운다.<br><br>
    이 층 다른 방 전화들도 같은 박자로 운다. 받을 사람을 찾고 있다.<br>
    이건 안다. 이렇게 우는 전화는 받는 사람을 데려간다. 수화기 너머가 이쪽보다 넓다.<br><br>
    벨이 울릴 때마다 복도 커튼들이 이쪽 방향으로 조금씩 흔들린다.`,
  o:[
    { l:'① 소금을 혀 밑에 물고 수화기를 든다.', k:'gaze', dc:22,
      doom:{ title:'수화기 너머', what:'수화기 너머로 끌려갑니다', dc:17, sec:50,
        text:`소금을 물고 수화기를 들었다. 귀에 댔다.<br><br>저쪽에서 숨소리. 그리고 이쪽 이름. 천천히, 정확하게.<br>짠맛이 혀에서 녹는다. 너무 빨리 녹는다. 수화기 선이 손목에 감긴다. 귀가 수화기 안으로 당겨진다.<br><br>저쪽 목소리가 말한다. 「왔네. 이제 거기 비었지.」`,
        dieText:`당직실 전화가 운다. 다섯 번 울고 끊긴다.<br><br>복도 다른 방 전화들은 이제 안 운다. 받을 사람을 찾았다.<br>책상 위 수화기가 제자리에 놓여 있다. 선에 머리카락 몇 올이 감겼다.` },
      ok:`소금을 혀 밑에 물고 수화기를 들었다. 귀에 대지 않았다. 수화기를 책상 위에 눕혀 두었다.<br><br>저쪽 목소리가 이쪽 이름을 부른다. 귀가 없는 수화기에 대고. 받았다. 그런데 아무도 안 듣는다.<br>층 전체 전화가 멎었다. 받을 사람을 찾았으니까. 찾은 것은 수화기 하나다. 소금을 뱉고 방을 나왔다. 등 뒤에서 수화기가 혼자 오래 중얼거렸다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 전화선을 뽑는다.', k:'break', dc:20,
      ok:`벽 쪽 전화선을 잡아 뽑았다.<br><br>이 방 전화가 멎었다. 다른 방 전화들이 박자를 놓쳤다. 다섯 번 울던 것이 네 번, 여섯 번.<br>박자가 깨진 부름은 찾는 힘이 약하다. 복도 커튼들이 흔들림을 멈췄다.`,
      ng:`선을 뽑았는데 전화가 계속 운다. 선 없이.<br><br>오히려 크다. 이쪽 손에 선이 쥐어져 있다. 선 끝이 따뜻하다.<br>던지고 나왔다. 귀에서 벨 소리가 한참 떠나지 않았다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 받지 않고 벨 수를 끝까지 센다.', k:'steady', dc:20,
      ok:`문 앞에 서서 셌다. 다섯, 쉬고, 다섯. 백 번을 넘게.<br><br>받지 않는 전화는 결국 지친다. 부르는 쪽도 숨이 있다.<br>한참 뒤 벨이 넷에서 멈췄다. 셋. 다시 안 울렸다. 그동안 일행은 복도 끝까지 갔다.`,
      ng:`세다 보니 손이 수화기 위에 있다. 언제 갔는지 모른다.<br><br>일행이 팔을 쳐 냈다. 수화기가 바닥에 떨어졌다. 저쪽에서 숨소리가 새어 나온다.<br>발로 밀어 책상 밑에 넣었다. 다리가 후들거렸다.`,
      win:{ exp:15, mind:6 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B2', t:'계단참 — 벽을 보는 보호사들',
  x:`4층 계단참에 보호사 둘이 벽을 보고 섰다. 코가 벽에 닿을 만큼 가까이.<br><br>
    입속으로 숫자를 센다. 같은 박자로. 지금 예순여덟. 백이면 돌아설 것이다.<br>
    이쪽 눈에 둘의 등이 비었다. 안이 비었다. 사람 모양 껍데기에 무언가가 들어 있다. 둘에 하나가.<br><br>
    둘이 같이 숨을 쉬는 까닭이다.`,
  o:[
    { l:'① 마력으로 둘의 등에 봉인을 붙여 돌아서지 못하게 한다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`발끝으로 다가갔다. 손가락에 마력을 모아 첫째 등에 획을 그었다. 둘째 등에도. 한 획씩, 같은 박자로.<br><br>숫자가 백에 닿았다. 둘이 돌아서려 한다. 등의 획이 붙든다. 몸이 반쯤 틀어졌다 멈췄다.<br>둘은 다시 하나부터 세기 시작했다. 돌아서지 못한 것은 처음부터 다시 센다. 그 사이 계단을 다 내려갔다.`,
      ng:`둘째 등에 획을 긋는데 숫자가 멈췄다. 아흔둘에서.<br><br>둘이 같이 고개만 돌렸다. 몸은 벽을 보고 얼굴만 이쪽을 본다.<br>뒷걸음질 치다 계단을 헛디뎠다. 다섯 칸을 굴렀다. 숫자가 다시 시작됐다. 이쪽 쪽에서.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-14 } },
    { l:'② 둘에게 무엇이 들었는지 본다.', k:'gaze', dc:21,
      ok:`숨을 죽이고 등을 봤다. 비어 있는 안쪽에 하나가 길게 누웠다. 두 몸에 걸쳐서. 한쪽 몸에 머리, 한쪽 몸에 다리.<br><br>하나를 둘로 나눠 넣었다. 그래서 둘이 같이 숨 쉬고 같이 센다. 그런데 한 몸에 머리만 있다. 셈은 머리 쪽이 한다.<br>왼쪽 것 뒤를 지났다. 다리만 든 쪽. 그쪽은 세기만 하고 듣지 못한다. 계단을 다 내려갈 때까지 숫자가 한 번도 안 흔들렸다.<br><br>씐 것의 모양을 보고 어디가 머리고 어디가 다리인지 가렸다. 붙은 것을 보는 데서 붙은 것의 몸을 보는 데로 눈이 한 칸 갔다.`,
      ng:`보다가 숨이 새었다. 머리 든 쪽이 그 숨을 들었다.<br><br>숫자가 건너뛰었다. 일흔에서 아흔으로.<br>뛰었다. 등 뒤에서 백이 들렸다. 돌아서는 소리. 다음 계단참까지 쫓기다 난간에 팔꿈치를 찧었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 }
  ] },

{ at:'B2', t:'4층 개방 병동 — 깨어 있는 여자',
  x:`불 꺼진 병실에 사람들이 잔다. 숨소리가 고르다. 너무 고르다.<br><br>
    한 침대에 여자가 앉아 있다. 이쪽을 보고 손가락을 입에 댄다. 그리고 창밖을 가리킨다.<br>
    퇴마사 눈에는 자는 사람들 가슴 위가 보인다. 무언가 하나씩 앉았다. 가슴이 오르내릴 때마다 같이 오르내린다.<br><br>
    여자 가슴 위에만 아무것도 없다.`,
  o:[
    { l:'① 자는 이들의 숨에 붙은 것을 본다.', k:'gaze', dc:21,
      ok:`가슴 위 것들을 봤다. 누르지 않는다. 숨을 센다. 들이쉴 때 하나, 내쉴 때 하나.<br><br>세는 것이다. 정각 점검이 사람 수를 세듯 이것들은 숨을 센다. 숨이 고르면 사람이 있는 것이다. 여자는 그래서 깨어 있다. 깨어 있으면 숨이 불규칙하다. 세어지지 않는다.<br>일행에게 숨을 고르지 말라고 했다. 일부러 끊고, 몰아쉬고. 가슴 위 것들이 이쪽을 셀 수 없었다. 병실을 지나 창가에 닿았다.<br><br>숨의 박자로 붙은 것이 무엇을 하는지 읽었다. 이제 고른 숨소리가 무섭다. 그리고 그걸 깨는 법을 안다.`,
      ng:`보는 사이 이쪽 숨이 저절로 골라졌다. 자는 사람들 박자에 맞춰.<br><br>가슴 위가 무거워진다. 무언가 올라앉았다. 들이쉴 때 하나.<br>여자가 이쪽 뺨을 때렸다. 숨이 흐트러졌다. 무게가 내려갔다. 뺨이 얼얼하다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-15, spirit:-16 }, wake:1 },
    { l:'② 여자에게 창밖을 가리킨 뜻을 묻는다.', k:'bond', dc:20,
      ok:`여자 침대 곁에 쪼그려 앉아 입 모양으로만 물었다.<br><br>여자가 창틀을 손톱으로 두드린다. 셋. 창틀 나사가 셋 빠졌다. 넷째만 남았다. 여자가 매일 밤 하나씩 풀었다.<br>넷째를 같이 풀었다. 창이 철망째 들린다. 바깥 배관이 아래로 이어진다. 여자는 따라오지 않았다. 손을 흔들었다.`,
      ng:`묻는 입 모양이 커졌다. 숨이 소리가 됐다.<br><br>자는 사람 하나가 눈을 떴다. 가슴 위 것과 같이.<br>여자가 이쪽을 침대 밑으로 밀었다. 바닥에 오래 엎드려 있었다. 먼지를 들이켜 기침을 참느라 갈비뼈가 아팠다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 끝 문 두드림',
  x:`맨 끝 문 유리창에 김이 서렸다. 밖에서 누가 두드린다. 똑, 똑, 똑.<br><br>
    이 열차 뒤에는 칸이 없다. 선로가 빗속으로 풀려 나간다.<br>
    두드리는 소리를 듣는다. 손가락 마디 소리다. 그런데 박자가 이음매와 같다. 열차가 달리는 박자.<br><br>
    떨어진 것이 따라오고 있다.`,
  o:[
    { l:'① 두드림에 붙은 것이 무엇인지 읽는다.', k:'gaze', dc:21,
      ok:`김 서린 유리에 손을 대지 않고 봤다. 바깥에 손이 하나. 팔도 몸도 없다. 빨간 꼬리등에 하얗게 비친다.<br><br>전에 이 열차에서 떨어진 사람의 손이다. 마지막까지 문을 붙잡던 손. 놓친 뒤에도 문을 두드린다.<br>들어오려는 게 아니다. 열어 달라던 그날 밤을 아직 되풀이한다. 유리 안쪽에서 똑, 똑, 똑 두드려 주었다. 같은 박자로. 바깥 두드림이 멎었다. 누가 대답해 주기를 기다렸던 것이다.`,
      ng:`읽는 사이 일행 하나가 문고리를 잡았다. 두드림이 하도 사람 같아서.<br><br>문이 한 뼘 열렸다. 빗물과 바람이 들이친다. 바깥 손이 그 사람 손목을 잡는다.<br>둘이 매달려 끌어 들였다. 문을 닫았다. 그 사람 손목에 젖은 손가락 자국이 다섯.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 문지방에 소금 선을 긋는다.', k:'fix', dc:20,
      ok:`문지방 홈을 따라 소금을 한 줄로 부었다. 빈틈없이.<br><br>두드림이 약해졌다. 문 앞까지 왔다가 소금 선 앞에서 망설인다.<br>열차가 휠 때마다 소금이 쏠린다. 일행 하나가 쭈그려 앉아 쏠린 소금을 손으로 고른다. 그렇게 앞 칸으로 갈 때까지 지켰다.`,
      ng:`소금을 붓는데 열차가 크게 휘었다. 소금이 한쪽으로 다 쏟아졌다.<br><br>빈 쪽 틈으로 두드림이 안으로 들어왔다. 이번엔 객차 바닥에서. 이쪽 발밑에서.<br>뛰어서 앞 칸 쪽으로 갔다. 넘어진 선반 가방에 정강이를 찍었다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B3', t:'8호차 — 숨이 모자란 침대칸',
  x:`침대 스물넷. 칸마다 감색 커튼. 커튼 너머에서 숨소리가 난다.<br><br>
    숨을 센다. 스물. 넷이 모자란다.<br>
    숨 없는 커튼이 어느 것인지 모른다. 통로를 걸을 때마다 커튼 하나가 아주 조금씩 벌어진다.<br><br>
    통로 끝까지 스무 걸음.`,
  o:[
    { l:'① 숨 없는 커튼 넷을 가려낸다.', k:'gaze', dc:21,
      ok:`걸음을 멈추고 귀를 기울였다. 숨소리 스물을 하나씩 짚었다. 짚은 커튼을 머릿속에서 지웠다.<br><br>남은 넷. 그 커튼만 벌어진 틈이 안쪽에서 열렸다. 다른 커튼은 바깥 바람에 흔들린다. 그 넷은 안에서 누가 손가락으로 벌린다.<br>그 넷의 반대편 벽에 붙어 걸었다. 숨 없는 것은 숨소리를 듣고 온다. 일행에게 숨을 참게 했다. 스무 걸음을 숨 셋으로.<br><br>숨이 있는 것을 세어 숨이 없는 것을 찾았다. 있는 것으로 없는 것을 짚는 셈. 이 셈을 할 줄 알면 어둠 속에서도 수가 맞는다.`,
      ng:`세다 숨소리가 섞였다. 이쪽 일행 숨까지 셌다.<br><br>숫자가 맞는다고 믿고 걸었다. 셋째 커튼이 크게 열렸다. 손이 나와 일행 외투 자락을 쥔다.<br>잡아당겨 찢고 빠져나왔다. 외투 자락이 커튼 안으로 사라졌다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 마력으로 통로 양쪽에 봉인을 친다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`통로 입구 바닥에 손바닥을 대고 마력을 길게 흘렸다. 통로 양쪽 커튼 밑을 따라 두 줄로.<br><br>커튼이 벌어지다 멈췄다. 봉인 줄을 못 넘는다. 안에서 손가락이 커튼 밑단을 더듬다 그만둔다.<br>스무 걸음을 걸었다. 커튼은 하나도 안 벌어졌다. 통로 끝에서 손을 떼자 뒤에서 커튼 스물넷이 한꺼번에 흔들렸다.`,
      ng:`줄을 반쯤 긋다 열차가 휘었다. 손이 바닥에서 미끄러졌다.<br><br>한쪽 줄만 남았다. 반대쪽 커튼이 벌어진다. 하나, 둘.<br>뛰었다. 통로 신발들을 걷어찼다. 뒤꿈치를 무언가 스쳤다. 차갑다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B3', t:'식당칸 — 한 자리 더',
  x:`식탁 하나에 일행 수보다 한 자리가 더 차려졌다.<br><br>
    다른 접시는 다 식었다. 그 자리 수프만 김이 오른다. 숟가락이 접시 안쪽으로 기울었다.<br>
    퇴마사는 빈자리를 본다. 차려 둔 빈자리는 누구를 기다린다. 오는 것이 앉으면 그 식탁 전부가 그것의 손님이 된다.<br><br>
    웨이터가 의자를 빼 준다. 그 자리 의자를.`,
  o:[
    { l:'① 그 자리에 무엇이 앉으러 오는지 본다.', k:'gaze', dc:21,
      ok:`의자를 봤다. 쿠션이 꺼져 있다. 이미 앉았다. 보이지 않을 뿐.<br><br>수프의 김이 곧게 오르지 않고 의자 쪽으로 휜다. 먹고 있다. 김을.<br>일행을 그 식탁에 앉히지 않았다. 다른 식탁 의자를 뺐다. 웨이터가 고개를 갸웃했다. 차려진 식탁의 손님이 혼자 남았다. 혼자인 손님은 오래 못 앉아 있다. 김이 끊겼다.`,
      ng:`보는 사이 일행 하나가 다른 의자에 앉았다. 그 식탁에.<br><br>앉은 사람이 숟가락을 든다. 저도 모르게. 수프를 뜬다.<br>팔을 쳐서 숟가락을 떨어뜨렸다. 수프가 손등에 튀었다. 덴 자리가 얼음처럼 차다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 그 자리에 대신 앉아 먼저 자리를 차지한다.', k:'steady', dc:22,
      doom:{ title:'빈자리', what:'식탁에 붙들렸습니다', dc:17, sec:50,
        text:`웨이터가 빼 준 의자에 먼저 앉았다. 차지하면 오는 것이 못 앉는다.<br><br>앉는 순간 의자가 따뜻하다. 무릎 위에 누가 앉아 있다. 이쪽이 그 위에 앉았다.<br>무릎 위의 것이 이쪽 허리를 감는다. 일어설 수 없다. 숟가락이 손에 쥐여진다. 수프 김이 얼굴을 덮는다.<br><br>웨이터가 고개를 숙인다. 「다 오셨군요.」`,
        dieText:`식당칸에 불이 환하다. 식탁마다 하얀 천.<br><br>식탁 하나에 일행 수보다 한 자리가 더 차려졌다.<br>그 자리 수프만 식지 않는다. 숟가락이 접시 안쪽으로 기울었다.` },
      ok:`의자에 앉기 전에 쿠션에 소금을 한 줌 뿌렸다. 그 위에 앉았다.<br><br>엉덩이 밑에서 무언가 지글거리며 빠져나간다. 미끄러지듯 바닥으로, 식탁 밑으로, 칸 끝으로.<br>수프 김이 끊겼다. 식었다. 웨이터가 이쪽을 오래 봤다. 「손님께서 앉으셨군요.」 그리고 접시를 거둬 갔다. 이쪽은 그 자리에서 일어났다. 아무도 안 잡았다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'B3', t:'2호차 — 입마개 한 개들',
  x:`화물칸 쇠 우리마다 큰 개가 엎드렸다. 입마개를 했다. 얼굴 냄새를 맡는 코다.<br><br>
    누가 이 열차의 그것을 잡으려고 실었다. 그런데 개들이 맡는 쪽은 그것이 아니다. 이쪽이다.<br>
    이쪽 눈에 보인다. 개 코끝마다 가는 김이 걸렸다. 그것이 개 코에 제 냄새 대신 일행 냄새를 묻혀 두었다.<br><br>
    우리 하나는 문이 열렸다. 안이 비었다.`,
  o:[
    { l:'① 개 코끝에 걸린 것을 본다.', k:'gaze', dc:21,
      ok:`우리 앞에 쪼그려 앉았다. 개와 눈높이를 맞췄다. 코끝 김을 봤다.<br><br>김이 개 콧구멍 둘레를 막처럼 덮었다. 그 막 위에 일행 외투 냄새가 묻었다. 개는 막을 통해 맡는다. 막에 묻은 것을.<br>소매로 개 코를 닦아 주었다. 개가 재채기를 했다. 고개를 들어 공기를 맡는다. 그리고 낮게 으르렁거렸다. 이쪽이 아니라 빈 우리 쪽을 향해.`,
      ng:`보는 사이 개가 이쪽 냄새를 맡았다. 입마개 사이로 이를 드러낸다.<br><br>여섯 마리가 한꺼번에 일어섰다. 우리가 덜컹거린다.<br>뒷걸음질 치다 상자에 걸려 넘어졌다. 우리 틈으로 앞발이 나와 종아리를 긁었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 열린 우리의 개가 어디 있는지 찾아 달랜다.', k:'bond', dc:21,
      doom:{ title:'빈 우리', what:'개들에게 끌려갑니다', dc:17, sec:50,
        text:`빈 우리 둘레를 살폈다. 상자 그늘에 개가 엎드렸다. 입마개가 벗겨졌다.<br><br>손바닥을 내밀었다. 개가 냄새를 맡는다. 그것이 묻혀 둔 냄새를.<br>개가 손목을 문다. 놓지 않는다. 끈다. 화물칸 바닥을, 상자 사이를, 뒤쪽 어둠으로. 우리 속 다섯이 한꺼번에 짖는다.<br><br>어둠 저쪽에 누가 서 있다. 개를 실은 사람의 얼굴로.`,
        dieText:`화물칸이다. 쇠 우리가 여섯. 문은 다 닫혔다.<br><br>개 여섯이 엎드렸다. 입마개를 했다. 코가 움직인다.<br>우리 꼬리표에 추가된 이름이 하나 있다.` },
      ok:`상자 그늘에 개가 엎드렸다. 입마개가 벗겨졌다. 손바닥을 내밀기 전에 손에 소금을 비볐다.<br><br>개가 냄새를 맡는다. 짠 냄새. 묻혀 둔 냄새가 소금에 덮였다. 개가 혀로 손바닥을 핥았다.<br>개가 일어나 꼬리를 흔들며 앞장섰다. 얼음 칸 쪽이 아니라 반대쪽 상자 틈으로. 사람이 모르는 길을 개가 안다.`,
      win:{ exp:23, dream:3 } },
    { l:'③ 마력을 개 코끝에 묻혀 그것의 냄새를 가르쳐 준다.', k:'sense', dc:21, cost:{ mana:26 },
      ok:`손가락 끝에 마력을 모았다. 그것이 지나간 자리, 빈 우리 문고리에 대고 냄새를 떴다. 그 손가락을 개 코끝에 댔다.<br><br>개가 몸을 떨었다. 털이 선다. 다른 우리 개들에게도 하나씩 묻혔다.<br>여섯 마리가 동시에 한쪽을 향해 으르렁거렸다. 화물칸 앞쪽 문. 그쪽에 무언가 서 있다가 문을 닫고 물러났다. 개들이 그것을 안다. 이제 이 칸은 이쪽 편이다.`,
      ng:`마력을 묻히는 사이 개 하나가 손가락을 물었다. 입마개 틈으로.<br><br>이빨이 뼈에 닿는다. 빼냈다. 피가 바닥에 떨어진다.<br>피 냄새에 여섯 마리가 다 이쪽을 향했다. 우리가 흔들린다. 물러나 문 뒤에 숨어 한참 숨을 골랐다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-12 } }
  ] }
]);

// ------------------------------------------
// 관상가 · 내공
// ------------------------------------------
kJob('physiog', 'B', [

{ at:'B', t:'네온 아래 — 물든 안색',
  x:`길 건너 간판 불빛이 일행 얼굴을 칠한다. 붉게, 그다음 초록으로. 깜빡일 때마다.<br><br>
    관상가는 안색으로 사람 몸을 읽는다. 붉으면 아직 괜찮다. 파리하면 늦기 직전이다.<br>
    지금은 다 붉다가 다 파랗다. 누가 다쳤는지, 누가 지쳤는지 안 보인다.<br><br>
    일행 하나가 괜찮다고 한다. 목소리가 낮게 깔렸다.`,
  o:[
    { l:'① 흰자와 입술 안쪽으로 안색을 다시 읽는다.', k:'gaze', dc:21,
      ok:`네온은 살갗을 칠한다. 젖은 데는 못 칠한다. 눈 흰자와 입술 안쪽을 봤다.<br><br>괜찮다는 사람 흰자가 누렇다. 입술 안쪽이 하얗다. 피가 많이 빠졌다. 외투 안에서 어디가 젖고 있다. 빗물이 아니다.<br>외투를 열게 했다. 옆구리에 베인 상처. 처음 셔터 앞에서 긁힌 것이 벌어졌다. 천으로 꽉 묶었다.<br><br>빛에 물든 얼굴에서도 빛이 못 닿는 데만 골라 보는 법. 이제 붉은 불 아래서도 얼굴이 제 색으로 읽힌다.`,
      ng:`흰자를 보려 얼굴을 가까이 대자 그 사람이 고개를 돌렸다. 괜찮다는데 왜 그러느냐고.<br><br>실랑이하는 사이 간판이 꺼졌다. 어둠이다. 그 사람이 휘청했다.<br>붙잡다 둘이 같이 넘어졌다. 이쪽 무릎이 깨졌다. 그 사람 상처는 더 벌어졌다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 내공을 눈에 모아 빛을 걷어 낸다.', k:'gaze', dc:21, cost:{ qi:24 },
      ok:`단전에서 내공을 끌어 올려 눈 뒤에 모았다. 눈꺼풀이 뜨겁다. 깜빡이는 빛이 느려진다. 붉음과 초록 사이 한 박자가 길게 늘어난다.<br><br>그 한 박자에 본래 안색이 보인다. 괜찮다는 사람 얼굴만 잿빛이다.<br>그 사람을 가운데 세우고 걸었다. 쓰러지기 전에 업을 수 있게.`,
      ng:`내공이 눈에 몰리자 눈이 따갑다. 네온이 칼처럼 찌른다.<br><br>눈물이 쏟아졌다. 한동안 아무 얼굴도 안 보였다.<br>더듬어 걷다 쓰레기통을 걷어찼다. 소리가 골목을 울렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-20, spirit:-16 } },
    { l:'③ 일행을 간판 빛이 안 닿는 그늘로 데려가 본다.', k:'sense', dc:20,
      ok:`처마 밑 그늘을 찾았다. 빛이 안 닿는다. 대신 어둡다.<br><br>성냥 하나를 켰다. 노란 불은 얼굴을 덜 속인다. 하나씩 비췄다. 셋째 사람 얼굴이 잿빛이다.<br>성냥이 다 타기 전에 봤다. 그거면 됐다.`,
      ng:`그늘을 찾아 골목 안쪽으로 들어갔다. 막다른 데다.<br><br>성냥을 켜자 막다른 벽에 누가 기대 서 있다. 이쪽을 본다.<br>돌아 나왔다. 뛰다가 일행 하나가 발목을 접질렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B', t:'빗속 — 젖은 얼굴',
  x:`처마 밑에 여자가 서 있다. 머리부터 젖었다. 「우리 애가 저쪽으로 끌려갔어요. 같이 가 주세요.」<br><br>
    얼굴에 물이 흐른다. 빗물인지 눈물인지 모른다.<br>
    우는 얼굴을 읽는다. 진짜 울면 콧방울이 벌름거리고 아랫입술이 떤다.<br><br>
    비가 그 둘을 다 감춘다. 여자가 가리킨 쪽은 불 꺼진 창고다.`,
  o:[
    { l:'① 숨과 콧방울로 우는지 아닌지 읽는다.', k:'gaze', dc:21,
      ok:`얼굴 말고 숨을 봤다. 우는 사람 숨은 들쑥날쑥하다. 들이쉴 때 끊긴다.<br><br>여자 숨은 고르다. 말할 때만 떨게 한다. 콧방울은 가만히 있다. 우는 얼굴을 만든 것이다.<br>「같이 가 드리지. 앞장서시오.」 여자 얼굴이 아주 잠깐 굳었다. 앞장서는 사람은 함정에 먼저 든다. 여자는 따라오지 않고 어둠으로 걸어 들어갔다. 창고는 그냥 지나쳤다.`,
      ng:`숨을 보는 사이 빗소리가 너무 컸다. 들리지 않았다.<br><br>믿었다. 따라갔다. 창고 문 앞에서 여자가 뒤로 물러났다. 문 안에서 손이 나왔다.<br>뿌리치고 달아났다. 어깨가 문틀에 걸려 찢겼다. 여자는 끝까지 울고 있었다. 우는 얼굴로.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 우산을 씌워 주고 얼굴이 마를 때까지 본다.', k:'bond', dc:20,
      ok:`우산을 여자 머리 위로 기울였다. 이쪽 어깨가 젖었다.<br><br>얼굴이 마른다. 마른 뺨에 눈물 자국이 없다. 눈물은 마르면 소금 자국을 남긴다.<br>「아이 이름이 뭐요.」 여자가 머뭇거렸다. 대답이 늦은 이름은 지어낸 이름이다. 우산을 접고 돌아섰다.`,
      ng:`우산을 씌우자 여자가 이쪽 팔을 붙잡았다. 손이 차다. 세다.<br><br>「빨리요.」 끈다. 창고 쪽으로.<br>팔을 빼느라 우산살이 부러졌다. 부러진 살에 손바닥이 찔렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B', t:'골목 — 길을 안다는 사내',
  x:`골목 입구에 사내가 담배를 문다. 젖은 모자, 금니.<br><br>
    「뒷길 아는 사람은 나밖에 없소. 값은 나중에 받지.」 웃는다. 금니가 네온에 번쩍인다.<br>
    웃는 입이 아니라 눈가를 본다. 웃을 때 눈가가 접히지 않으면 웃는 것이 아니다.<br><br>
    사내 눈가가 접힌다. 그런데 한쪽만.`,
  o:[
    { l:'① 한쪽만 접히는 눈가를 끝까지 읽는다.', k:'gaze', dc:20,
      ok:`왼쪽 눈가만 접힌다. 오른쪽은 펴진 채다. 오른눈은 이쪽이 아니라 이쪽 뒤를 본다.<br><br>뒤에 누가 있다. 사내는 그 사람에게 웃는다. 이쪽에게는 반만.<br>「값은 지금 치르지.」 동전 하나를 사내 손에 쥐여 주고 뒷길이 아니라 앞길로 갔다. 등 뒤에서 사내가 누군가에게 고개를 젓는 기척이 났다. 일이 어그러졌다는 뜻이다.`,
      ng:`눈가를 보다가 사내 눈과 마주쳤다. 사내가 이쪽이 무엇을 보는지 봤다.<br><br>웃음이 걷혔다. 담배를 땅에 버린다. 그게 신호였다.<br>골목 양쪽에서 발소리. 담벼락을 넘다 손바닥이 깨진 병 조각에 베였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 사내의 손을 본다.', k:'sense', dc:20,
      ok:`손가락 마디에 굳은살이 없다. 뒷길을 다니는 사람 손은 담을 짚어 거칠다. 이 손은 깨끗하다.<br><br>길을 아는 손이 아니다. 길로 데려가는 손이다. 대신 손톱 밑에 생선 비늘이 끼었다. 어시장 사람이다.<br>「경매장 쪽이오?」 사내 웃음이 굳었다. 맞힌 것이다. 그쪽만 피해 갔다.`,
      ng:`손을 보려고 눈을 내리깔았다. 사내가 그 손으로 이쪽 손목을 잡았다.<br><br>「손님, 손금 보시나.」 놓지 않는다.<br>비틀어 빼냈다. 손목이 꺾였다. 사내가 웃으며 뒤로 손짓한다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 내공을 끌어올려 기세로 눌러 바른말을 받아 낸다.', k:'steady', dc:21, cost:{ qi:22 },
      ok:`숨을 깊이 들이쉬고 내공을 가슴께로 끌어 올렸다. 눈을 똑바로 보고 한 걸음 다가섰다.<br><br>사내 콧방울이 움찔한다. 기세에 밀린 얼굴은 거짓을 오래 못 붙든다. 금니가 입술 안으로 숨었다.<br>「뒷길은 막혔소. 막아 놓고 데려가는 거요. 돌아가려면 하수 뚜껑.」 그가 담배를 끄고 먼저 사라졌다.`,
      ng:`내공이 가슴에서 흩어졌다. 숨이 반만 올라왔다.<br><br>사내가 그 반을 읽었다. 겁으로. 웃음이 넓어진다.<br>「값은 비싸지겠군.」 등 뒤에서 누가 이쪽 외투를 잡았다. 빠져나오느라 단추가 다 뜯겼다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B', t:'쫓는 자 — 뒷모습',
  x:`앞서 걷는 사람이 있다. 비옷, 장화. 이쪽을 쫓던 사람이다. 지금은 이쪽이 그 뒤에 있다.<br><br>
    얼굴이 안 보인다. 뒤통수, 어깨, 뒷목뿐.<br>
    관상가는 얼굴로 사람을 읽는다. 그런데 얼굴만 상이 있는 게 아니다. 어깨에도, 걸음에도, 뒷목 주름에도 있다.<br><br>
    모퉁이가 둘 남았다. 그가 돌아보면 끝이다.`,
  o:[
    { l:'① 어깨와 뒷목으로 그 사람을 읽는다.', k:'gaze', dc:21,
      ok:`오른쪽 어깨가 처졌다. 무거운 것을 늘 그쪽에 든다. 지금도 오른손에 무언가 쥐었다.<br><br>뒷목에 땀이 아니라 김이 오른다. 서두른다. 그런데 걸음은 느리다. 몸은 서두르는데 일부러 늦춘다. 기다리는 걸음이다. 누군가 앞에서 몰아오기를.<br>앞 모퉁이에 다른 누가 있다. 이쪽은 그 모퉁이를 돌지 않고 뒤로 물러났다.<br><br>얼굴 없이 사람을 읽었다. 뒷모습에도 상이 선다는 것을 이제 눈이 안다. 얼굴을 기다릴 필요가 없다.`,
      ng:`뒷목을 보다 너무 가까이 갔다. 장화 소리가 그의 것과 겹쳤다.<br><br>그가 멈췄다. 이쪽도 멈췄다. 너무 늦게.<br>돌아본다. 오른손에 쥔 갈고리 장대가 이쪽 허벅지를 그었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-12 }, wake:1 },
    { l:'② 숨어서 그가 돌아보기를 기다린다.', k:'hide', dc:20,
      ok:`벽 틈에 몸을 넣고 기다렸다. 모퉁이에서 그가 돌아본다. 습관처럼.<br><br>얼굴이 잠깐 보였다. 젊다. 눈 밑이 검다. 사흘을 못 잤다. 쫓는 사람도 지쳤다.<br>지친 사람은 다음 모퉁이에서 또 돌아보지 않는다. 그 다음 모퉁이를 이쪽이 먼저 돌았다.`,
      ng:`틈이 얕았다. 그가 돌아보는 순간 이쪽 어깨가 틈 밖에 있었다.<br><br>손전등 빛이 어깨에 닿았다. 그가 걸음을 바꿨다.<br>뛰었다. 장화 소리가 바로 뒤에서 따라왔다. 숨이 끊어질 때까지.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'벽 — 고쳐 그린 수배 전단',
  x:`벽에 새 전단이 붙었다. 사람 얼굴 그림. 그 밑에 『이 사람을 보면 신고』.<br><br>
    그림이 일행 하나를 닮았다. 아주 닮았다. 그런데 어딘가 다르다.<br>
    그림 얼굴도 읽는다. 그린 사람 눈에 비친 대로니까.<br><br>
    길 건너 사람들이 전단과 이쪽 일행을 번갈아 본다.`,
  o:[
    { l:'① 그린 손이 무엇을 고쳤는지 읽는다.', k:'gaze', dc:21,
      ok:`그림을 봤다. 눈썹, 콧대, 턱은 그대로다. 인중만 짧게 고쳤다. 눈 밑에 그늘을 더 그렸다.<br><br>짧은 인중, 검은 눈 밑. 겁 많고 일찍 죽을 상이다. 그린 사람은 이 얼굴을 쫓기는 얼굴로 만들었다. 보는 사람이 이 얼굴을 보면 쫓고 싶어진다.<br>일행에게 고개를 들고 걷게 했다. 턱을 내밀고, 천천히. 인중이 길어 보이게. 길 건너 사람들 눈길이 전단에서 떨어졌다. 그림과 다른 얼굴이 지나간다.`,
      ng:`읽는 사이 길 건너 한 사람이 다가왔다. 전단과 일행을 번갈아 본다.<br><br>「이 사람 맞지.」 소리친다. 사람들이 돌아본다.<br>뛰었다. 젖은 계단에서 미끄러져 턱을 찧었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 전단 얼굴에 숯으로 한 획을 더 긋는다.', k:'fix', dc:20,
      ok:`숯을 쥐고 그림 인중에 한 획을 길게 그었다. 눈 밑 그늘은 손가락으로 문질러 흐렸다.<br><br>얼굴이 달라졌다. 같은 사람인데 쫓을 마음이 안 드는 얼굴이 됐다.<br>길 건너 사람들 눈길이 흩어졌다. 그림 얼굴을 고친 손이 이쪽에도 있다.`,
      ng:`그었는데 숯이 젖은 종이에서 번졌다. 얼굴이 검게 일그러졌다.<br><br>일그러진 얼굴이 더 무섭다. 지나가던 사람이 그 얼굴을 보고 비명을 질렀다.<br>사람들이 모였다. 그 틈에 빠지느라 일행 하나와 떨어졌다. 찾는 데 한참 걸렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B', t:'젖은 유리 — 지친 제 얼굴',
  x:`꺼진 진열창에 제 얼굴이 비친다. 남의 얼굴은 잘 보면서 제 얼굴은 잘 안 본다. 보면 다 보이니까.<br><br>
    광대가 꺼졌다. 귀가 하얗다. 인당이 검다.<br>
    지친 상이다. 지친 상은 다음 갈림길에서 틀린 쪽을 고른다. 관상가는 남의 얼굴에서 그걸 수십 번 봤다.<br><br>
    다음 갈림길이 바로 앞이다.`,
  o:[
    { l:'① 제 얼굴을 남의 얼굴처럼 끝까지 읽는다.', k:'gaze', dc:21,
      ok:`남이라 생각하고 봤다. 남이면 뭐라 했을까.<br><br>인당이 검은 건 이마에 묻은 기름때다. 귀가 하얀 건 추워서다. 광대는 정말 꺼졌다. 이 사람은 배가 고프고 졸리다. 그뿐이다.<br>그뿐인 사람은 갈림길에서 오래 멈추면 된다. 서두르지 말고. 오래 멈췄다. 왼쪽 길 끝에서 손전등이 켜졌다 꺼졌다. 오른쪽으로 갔다.`,
      ng:`보다 보니 제 얼굴이 남의 얼굴이 됐다. 정말로.<br><br>비친 얼굴이 이쪽보다 먼저 눈을 깜빡인다.<br>뒤로 물러나 눈을 감았다. 다시 떴을 때 유리는 그냥 유리였다. 다리가 한참 떨렸다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 내공을 돌려 안색을 되살린다.', k:'heal', dc:21, cost:{ qi:22 },
      ok:`벽에 기대 앉아 숨을 세었다. 내공을 단전에서 한 바퀴, 두 바퀴 돌렸다.<br><br>손끝에 피가 돈다. 귀에 핏기가 오른다. 진열창을 다시 봤다. 광대가 조금 섰다.<br>상은 타고나는 것만이 아니다. 고칠 수도 있다. 고쳐진 얼굴로 갈림길에 섰다.`,
      ng:`돌리던 내공이 배에서 멎었다. 너무 지쳤다. 돌릴 것이 없다.<br><br>억지로 돌리다 속이 뒤집혔다. 토했다.<br>더 지친 얼굴로 일어섰다. 유리 속 얼굴이 동정하는 눈으로 봤다.`,
      win:{ exp:18, hp:10 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'철문 — 문지기',
  x:`나가는 철문 앞에 문지기가 섰다. 덩치가 크다. 비옷 안에서 무언가 불룩하다.<br><br>
    「통행증.」 손바닥을 내민다. 통행증은 없다. 주머니에 구겨진 돈 몇 장.<br>
    문지기 얼굴을 본다. 돈 받는 얼굴과 안 받는 얼굴은 콧방울과 입꼬리가 다르다.<br><br>
    문지기 뒤 초소 유리창에 누가 이쪽을 내다본다.`,
  o:[
    { l:'① 돈을 받을 얼굴인지 읽는다.', k:'gaze', dc:21,
      ok:`콧방울이 두툼하다. 셈이 밝다. 입꼬리가 아래로 처졌다. 오래 손해 본 사람이다. 받는다. 다만 보는 눈이 있으면 안 받는다.<br><br>문지기 눈이 초소 유리창을 한 번 본다. 그거다.<br>돈을 손바닥이 아니라 문지기 장화 옆 웅덩이에 떨어뜨렸다. 문지기가 허리를 굽혀 장화 끈을 매는 척했다. 일어설 때 철문이 한 뼘 열려 있었다. 초소 쪽에서는 문지기 등만 보였다.`,
      ng:`얼굴을 너무 오래 봤다. 문지기가 그걸 알아챘다.<br><br>「내 얼굴에 뭐 묻었소.」 손바닥이 주먹이 된다.<br>주먹이 명치에 들어왔다. 숨이 끊겼다. 기어서 물러났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 눈을 내리깔고 다른 일행 뒤에 붙어 지나간다.', k:'hide', dc:21,
      doom:{ title:'문지기', what:'문지기에게 끌려갑니다', dc:17, sec:55,
        text:`고개를 숙이고 일행 등 뒤에 붙었다. 문지기가 앞사람과 실랑이하는 사이에.<br><br>지나가는 순간 커다란 손이 뒷덜미를 잡는다. 「너는 얼굴을 안 보여 주네.」<br>얼굴을 안 보이는 사람이 제일 수상하다. 얼굴을 읽는 사람이 그걸 몰랐을 리 없다. 발이 땅에서 뜬다. 초소 쪽으로.<br><br>초소 문이 열린다. 안이 어둡다. 유리창의 그 사람이 일어선다.`,
        dieText:`철문 앞에 문지기가 섰다. 덩치가 크다.<br><br>「통행증.」 손바닥을 내민다.<br>초소 유리창에 사람이 둘 내다본다. 하나는 고개를 숙이고 있다.` },
      ok:`고개를 숙이지 않았다. 숙이면 수상하다. 대신 문지기 얼굴을 안 보고 초소 유리창을 봤다. 오래.<br><br>문지기가 이쪽 눈길을 따라 뒤를 돌아본다. 유리창의 사람이 고개를 돌렸다. 둘 사이에 무언가 오갔다. 그 틈에 일행 등 뒤로 붙어 지났다.<br>사람은 남이 보는 쪽을 따라 본다. 얼굴을 읽는 사람은 남의 눈길을 옮길 줄도 안다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B', t:'젖은 사내 — 뛰는 목덜미',
  x:`붙잡힌 사내 하나를 만났다. 쫓는 쪽 사람이었다고 한다. 이제 그쪽에서도 쫓긴다고.<br><br>
    「출구를 알려 주지. 대신 나도 데려가.」 말이 매끄럽다. 얼굴은 겁먹었다.<br>
    얼굴보다 목을 본다. 거짓을 말할 때 목덜미 핏줄이 먼저 뛴다. 얼굴은 꾸며도 핏줄은 못 꾸민다.<br><br>
    사내 목은 옷깃에 반쯤 가렸다.`,
  o:[
    { l:'① 말 한마디마다 목의 맥을 맞춰 읽는다.', k:'gaze', dc:21,
      ok:`옷깃 위로 드러난 한 치를 봤다. 「출구는 동쪽.」 맥이 잔잔하다. 「나도 쫓겨.」 맥이 튄다.<br><br>출구는 맞다. 쫓긴다는 건 거짓이다. 이 사람은 데려가 달라는 게 아니라 따라오겠다는 것이다. 따라와서 어디서 손을 들지 정해 두었다.<br>동쪽으로 갔다. 사내를 맨 앞에 세웠다. 맨 앞에 선 사람은 손을 들 수 없다. 출구 앞에서 사내가 먼저 달아났다.<br><br>말과 맥을 한 줄씩 맞대는 법. 얼굴 하나로 모자랄 때 몸이 대신 털어놓는 데를 눈이 바로 찾는다.`,
      ng:`목을 보려 옷깃 쪽으로 손을 뻗었다. 사내가 움찔했다.<br><br>「뭘 보는 거요.」 매끄럽던 말이 거칠어진다. 손에 칼이 있다.<br>칼끝이 팔뚝을 그었다. 사내는 어둠으로 뛰었다. 출구가 어디인지는 끝내 못 들었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 내공을 손끝에 모아 손목 맥을 짚는다.', k:'sense', dc:21, cost:{ qi:24 },
      ok:`악수를 청했다. 사내가 손을 내밀었다. 손목에 손가락 셋을 얹고 내공을 실었다.<br><br>맥이 손끝으로 크게 들린다. 말할 때마다 흔들린다. 동쪽에서는 잔잔, 혼자서 왔다에서는 튄다.<br>손을 놓았다. 「같이 가지. 앞장서시오.」 사내가 눈을 피했다. 앞장서는 일만은 안 하려 했다.`,
      ng:`내공을 실은 손끝이 너무 셌다. 사내가 손목을 홱 뺐다.<br><br>「뭘 한 거요.」 경계하는 얼굴이 굳는다.<br>그가 휘파람을 불었다. 어둠 저쪽에서 대답이 왔다. 뛰는 내내 등이 시렸다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 늙은 하역부',
  x:`노인은 이 항구에서 삼십 년 짐을 졌다고 했다. 손이 하얗게 얼었다. 손가락이 굽은 채 안 펴진다.<br><br>
    「얼음 활송로를 알아. 경매장으로 이어지지.」<br>
    관상가는 노인 얼굴을 본다. 삼십 년 짐 진 얼굴은 목이 굵고 눈썹 사이 주름이 깊다. 맞다.<br><br>
    그런데 노인은 말하는 동안 조끼 안주머니를 자꾸 만진다.`,
  o:[
    { l:'① 눈 밑과 손으로 노인을 읽는다.', k:'gaze', dc:21,
      ok:`눈 밑이 젖었다. 추위 때문이 아니다. 오늘 밤 울었다. 그리고 손. 안주머니를 만지는 손이 지키는 손이다. 내놓을 생각은 없다.<br><br>돈 받은 얼굴이 아니다. 무언가를 뺏긴 얼굴이다. 그리고 남은 하나를 지키는 얼굴.<br>「그 주머니 건 안 묻겠소.」 노인 어깨가 내려갔다. 그는 활송로로 앞장섰다. 끝까지 앞장섰다.`,
      ng:`안주머니만 보다가 얼굴을 놓쳤다. 의심하는 얼굴이 이쪽에 떠올랐다.<br><br>노인이 그걸 봤다. 입을 다물었다. 활송로는 직접 찾아야 했다.<br>얼음물에 무릎까지 빠지며 헤맸다. 다리가 얼어 한참 감각이 없었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 안주머니에 무엇이 들었는지 묻는다.', k:'bond', dc:20,
      ok:`곁에 쪼그려 앉아 언 손을 감싸 쥐었다. 그리고 물었다.<br><br>노인이 한참 있다가 안주머니에서 꺼냈다. 젖은 사진 한 장. 아이 얼굴이다. 「손녀. 오늘 밤 배에 실린대.」<br>사진 속 아이 얼굴은 오래 살 상이다. 그렇게 말해 주었다. 노인이 사진을 도로 넣으며 말린 고기 한 줄을 내밀었다. 조끼 다른 주머니에서.`,
      ng:`묻는 순간 노인 얼굴이 닫혔다. 「상관 마.」<br><br>이쪽 손을 뿌리친다. 굽은 손가락이 이쪽 손등을 긁었다. 얼어 있어서 쇠처럼 날카롭다.<br>그 뒤로 노인은 맨 뒤에서만 걸었다. 이쪽을 안 봤다.`,
      win:{ exp:16, item:'말린 고기' }, lose:{ hp:-20, spirit:-14 } },
    { l:'③ 내공을 손바닥에 모아 언 손을 녹여 준다.', k:'heal', dc:21, cost:{ qi:20 },
      ok:`노인 두 손을 이쪽 손바닥 사이에 넣었다. 내공을 손바닥으로 밀었다. 천천히, 뼈까지.<br><br>굽은 손가락 하나가 펴진다. 둘. 노인이 제 손을 내려다본다. 삼십 년 만에 처음 보는 손처럼.<br>펴진 손으로 노인은 활송로 쇠뚜껑을 들어 올렸다. 혼자서는 못 들던 것이다.`,
      ng:`내공이 노인 손에 닿자 너무 차서 이쪽 손바닥이 먼저 얼었다.<br><br>밀던 것이 거꾸로 빨려 나온다. 이쪽 손가락이 굽는다.<br>떼었다. 두 사람 손이 다 하얗다. 한참 겨드랑이에 끼고 녹였다.`,
      win:{ exp:18, hp:8 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B1', t:'경매장 — 노란 비옷의 눈',
  x:`노란 비옷 셋이 얼음 더미를 장대로 찌른다. 한 뼘 간격으로. 빠짐없이.<br><br>
    손전등을 입에 물었다. 빛이 얼굴을 밑에서 친다. 셋 다 같은 얼굴로 보인다.<br>
    아니라는 걸 안다. 같은 일을 하는 셋이라도 겁의 크기는 다르다.<br><br>
    장대가 점점 가까워진다. 얼음이 서걱거린다.`,
  o:[
    { l:'① 셋 가운데 겁먹은 얼굴을 찾는다.', k:'gaze', dc:21,
      ok:`밑에서 친 빛은 이마와 콧등만 밝힌다. 그 대신 눈 밑 근육이 잘 보인다. 겁먹은 사람은 눈 밑이 떤다.<br><br>가운데 사람 눈 밑이 떤다. 장대를 찌를 때마다 손목이 반 박자 늦다. 처음 하는 일이다. 찌르다 무언가에 닿을까 겁낸다.<br>그 사람 쪽 얼음 더미로 옮겨 숨었다. 장대가 이쪽 어깨 한 뼘 앞에서 멈췄다. 닿기 전에 멈췄다. 그는 닿지 않은 척 다음 칸을 찔렀다.<br><br>같은 얼굴들 사이에서 떨리는 근육 하나를 찾았다. 빛이 얼굴을 지워도 겁은 안 지운다. 그 근육이 이제 먼저 보인다.`,
      ng:`셋을 번갈아 보다 시간을 너무 썼다.<br><br>맨 오른쪽 장대가 얼음을 뚫고 이쪽 허벅지에 닿았다. 갈고리 끝이 살을 문다.<br>얼음째 빠져나와 굴렀다. 피가 얼음 위에 길게 끌렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-12 }, wake:1 },
    { l:'② 얼음 더미 깊숙이 파고들어 숨는다.', k:'hide', dc:22,
      doom:{ title:'얼음 더미', what:'장대에 찍혀 끌려갑니다', dc:17, sec:50,
        text:`얼음 더미 속으로 파고들었다. 깊이, 숨이 막힐 만큼.<br><br>얼음이 몸을 덮는다. 차갑다. 장대 소리가 위에서 서걱거린다. 한 뼘, 또 한 뼘.<br>갈고리 끝이 외투를 꿰었다. 당긴다. 얼음이 무너지며 몸이 끌려 나온다. 손전등 셋이 얼굴을 비춘다.<br><br>「하나 찾았다.」 셋의 목소리가 다 똑같다.`,
        dieText:`얼음 더미가 고르게 다시 쌓였다.<br><br>노란 비옷 둘이 장대를 어깨에 메고 간다. 하나는 장대 끝에 무언가를 끌고.<br>경매판에 분필 줄이 하나 그어졌다.` },
      ok:`얼음 더미 속으로 파고들기 전에 셋 얼굴을 한 번 봤다. 가운데 사람 쪽 더미를 골랐다.<br><br>장대 소리가 가까워진다. 가운데 사람 장대가 이쪽 위 얼음에 닿았다. 멈칫. 그리고 그 칸을 건너뛰었다.<br>셋이 지나갔다. 얼음에서 나왔을 때 입술이 파랬다. 그래도 숨은 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B1', t:'방파제 — 우산 밑의 턱',
  x:`방파제 끝에 우산이 서 있다. 이 바람에도 안 뒤집힌다.<br><br>
    「늦었네. 장부는?」 반갑게 손을 흔든다. 다른 손에 손전등. 엄지가 스위치 위에 있다.<br>
    얼굴은 끝까지 우산 밑이다. 보이는 건 턱과 입뿐이다.<br><br>
    얼굴 반쪽은 얼굴이 아니다. 그래도 지금은 그것밖에 없다.`,
  o:[
    { l:'① 턱과 입꼬리만으로 그를 읽는다.', k:'gaze', dc:21,
      ok:`말할 때 아래턱이 왼쪽으로 조금 돌아간다. 이를 문 채 말하는 버릇이다. 속으로 다른 말을 참는 사람이다.<br><br>「늦었네」 할 때 입꼬리가 올라갔다. 「장부는」 할 때 입꼬리가 내려갔다. 반가운 건 이쪽이 아니라 이쪽이 왔다는 것이다. 장부는 핑계다. 엄지는 신호다. 불을 켜면 누가 온다.<br>장부 대신 빈 손을 들어 보이며 옆으로 비켜섰다. 그가 엄지를 누르기 전에 등대 그늘로 들어갔다.<br><br>얼굴 반쪽으로 사람 하나를 다 세웠다. 가린 쪽보다 드러난 쪽이 더 많이 말한다는 것을 이제 믿는다.`,
      ng:`입꼬리를 보다 그의 엄지를 놓쳤다.<br><br>손전등이 켜졌다. 방파제 저쪽에서 손전등 줄이 대답했다.<br>뛰었다. 파도가 발목을 쓸었다. 블록 모서리에 무릎을 찍었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 },
    { l:'② 내공을 끌어올려 기세로 우산을 젖히게 한다.', k:'steady', dc:21, cost:{ qi:26 },
      ok:`한 걸음 앞으로 나섰다. 내공을 가슴에서 눈으로 끌어 올려 우산 밑 어둠을 똑바로 봤다.<br><br>우산이 흔들렸다. 바람 때문이 아니다. 들고 있는 손이 떨었다. 기세에 밀린 손이 우산을 젖힌다. 얼굴이 드러났다. 평범하다. 그래서 무섭다.<br>얼굴을 들킨 그는 더 웃지 못했다. 손전등을 켜지 않고 배 쪽으로 물러났다. 얼굴을 보인 일은 해 본 적이 없는 사람이다.`,
      ng:`내공이 바람에 흩어졌다. 기세가 반만 나갔다.<br><br>우산이 젖혀지지 않았다. 대신 손전등이 켜졌다.<br>하얀 빛이 눈을 찔렀다. 앞이 안 보인 채 뛰다 방파제 가장자리에서 미끄러졌다. 블록에 매달려 겨우 올라왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'경비 초소 — 조는 경비원',
  x:`정문 옆 초소. 유리창에 김이 서렸다. 경비원이 의자에서 존다. 고개가 가슴에 닿았다.<br><br>
    벽에 정문 열쇠가 걸렸다. 무전기가 지직거린다. 「정문. 다섯 확인했나.」<br>
    관상가는 자는 얼굴을 안다. 진짜 잠은 입이 벌어지고 눈꺼풀이 무겁게 덮인다.<br><br>
    경비원 입이 다물렸다. 눈꺼풀 밑이 아주 조금 움직인다.`,
  o:[
    { l:'① 눈꺼풀과 숨으로 잠인지 아닌지 가린다.', k:'gaze', dc:20,
      ok:`숨을 셌다. 자는 숨은 길고 느리다. 이 숨은 짧다. 눈꺼풀 밑 눈동자가 무전기 쪽으로 간다.<br><br>안 잔다. 듣고 있다. 그런데 일어나지 않는다. 일어나면 대답해야 하니까. 대답하기 싫은 얼굴이다.<br>초소 문을 조용히 열고 열쇠를 내렸다. 경비원은 끝까지 눈을 안 떴다. 입꼬리만 아주 조금 풀렸다.`,
      ng:`가리는 사이 무전기가 다시 울렸다. 「정문. 대답해.」<br><br>경비원이 눈을 떴다. 이쪽과 눈이 마주쳤다. 둘 다 놀랐다.<br>그가 무전기를 집었다. 뛰었다. 등 뒤에서 호루라기. 젖은 아스팔트에 손바닥이 까졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 무전기에 대신 대답한다.', k:'luck', dc:21,
      ok:`초소 문틈으로 손을 넣어 무전기를 들었다. 경비원 목소리를 흉내 냈다. 낮게, 졸린 듯이. 「다섯 확인.」<br><br>무전기가 조용해졌다. 경비원은 그대로 눈을 감고 있다. 대답을 남이 해 줬으니 편한 얼굴이다.<br>열쇠까지 내려 왔다. 그는 끝내 못 봤다. 못 본 척했다.`,
      ng:`목소리가 너무 높았다. 무전기 저쪽이 잠깐 조용하다가 물었다. 「누구야.」<br><br>경비원이 눈을 번쩍 떴다. 무전기를 낚아챈다.<br>도망치다 초소 문에 손가락이 끼었다. 손톱이 들렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 경비원 얼굴 앞에서 일부러 기침한다.', k:'bond', dc:21,
      ok:`초소 유리를 두드리고 기침을 했다. 경비원이 눈을 떴다. 이쪽을 본다.<br><br>얼굴에 겁이 있다. 이 사람도 오늘 밤 여기 있기 싫다. 그 얼굴에 대고 고개를 한 번 끄덕였다. 같은 처지라는 뜻으로.<br>경비원이 한참 보다가 열쇠를 유리창 밑 틈으로 밀어 주었다. 그리고 다시 고개를 숙였다. 자는 척.`,
      ng:`경비원이 눈을 떴다. 얼굴에 겁이 있다. 겁은 사람을 빨리 움직이게 한다.<br><br>그가 바로 무전기를 잡았다. 「정문. 하나 있다.」<br>뛰었다. 정문 철망에 외투가 걸려 찢어졌다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B2', t:'정각 점검 — 마스크 위의 눈',
  x:`간호사가 병실 문 앞에 선다. 흰 모자, 흰 마스크. 계수기를 쥐었다.<br><br>
    보이는 얼굴은 눈 둘과 눈썹뿐이다. 다음 병실, 그다음 병실의 간호사도 같다. 같은 눈.<br>
    마스크를 싫어한다. 입과 코가 반을 말하는데 그 반이 가려졌다.<br><br>
    간호사가 이쪽 침대 명패의 이름을 부른다. 대답해야 한다.`,
  o:[
    { l:'① 마스크 위 눈만으로 그것을 읽는다.', k:'gaze', dc:21,
      ok:`눈을 봤다. 웃지도 찡그리지도 않는다. 그런데 이름을 부를 때 눈꼬리가 아주 조금 내려간다. 맞는 이름을 부를 때만.<br><br>틀린 이름을 부르면 눈꼬리가 그대로다. 이것은 대답을 듣는 게 아니라 이름이 맞는지를 본다. 명패 이름과 사람이 맞으면 센다.<br>대답하지 않고 기침만 했다. 눈꼬리가 안 내려갔다. 계수기가 안 눌렸다. 다음 침대로 넘어갔다. 셈에서 빠졌다.<br><br>눈 둘로 얼굴 하나를 다 읽었다. 가린 얼굴도 얼굴이다. 이제 눈꼬리 한 올의 움직임이 입보다 먼저 들린다.`,
      ng:`눈을 보다가 마주쳤다. 마스크 위 눈이 이쪽 눈을 읽는다. 똑같이.<br><br>계수기가 눌렸다. 하나. 그리고 한 번 더. 하나 더 센다. 이쪽 몸 안 무언가를.<br>간호사가 지나간 뒤 한참 손발이 무겁고 차가웠다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'② 명패 이름에 그냥 대답한다.', k:'steady', dc:20,
      ok:`「네.」 짧게 대답했다. 목소리를 낮게, 아무 느낌 없이.<br><br>계수기가 눌렸다. 간호사가 다음 침대로 갔다. 센 것은 명패다. 사람이 아니다.<br>대답한 입이 쓰다. 남의 이름으로 한 번 대답하면 그 이름이 반쯤 붙는다. 반은 이쪽이 지켰다.`,
      ng:`대답하는데 목소리가 이쪽 것이 아니었다. 명패 이름 주인의 목소리였다. 아마.<br><br>간호사가 고개를 갸웃했다. 계수기를 두 번 눌렀다.<br>한참 이쪽 이름이 기억나지 않았다. 일행이 귀에 대고 불러 줄 때까지.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B2', t:'기록 보관실 — 창가의 경비원',
  x:`창가에 경비원이 담배를 피운다. 명찰에 『오』. 글자가 닳았다.<br><br>
    어깨가 젖었다. 신발도 젖었다. 이 건물에서 밖에 나갔다 온 사람은 처음 본다.<br>
    그가 이쪽을 보고 담배를 끈다. 놀라지 않는다. 「나가는 길 찾소? 나도 찾소. 같이 찾지.」<br><br>
    관상가는 반가운 얼굴을 제일 오래 본다.`,
  o:[
    { l:'① 반가운 얼굴 밑을 읽는다.', k:'gaze', dc:21,
      ok:`웃는다. 눈가가 접힌다. 진짜 웃음이다. 그런데 웃음이 이쪽 얼굴에 오래 머물지 않는다. 일행 머릿수에 머문다. 하나, 둘, 셋.<br><br>세면서 웃는 얼굴이다. 반가운 건 사람이 아니라 숫자다. 숫자가 맞으면 그는 나간다. 누가 남아야.<br>「먼저 찾으시오. 우리는 쉬었다 가겠소.」 그의 웃음이 아주 잠깐 굳었다. 그리고 모자를 쓰고 먼저 나갔다. 다음에 만나면 그는 뒷문을 가리킬 것이다.`,
      ng:`웃음에 마음이 풀렸다. 오래 본 게 아니라 오래 기대고 싶었다.<br><br>그를 따라 몇 걸음 갔다. 그가 일행을 세며 걷는다. 일행 하나가 처졌다. 그가 그 사람을 기다렸다. 아주 친절하게.<br>그 사람을 끌어당겨 돌아섰다. 그의 손이 그 사람 팔을 오래 놓지 않았다. 떼어 내다 손목이 꺾였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 담배를 권하며 시간을 번다.', k:'bond', dc:20,
      ok:`주머니에서 젖은 담배를 꺼내 내밀었다. 그가 받았다. 불을 붙이려 애쓴다. 젖어서 안 붙는다.<br><br>그 사이 일행은 서가 뒤로 돌아 덕트 쪽으로 갔다. 그는 담배에 정신이 팔렸다. 오래 혼자 있던 사람은 작은 일에 오래 매달린다.<br>불이 붙었을 때 이쪽은 덕트 앞에 있었다.`,
      ng:`담배를 내미는 손을 그가 잡았다. 「손이 차네. 오래 있었구먼.」<br><br>놓지 않는다. 웃으며. 손목을 꽉.<br>빼내려 비틀다 서가에 등을 부딪쳤다. 서가가 레일 위로 밀려왔다. 겨우 빠져나왔다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-24, spirit:-12 } },
    { l:'③ 내공을 손끝에 모아 그의 맥을 짚는다.', k:'sense', dc:21, cost:{ qi:22 },
      ok:`악수를 했다. 손목에 손끝을 얹고 내공을 실었다.<br><br>맥이 고르다. 너무 고르다. 정각마다 도는 딸깍 소리와 같은 박자다. 이 사람 몸은 이 건물 박자로 뛴다. 오래 있으면 그렇게 된다.<br>그의 손을 놓았다. 이 사람은 나가고 싶다. 몸은 못 나간다. 그 둘 사이에서 누가 대신 남아 주기를 기다린다. 따라가지 않기로 했다.`,
      ng:`손끝에 실은 내공이 그 박자에 휘말렸다. 이쪽 맥도 딸깍 소리에 맞춰 뛴다.<br><br>손을 뗐다. 맥이 돌아오지 않는다.<br>한참 가슴을 치며 숨을 일부러 흐트러뜨렸다. 겨우 제 박자가 돌아왔다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'B2', t:'퇴원 수속 창구 — 입이 안 움직이는 웃음',
  x:`창구 유리 너머에 직원이 앉아 웃는다. 마스크가 없다. 그래서 더 웃는 것 같다.<br><br>
    『퇴원 확인서에 직인이 없으면 정문을 통과할 수 없습니다.』 직원 팔꿈치 옆에 직인. 인주가 빨갛게 젖었다.<br>
    웃음을 읽는다. 그런데 이 웃음은 입이 안 움직인다. 말할 때도.<br><br>
    「확인서 주세요.」 입술이 그대로다. 목소리만 나온다.`,
  o:[
    { l:'① 움직이지 않는 웃음이 무엇을 가리는지 읽는다.', k:'gaze', dc:21,
      ok:`입이 안 움직이는데 목이 움직인다. 소리는 목에서 나온다. 얼굴은 그림이다. 얼굴 가죽을 웃는 모양으로 고정했다.<br><br>그림 얼굴은 눈을 깜빡여도 눈가가 안 접힌다. 그런데 직인 쪽을 볼 때만 눈썹 끝이 떤다. 직인이 이것의 약한 데다. 직인을 안 쓰면 이것도 할 일이 없다.<br>확인서를 내지 않았다. 「직인은 거기 두시오.」 유리 너머 웃음이 그대로인 채 눈썹만 오래 떨었다. 창구 옆 구급차 통로로 갔다.`,
      ng:`웃음을 보다 그 웃음이 이쪽 얼굴에 옮아왔다. 입꼬리가 저절로 올라간다.<br><br>안 내려간다. 볼이 굳는다.<br>손으로 입을 눌러 내렸다. 한참 지나서야 풀렸다. 볼 근육이 쑤신다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 유리 밑 틈으로 손을 넣어 직인을 집는다.', k:'luck', dc:22,
      doom:{ title:'창구', what:'창구 안으로 끌려갑니다', dc:17, sec:50,
        text:`유리 밑 서류 틈으로 손을 넣었다. 직인을 쥐었다.<br><br>직원 손이 이쪽 손목 위에 얹힌다. 웃는 채로. 「손님 확인서에 찍어 드릴게요.」<br>손목이 틈 안으로 당겨진다. 팔꿈치까지. 어깨가 유리에 눌린다. 틈은 서류 한 장 너비인데 팔이 계속 들어간다.<br><br>손등에 인주가 찍힌다. 빨갛게. 『퇴원 불가』.`,
        dieText:`창구 유리 너머에 직원이 앉아 웃는다. 둘이다.<br><br>둘 다 마스크가 없다. 둘 다 입이 안 움직인다.<br>직인 옆에 확인서가 한 장 쌓였다. 빨간 글씨로.` },
      ok:`손을 넣기 전에 직원 눈썹을 봤다. 직인을 볼 때 떤다. 이쪽 손을 볼 때는 안 떤다. 손이 아니라 직인을 지킨다.<br><br>그래서 손을 넣지 않았다. 확인서 종이를 틈에 끼워 넣었다. 직원이 습관처럼 직인을 들어 찍었다. 웃는 채로.<br>찍힌 종이를 빼냈다. 『퇴원 확인』. 할 일을 한 얼굴은 더 붙잡지 않는다. 웃음이 그대로였다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'B2', t:'중앙 계단 — 같은 얼굴들',
  x:`2층에서 1층으로 내려가는 계단. 양옆으로 직원들이 줄지어 섰다.<br><br>
    간호사, 보호사, 배식 직원, 원무과 직원. 다 같은 얼굴이다. 계수기에 엄지를 얹었다.<br>
    같은 얼굴은 없다. 쌍둥이도 다르다. 같아 보인다면 볼 데를 안 본 것이다.<br><br>
    발이 계단에 닿는 순간 엄지들이 내려갈 것이다.`,
  o:[
    { l:'① 같은 얼굴들 사이에서 다른 하나를 찾는다.', k:'gaze', dc:22,
      ok:`한 얼굴씩 봤다. 눈, 코, 입은 같다. 귀를 봤다. 같다. 마지막으로 이마 주름을 봤다.<br><br>스물이 다 주름이 없다. 하나만 이마에 주름이 셋. 걱정을 오래 한 사람의 주름이다. 이 사람은 원래 사람이다. 얼굴을 덮어썼지만 주름까지는 못 지웠다.<br>그 사람 앞으로 걸어가 눈을 맞췄다. 그 사람 엄지가 떨렸다. 누르지 않았다. 다른 엄지들이 눌리기 전에 그 사람이 계수기를 떨어뜨렸다. 소리에 다들 그쪽을 봤다. 그 틈에 계단을 다 내려갔다.<br><br>같은 얼굴 스물에서 다른 하나를 찾는 데 이마 한 줄이면 됐다. 이제 얼굴을 볼 때 맨 나중에 보던 데부터 본다.`,
      ng:`보다가 다 같아 보였다. 눈이 지쳤다. 이마도 귀도 다 같다.<br><br>그때 발이 계단에 닿았다. 엄지들이 한꺼번에 내려갔다. 딸깍.<br>소리가 몸을 친다. 무릎이 꺾였다. 일행이 부축해 끌고 내려갔다. 한참 숨이 붙지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-16 }, wake:1 },
    { l:'② 눈을 감고 계단 수만 세며 내려간다.', k:'steady', dc:21,
      ok:`눈을 감았다. 얼굴을 안 보면 얼굴도 이쪽을 못 읽는다.<br><br>난간을 쥐고 한 칸씩. 스물두 칸. 딸깍 소리가 양옆에서 났다. 그런데 이쪽 몸에 닿지 않는다. 눈 감은 사람은 세기 어렵다.<br>로비 바닥에 발이 닿았다. 눈을 떴다. 등 뒤가 조용하다.`,
      ng:`열다섯째 칸에서 계단이 한 칸 더 있었다. 세던 숫자와 안 맞는다.<br><br>헛디뎠다. 굴렀다. 대리석 모서리에 옆구리를 찧었다.<br>눈을 떴을 때 같은 얼굴들이 다 이쪽을 내려다보고 있었다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B3', t:'9호차 — 빌린 얼굴의 검표원',
  x:`검표원이 집게를 딸깍이며 들어온다. 모자를 눌러 썼다.<br><br>
    얼굴이 낯익다. 아까 맨 뒷자리에서 자던 남자 얼굴이다. 그 자리는 지금 비었다.<br>
    관상가는 안다. 얼굴은 뼈와 살과 버릇으로 생긴다. 뼈와 살은 빌려도 버릇은 못 빌린다.<br><br>
    「표 좀 보겠습니다.」 검표원이 이쪽 앞에 섰다.`,
  o:[
    { l:'① 얼굴과 표정이 안 맞는 데를 찾는다.', k:'gaze', dc:21,
      ok:`표를 꺼내는 척 오래 뒤적이며 봤다. 자던 남자는 왼쪽으로 고개가 기울어 잤다. 왼쪽 볼이 눌려 살이 접혔다. 그 접힌 자국이 검표원 얼굴에 그대로 있다.<br><br>그런데 검표원이 웃을 때는 오른쪽 입꼬리만 오른다. 왼쪽 볼이 접힌 사람은 왼쪽으로 웃는다. 얼굴과 웃음이 반대다.<br>표를 내밀었다. 검표원이 구멍을 뚫는다. 이쪽은 그의 웃음 쪽, 오른쪽 어깨 너머만 봤다. 그는 웃는 쪽에서 들키는 줄 몰랐다. 다음 칸으로 갔다.<br><br>빌린 얼굴과 제 버릇이 어긋나는 금 하나. 이제 얼굴을 볼 때 얼굴과 웃음을 따로 본다.`,
      ng:`뒤적이는 시간이 길었다. 검표원이 기다린다. 웃는다. 오른쪽만.<br><br>「표가 없으세요?」 집게가 이쪽 손등에 닿았다. 딸깍.<br>손등에 구멍 모양 자국이 남았다. 붉게. 그 손이 한참 이쪽 것 같지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-15, spirit:-16 }, wake:1 },
    { l:'② 내공을 눈에 모아 빌린 얼굴 밑을 본다.', k:'gaze', dc:22, cost:{ qi:26 },
      ok:`내공을 눈 뒤에 모았다. 눈을 가늘게 떴다. 검표원 얼굴 가장자리가 흐리다. 귀 밑에서 얼굴이 살짝 떠 있다.<br><br>그 밑에 다른 것이 있다. 얼굴이 아니다. 얼굴을 걸어 둘 데뿐이다.<br>표를 내밀었다. 얼굴 밑을 본 눈으로 검표원을 똑바로 봤다. 검표원이 먼저 눈을 내렸다. 들킨 것은 오래 서 있지 못한다. 구멍도 안 뚫고 지나갔다.`,
      ng:`내공이 눈에 몰리다 머리로 치솟았다. 눈앞이 하얘졌다.<br><br>하얀 데서 검표원 얼굴이 크게 다가온다. 얼굴 밑이 이쪽을 본다.<br>눈을 감았다. 한참 어지러워 좌석을 붙잡았다. 코피가 흘렀다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B3', t:'7호차 — 거울 속 늦은 얼굴',
  x:`세면대 앞에서 남자가 면도한다. 거울이 셋. 가운데 거울 앞.<br><br>
    거울 속 남자는 다른 얼굴에 면도칼을 대고 있다. 진짜보다 조금 늦게.<br>
    거울 속 얼굴을 본다. 늦게 따라오는 얼굴이 진짜다. 앞서 움직이는 얼굴이 쓴 얼굴이다.<br><br>
    「늦은 밤이네요. 수건 좀 잡아 주시겠어요.」 남자가 거울 너머로 인사한다.`,
  o:[
    { l:'① 거울 속 늦은 얼굴을 끝까지 읽는다.', k:'gaze', dc:21,
      ok:`거울 속 얼굴을 봤다. 늙었다. 인중이 길다. 오래 산 상이다. 그런데 눈 밑이 젖었다. 울고 있다.<br><br>거울 속 사람이 원래 주인이다. 얼굴을 빼앗기고 거울에 남았다. 면도칼은 빼앗은 쪽 손에 있다. 거울 속 사람은 그 칼이 다가오는 걸 늦게 따라 할 뿐이다.<br>수건을 잡지 않았다. 거울 속 노인에게 아주 작게 고개를 숙였다. 노인이 늦게 고개를 숙였다. 앞의 남자는 숙이지 않았다. 그 사이 지나갔다.`,
      ng:`읽는 사이 거울 속 얼굴이 이쪽을 봤다. 늦게가 아니라 먼저.<br><br>가운데 거울에 이쪽 얼굴이 비친다. 이쪽보다 먼저 웃는다.<br>눈을 떼고 물러났다. 한참 이쪽 입꼬리가 제 마음대로 떨렸다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-14, spirit:-18 } },
    { l:'② 다가가 수건을 잡아 준다.', k:'bond', dc:21,
      doom:{ title:'면도칼', what:'면도칼이 목에 닿았습니다', dc:18, sec:45,
        text:`다가가 수건을 잡았다. 남자가 고맙다며 고개를 숙인다. 거울 속은 숙이지 않는다.<br><br>남자가 면도칼을 든다. 이쪽 쪽으로. 「수염이 자라셨네.」<br>칼날이 턱밑에 닿는다. 차다. 움직이면 그어진다. 안 움직이면 천천히 그어진다.<br><br>가운데 거울에 이쪽 얼굴이 비친다. 이쪽보다 조금 늦게 놀란다.`,
        dieText:`세면대 앞에서 남자가 면도한다. 거울이 셋.<br><br>가운데 거울 속에는 노인이, 오른쪽 거울 속에는 처음 보는 얼굴이 늦게 따라 한다.<br>「늦은 밤이네요. 수건 좀 잡아 주시겠어요.」` },
      ok:`다가가 수건을 잡기 전에 남자 손을 봤다. 면도칼 쥔 손 엄지가 칼등이 아니라 칼날 쪽에 있다. 면도하는 손이 아니다.<br><br>수건을 남자 손등 위에 덮어 쥐여 주었다. 칼까지 같이 싸서. 「여기 있소.」<br>남자가 웃는다. 칼이 수건에 싸여 안 나온다. 웃음이 굳는 사이 등을 돌려 통로로 나갔다. 등 뒤 거울 셋에서 아무도 늦게 따라오지 않았다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'B3', t:'식당칸 — 빨간 외투의 찻잔',
  x:`창가에 빨간 외투 여자. 담배를 끼웠는데 불은 안 붙였다. 앞에 찻잔이 둘.<br><br>
    「그 사람이 누군지 알아요. 알려 줄게요. 대신 표를 줘요.」<br>
    여자 얼굴을 본다. 인당이 맑다. 콧날이 곧다. 거짓말을 잘 못하는 상이다. 그런데 손가락 담배가 떤다.<br><br>
    이쪽 자리 찻잔에 김이 오른다.`,
  o:[
    { l:'① 여자 얼굴과 떨리는 손을 같이 읽는다.', k:'gaze', dc:21,
      ok:`얼굴은 거짓을 못 하는 얼굴이다. 손이 떠는 건 무서워서다. 거짓말하는 사람은 손이 안 떤다. 연습했으니까.<br><br>무서운 사람이 표를 원한다. 내리고 싶은 것이다. 이 사람은 그것이 아니다. 이 열차에서 내리지 못한 사람이다.<br>찻잔은 안 마셨다. 대신 물었다. 「그것은 무엇을 늘 바꾸지 못하오.」 여자가 담배를 쥔 손을 내렸다. 「구두요. 늘 마른 구두.」 그 말 하나면 됐다.`,
      ng:`손이 떠는 걸 거짓말로 읽었다. 그렇게 말해 버렸다.<br><br>여자 얼굴이 하얘졌다. 일어나 찻잔을 엎었다. 뜨거운 차가 이쪽 손등에 쏟아졌다.<br>여자는 식당칸 끝으로 사라졌다. 알려 줄 사람이 하나 없어졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 표를 내주고 이름을 듣는다.', k:'luck', dc:21,
      ok:`표를 내밀었다. 여자가 받으며 손을 꽉 쥐었다. 고맙다는 손이다.<br><br>「그것은 얼굴을 바꿔도 구두를 못 바꿔요. 젖지 않은 구두.」 그리고 표를 이쪽 손에 도로 쥐여 주었다. 「난 이미 있어요. 내릴 데가 없을 뿐이지.」<br>표도 남고 말도 남았다.`,
      ng:`표를 내밀자 여자가 받아 들고 일어섰다. 말없이.<br><br>창밖을 본다. 표를 창에 대고 비춘다. 구멍이 둘. 「이건 안 되겠네.」 표를 바닥에 떨어뜨렸다.<br>주우려 허리를 굽힌 사이 여자는 사라졌다. 표 모서리가 젖어 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-16 } },
    { l:'③ 찻잔을 바꿔 놓고 여자 얼굴을 본다.', k:'hide', dc:20,
      ok:`여자가 창을 볼 때 두 찻잔을 바꿔 놓았다.<br><br>여자가 이쪽을 보고 찻잔을 든다. 제 앞 잔. 원래 이쪽 잔. 입에 대려다 멈춘다. 얼굴에 놀람이 없다. 그냥 마신다.<br>아무 일도 없다. 차는 그냥 차였다. 여자는 이쪽을 해칠 생각이 없었다. 찻잔을 바꾼 손이 부끄러웠다. 그래도 바꾼 덕에 그걸 알았다.`,
      ng:`바꾸다 찻잔이 부딪쳤다. 쨍.<br><br>여자가 돌아봤다. 바뀐 찻잔을 보고 웃는다. 슬프게. 「다들 그래요.」<br>여자가 일어나 갔다. 남은 차가 식었다. 이쪽 얼굴이 화끈거렸다. 등 뒤에서 웨이터가 오래 서 있었다.`,
      win:{ exp:15, spirit:6 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B3', t:'바 카운터 — 거울에 안 비치는 얼굴',
  x:`바텐더가 잔을 닦는다. 카운터 끝에 할머니가 보따리를 안고 앉았다. 젖은 머릿수건. 나물 냄새.<br><br>
    바텐더가 잔 하나를 이쪽으로 민다. 따뜻한 물에 무언가 탔다. 단내.<br>
    카운터 뒤 거울에 할머니는 비친다. 바텐더는 안 비친다.<br><br>
    관상가는 둘의 얼굴을 다 본다. 하나는 거울로, 하나는 맨눈으로.`,
  o:[
    { l:'① 할머니 얼굴을 읽는다.', k:'gaze', dc:20,
      ok:`볕에 그을린 얼굴. 손등에 흙물. 눈가 주름이 아래로 처졌다. 오래 웃어 준 얼굴이다. 이 열차의 것이 아니다. 산에서 나물 뜯다 탄 사람이다.<br><br>할머니가 이쪽을 보고 보따리를 푼다. 「배고프지. 이거라도.」 산나물 한 줌.<br>이 열차에서 처음 받는, 거울에 비치는 사람의 것이다. 바텐더가 민 잔은 손대지 않았다.`,
      ng:`할머니 얼굴을 보는 사이 바텐더가 잔을 한 번 더 밀었다. 이쪽 손에 닿게.<br><br>손이 저절로 잔을 쥐었다. 단내가 코를 찌른다. 입에 대기 직전에 할머니가 손등을 쳤다.<br>잔이 깨졌다. 단물이 손바닥에 묻어 오래 끈적거렸다. 머리가 핑 돈다.`,
      win:{ exp:16, item:'산나물' }, lose:{ mind:-15, spirit:-14 } },
    { l:'② 바텐더가 민 잔을 그대로 바텐더 앞으로 되민다.', k:'steady', dc:21,
      ok:`잔을 손끝으로 되밀었다. 천천히. 바텐더 앞까지.<br><br>바텐더 얼굴이 처음으로 움직였다. 아주 조금. 눈썹 하나. 거울에 안 비치는 얼굴도 놀랄 줄은 안다.<br>그는 잔을 들어 버렸다. 그리고 다른 잔에 맹물을 따라 내밀었다. 이번엔 정말 맹물이다. 맑다.`,
      ng:`되미는데 바텐더가 손가락 하나로 잔을 막았다. 힘이 세다.<br><br>잔이 두 손가락 사이에서 멈췄다. 김이 이쪽 얼굴로 오른다. 단내를 들이켰다.<br>한참 카운터를 붙잡고 서 있었다. 할머니가 등을 두드려 주었다.`,
      win:{ exp:18, item:'맑은 물' }, lose:{ hp:-20, mind:-16 } }
  ] }
]);

// ------------------------------------------
// 탐정 · 자원 없음
// ------------------------------------------
kJob('detective', 'B', [

{ at:'B', t:'빗속 — 마른 자리',
  x:`온 바닥이 젖었다. 모퉁이 한 곳만 말랐다. 신발 두 짝 크기의 네모.<br><br>
    탐정은 마른 자리를 그냥 못 지나간다. 비 오는 밤에 마른 자리는 누가 오래 서 있던 자리다.<br>
    네모 둘레에 꽁초가 셋. 다 반쯤 타다 꺼졌다.<br><br>
    서 있던 사람은 지금 없다. 아니면 지금은 다른 데서 서 있다.`,
  o:[
    { l:'① 마른 자리의 모양과 꽁초로 그 사람을 세운다.', k:'gaze', dc:21,
      ok:`마른 네모 앞쪽이 좁고 뒤쪽이 넓다. 뒤꿈치에 무게를 둔 사람이다. 오래 서는 데 익숙하다.<br><br>꽁초 셋은 타다 만 길이가 같다. 피우는 게 아니라 시간을 잰다. 하나에 십 분쯤. 삼십 분을 서 있었다. 그리고 꽁초 끝이 다 한쪽을 향해 버려졌다. 늘 같은 쪽을 보며 버린다. 지켜보던 쪽이다.<br>그 쪽을 봤다. 이쪽이 지나갈 길이다. 그 길을 안 갔다. 마른 자리 뒤 담을 넘었다.<br><br>맞지 않는 것 하나가 사람 하나를 세운다. 마른 땅 한 뼘으로 서른 분을 읽었다. 이제 빗속에서는 젖은 데보다 마른 데가 먼저 눈에 걸린다.`,
      ng:`네모를 재려고 쪼그려 앉았다. 앉은 자리가 마른 자리였다.<br><br>그 순간 맞은편 창에서 성냥 긋는 소리. 불빛 하나. 서 있던 사람은 자리를 옮겨 같은 쪽을 보고 있었다.<br>뛰었다. 담벼락을 넘다 손바닥이 깨진 병에 베였다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 꽁초 하나를 주워 상표를 본다.', k:'luck', dc:20,
      ok:`꽁초를 집어 필터를 봤다. 금색 띠가 둘. 흔한 담배가 아니다. 이 동네에서 파는 데가 한 곳이다.<br><br>그 한 곳은 아까 지나온 골목 입구 가게다. 그 가게 주인이 이쪽을 오래 봤던 게 떠오른다.<br>그 골목으로는 안 돌아가기로 했다.`,
      ng:`집은 꽁초가 아직 뜨거웠다. 손가락을 데었다.<br><br>방금 버린 것이다. 고개를 드니 골목 끝에서 담뱃불 하나가 이쪽으로 흔들리며 다가온다.<br>숨어 있던 내내 데인 손가락이 욱신거렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-14 } },
    { l:'③ 마른 자리를 크게 돌아 피한다.', k:'evade', dc:20,
      ok:`마른 자리에서 보이는 모든 데를 머릿속으로 그었다. 그 선 밖으로만 걸었다.<br><br>담 밑, 차 그늘, 간판 뒤. 돌아가는 길은 세 배 길었다.<br>끝까지 아무도 이쪽을 안 봤다. 서 있던 사람이 보던 데는 늘 같은 데다.`,
      ng:`돌아가다 차 그늘에 고인 물을 밟았다. 철벅.<br><br>골목 끝에서 누가 고개를 돌렸다. 손전등이 켜졌다.<br>차 밑으로 기어들었다. 기름 섞인 물에 배를 대고 오래 숨을 참았다.`,
      win:{ exp:15, spirit:6 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'공중전화 — 우는 수화기',
  x:`길가 공중전화 부스. 비에 유리가 뿌옇다. 전화가 운다.<br><br>
    부스 안을 본다. 바닥에 젖은 발자국이 있다. 들어간 것만. 나온 발자국이 없다.<br>
    선반 위 동전 하나. 수화기 줄이 반 바퀴 꼬였다.<br><br>
    전화는 계속 운다. 이쪽이 부스 앞에 선 뒤로 소리가 커졌다.`,
  o:[
    { l:'① 부스 안 흔적으로 누가 무엇을 기다렸는지 따진다.', k:'gaze', dc:21,
      ok:`발자국은 들어간 것만. 그런데 부스 뒤쪽 유리에 손바닥 자국이 있다. 안쪽에서. 뒤 유리가 반쯤 열리는 문이다.<br><br>들어가서 뒤로 나갔다. 앞으로 나가면 보이니까. 수화기 줄은 반 바퀴 꼬였다. 왼손으로 들었다가 오른손으로 걸었다. 통화 중에 무엇을 적었다.<br>선반 밑에 볼펜 자국이 눌린 종이 한 장. 연필로 비볐다. 『비 그치기 전. 둘째 맨홀.』 전화는 그 말을 다시 하려고 우는 것이다. 받지 않았다. 이미 들었다.`,
      ng:`흔적을 보려 부스 문을 열었다. 경첩이 비명을 질렀다.<br><br>전화가 뚝 끊겼다. 길 건너 2층 창의 커튼이 움직였다.<br>부스 뒤 유리로 빠져나가다 유리 모서리에 옆구리를 그었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 받아서 아무 말 없이 듣는다.', k:'steady', dc:20,
      ok:`수화기를 들고 숨을 죽였다. 저쪽도 말이 없다. 한참.<br><br>그러다 저쪽에서 다른 소리가 들렸다. 기적 소리. 아주 멀리서. 그리고 빗소리. 저쪽도 비가 온다. 저쪽은 바닷가다.<br>「왔나.」 저쪽이 물었다. 대답하지 않고 수화기를 내려놓았다. 상대가 어디 있는지 알면 그쪽으로 안 가면 된다.`,
      ng:`듣는 사이 숨소리가 새어 나갔다. 저쪽이 그걸 들었다.<br><br>「거기 있군. 움직이지 마.」 끊겼다.<br>부스를 나오는데 길 양쪽에서 차 불빛이 켜졌다. 골목으로 뛰어들다 발목을 접질렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'의뢰인 — 맞지 않는 이야기',
  x:`일을 맡긴 사람이 다시 나타났다. 우산을 들었다. 숨이 차 보인다.<br><br>
    「계획이 바뀌었소. 창고 말고 저쪽 부두. 거기서 배를 기다리시오.」<br>
    처음 들었던 말과 지금 말을 나란히 놓는다. 시각, 장소, 사람 수.<br><br>
    그는 숨이 차다고 했다. 그런데 우산 끝이 말라 있다.`,
  o:[
    { l:'① 처음 말과 지금 말의 순서를 맞춰 본다.', k:'gaze', dc:21,
      ok:`처음에 그는 「다섯 시 배」라고 했다. 지금은 「배를 기다리시오」. 시각이 빠졌다. 처음에 「장부 한 권」. 지금은 장부를 안 묻는다.<br><br>장부가 필요 없어졌다. 아니면 처음부터 필요 없었다. 필요했던 건 이쪽이 정해진 데 서 있는 것이다. 우산 끝이 마른 건 숨차게 뛰어온 게 아니라 차에서 내렸다는 뜻이다. 차는 저쪽 부두에서 왔다.<br>「알겠소.」 대답하고 그가 가리킨 쪽과 반대로 갔다. 등 뒤에서 그가 누군가에게 손짓하는 기척이 있었다.<br><br>말은 바꿀 수 있어도 말의 순서는 따라 바뀌지 않는다. 두 이야기를 나란히 놓고 빠진 칸을 세는 법이 이번엔 숨 한 번에 됐다.`,
      ng:`맞춰 보는 동안 표정에 의심이 떴다. 그가 그걸 봤다.<br><br>「의심하시나.」 우산을 접는다. 우산 속에서 다른 것이 나온다.<br>피했다. 스쳤다. 팔뚝이 찢어졌다. 그는 다시 우산을 펴고 걸어갔다. 서두르지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 의뢰인의 신발과 바짓단을 본다.', k:'sense', dc:20,
      ok:`구두가 말랐다. 바짓단에 모래가 묻었다. 젖은 모래가 아니라 마른 모래. 차 바닥 매트에서 묻는 모래다.<br><br>부두에서 차를 타고 왔다. 차는 부두에 다시 간다. 그쪽으로 가라는 말은 차가 있는 데로 가라는 말이다.<br>고개만 끄덕이고 헤어졌다. 부두 쪽은 안 갔다.`,
      ng:`신발을 보느라 고개를 숙였다. 그가 이쪽 어깨에 손을 얹었다.<br><br>「피곤하신가 보오.」 손에 힘이 들어간다. 어깨뼈가 눌린다.<br>뿌리치고 물러났다. 어깨가 한참 저렸다. 그는 웃으며 부두 쪽을 다시 가리켰다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'바닥 — 깨진 손목시계',
  x:`바닥에 손목시계가 떨어졌다. 유리가 깨졌다. 바늘이 멈췄다. 두 시 십칠 분.<br><br>
    옆에 핏자국이 조금. 끌린 자국이 문 쪽으로.<br>
    누가 보면 이렇게 읽는다. 두 시 십칠 분에 여기서 무슨 일이 있었다.<br><br>
    탐정은 그렇게 읽히라고 놓인 것을 먼저 의심한다.`,
  o:[
    { l:'① 시계가 언제 멈춘 척했는지 따진다.', k:'gaze', dc:21,
      ok:`시계를 집었다. 용두가 빠져 있다. 떨어져 깨진 시계는 용두가 안 빠진다. 누가 바늘을 맞추고 빼 두었다.<br><br>깨진 유리 조각이 시계 위에 있다. 시계가 떨어지고 유리가 깨진 게 아니다. 유리를 깨서 위에 뿌렸다.<br>그러면 두 시 십칠 분은 거짓이다. 이 일은 그보다 늦게 일어났다. 쫓는 쪽은 이쪽이 두 시 십칠 분에 맞춰 움직이길 바란다. 끌린 자국 쪽 문은 버렸다.`,
      ng:`시계를 집다 유리 조각에 손끝을 베였다.<br><br>피가 시계판에 떨어졌다. 이제 핏자국이 두 사람 것이다.<br>그 사이 문 쪽에서 발소리. 피 냄새를 따라온다. 숨어서 오래 숨을 죽였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 시계를 주머니에 넣어 현장을 비운다.', k:'luck', dc:20,
      ok:`시계를 주머니에 넣었다. 깨진 유리는 신발로 쓸어 구석에 밀었다.<br><br>꾸며 놓은 현장에서 꾸민 물건이 빠지면 꾸민 사람이 헷갈린다. 다시 와서 다시 꾸며야 한다.<br>시계 뒷면에 새긴 글씨가 있다. 이름 두 글자. 나중에 쓸 데가 있을 것이다.`,
      ng:`주머니에 넣는 순간 문 쪽에서 플래시가 터졌다. 사진이다.<br><br>시계를 든 이쪽이 찍혔다. 이제 이쪽이 그 일을 한 사람이 됐다.<br>뛰었다. 문 대신 창으로. 창틀에 무릎을 찧었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'방 — 너무 깨끗한 방',
  x:`문이 열린 방. 표백제 냄새가 숨을 막는다. 바닥이 반짝인다.<br><br>
    책상, 의자, 침대, 옷걸이. 다 제자리다. 너무 제자리다.<br>
    있는 것보다 없는 것을 센다. 깨끗한 방은 무엇이 없어졌는지 알려 주지 않는다. 대신 무엇이 남았는지가 이상해진다.<br><br>
    복도 끝에서 양동이 끄는 소리가 난다. 이쪽으로.`,
  o:[
    { l:'① 있어야 할 것 중 없는 것을 센다.', k:'gaze', dc:21,
      ok:`옷걸이가 다섯. 걸린 옷이 없다. 침대 시트가 새것이다. 접은 금이 그대로다. 책상에 펜꽂이. 펜이 없다. 쓰레기통이 비었다. 비닐까지 새것이다.<br><br>누가 살던 방을 지운 게 아니다. 이 방은 아직 아무도 안 산 방처럼 꾸몄다. 그런데 옷걸이는 다섯이다. 혼자 사는 방에 옷걸이 다섯은 많다. 다섯 사람 몫을 준비해 둔 방이다.<br>그 다섯이 누구인지 알았다. 방을 나와 양동이 소리 반대로 갔다.<br><br>없는 것들의 목록이 그 자리에 있을 사람을 말해 준다. 빈 데를 세는 셈이 이제 손가락보다 빠르다.`,
      ng:`세다가 숫자가 엉켰다. 표백제 냄새에 머리가 띵하다.<br><br>그사이 양동이 소리가 문 앞에서 멎었다. 고무장화가 한 걸음 들어온다.<br>침대 밑으로 들어갔다. 표백제가 코를 태운다. 기침을 삼키느라 갈비뼈가 아팠다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-12 }, wake:1 },
    { l:'② 냄새가 진한 쪽을 피해 나간다.', k:'sense', dc:20,
      ok:`냄새가 제일 진한 데는 방금 닦은 데다. 닦는 사람이 거기서 멀지 않다.<br><br>냄새가 옅은 쪽으로 갔다. 옅은 데는 오래전에 닦은 데다. 닦은 사람이 이미 지나갔다.<br>양동이 소리를 등 뒤로 두고 계단에 닿았다.`,
      ng:`옅은 쪽이라 믿고 간 데가 아직 안 닦은 데였다. 닦을 데였다.<br><br>복도 모퉁이에서 대걸레가 이쪽 발밑으로 밀려왔다. 그 뒤에 그가 있다.<br>돌아 뛰었다. 젖은 바닥에 미끄러져 벽에 어깨를 박았다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 반짝이는 바닥 틈을 칼끝으로 긁어 본다.', k:'fix', dc:21,
      ok:`바닥 판자 틈에 칼끝을 넣고 긁었다. 깨끗한 방도 틈은 못 닦는다.<br><br>틈에서 작은 것이 나왔다. 단추. 그리고 표 한 조각. 승차권 귀퉁이다. 찍힌 날짜가 오늘.<br>이 방에 오늘 누가 있었다. 표를 가진 사람. 단추는 주머니에, 표 조각은 수첩 사이에 넣었다.`,
      ng:`긁는 소리가 생각보다 컸다. 표백제로 닦은 바닥이 울린다.<br><br>양동이 소리가 멈췄다. 그리고 빨라졌다.<br>칼을 놓치고 뛰었다. 칼은 방에 남았다. 이제 그 방에 이쪽 것이 하나 있다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'진흙 — 겹친 발자국',
  x:`젖은 흙바닥에 발자국이 한 줄 이어진다. 한 사람 것이다. 보폭이 고르다.<br><br>
    그런데 발자국마다 깊이가 다르다. 왼발은 얕고 오른발은 깊다. 그다음은 반대.<br>
    깊이를 잰다. 한 사람이 이렇게 걷지는 않는다.<br><br>
    발자국 끝이 이쪽이 갈 길로 이어진다.`,
  o:[
    { l:'① 깊이로 몇 사람이 걸었는지 가린다.', k:'gaze', dc:21,
      ok:`발자국 하나에 손가락을 넣어 봤다. 바닥에 굽 자국이 두 겹이다. 큰 신발 안에 작은 신발.<br><br>둘이 걸었다. 뒷사람이 앞사람 발자국을 그대로 밟았다. 한 사람인 척하려고. 깊이가 엇갈리는 건 둘의 무게가 달라서다.<br>둘이 한 사람인 척하는 건 이쪽 머릿수 셈을 틀리게 하려는 것이다. 발자국 끝 모퉁이에 하나가 서고 하나는 숨었을 것이다. 모퉁이를 두 번 살피고 지났다. 두 번째에 숨은 하나가 보였다.<br><br>발자국 하나에서 두 사람을 꺼냈다. 겹친 것을 한 겹씩 벗기는 셈. 이제 하나로 보이는 것을 먼저 둘로 나눠 본다.`,
      ng:`손가락을 넣는 사이 발자국 끝 모퉁이에서 그림자가 둘 갈라졌다.<br><br>하나가 이쪽으로 오고 하나가 뒤로 돈다. 앞뒤가 막혔다.<br>흙벽을 기어올라 빠져나왔다. 손톱이 둘 들렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 발자국을 밟지 않고 거꾸로 거슬러 간다.', k:'evade', dc:20,
      ok:`발자국이 온 쪽으로 거슬러 갔다. 발자국 옆 돌만 밟았다.<br><br>발자국이 시작된 데에 상자가 있다. 둘이 쉬었던 데다. 상자 안에 먹다 남긴 말린 고기 한 줄.<br>쫓는 쪽도 먹는다. 남긴 것을 챙겼다. 이쪽이 그들의 출발점에 와 있는 줄은 그들도 모른다.`,
      ng:`돌을 밟다 미끄러져 발자국 한가운데를 밟았다.<br><br>이제 발자국이 세 겹이다. 이쪽 것까지.<br>뒤를 보니 모퉁이에서 둘이 돌아온다. 발자국을 보며. 흙벽 틈에 숨어 오래 떨었다.`,
      win:{ exp:16, item:'말린 고기' }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B', t:'쪽지 — 『너희 중 하나』',
  x:`일행 가방 사이에 쪽지가 끼워져 있었다. 누가 넣었는지 아무도 모른다.<br><br>
    『너희 중 하나가 너희를 팔았다.』<br>
    일행이 서로를 본다. 아무 말도 없다. 그게 제일 나쁘다.<br><br>
    탐정은 쪽지 내용보다 쪽지를 본다. 종이, 글씨, 접은 모양.`,
  o:[
    { l:'① 종이와 글씨로 누가 넣었는지 따진다.', k:'gaze', dc:21,
      ok:`종이가 두껍다. 한쪽 가장자리가 톱니처럼 뜯겼다. 장부를 뜯은 종이다. 일행 누구도 장부를 안 가졌다.<br><br>글씨는 반듯하다. 왼쪽으로 기운다. 일부러 기울였다. 진짜 버릇을 숨긴 글씨다. 그런데 『팔았다』의 받침만 오른쪽으로 섰다. 거기서 힘이 빠져 버릇이 나왔다.<br>일행 손글씨를 다 봤다. 그런 받침은 없다. 이 쪽지는 밖에서 왔다. 서로 의심하게 하려고. 쪽지를 모두에게 보여 주고 받침을 짚었다. 일행 어깨가 풀렸다.`,
      ng:`종이를 살피는 이쪽을 일행 하나가 봤다. 의심하는 얼굴로.<br><br>「왜 그걸 그렇게 오래 봐.」 다른 하나도 이쪽을 본다.<br>설명하는 데 시간이 들었다. 그 사이 쫓는 쪽 발소리가 가까워졌다. 다들 서로 떨어져 뛰었다. 한참 뒤에야 다시 모였다.`,
      win:{ exp:20, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 쪽지를 모두 앞에서 태운다.', k:'bond', dc:20,
      ok:`성냥을 그어 쪽지에 댔다. 모두가 보는 앞에서.<br><br>「누가 썼든 쓴 놈이 원하는 건 이거요. 우리가 서로 보는 거.」<br>재가 바닥에 떨어졌다. 일행이 서로를 보다 이쪽을 봤다. 그리고 걸음을 맞췄다.`,
      ng:`태우는데 일행 하나가 막았다. 증거를 왜 태우느냐고.<br><br>실랑이 끝에 쪽지가 반만 탔다. 『하나가』까지 남았다.<br>그 반쪽이 내내 누군가의 주머니에 있었다. 다들 말이 없었다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'철문 앞 — 줄 선 사람들',
  x:`나가는 철문 앞에 사람들이 줄을 섰다. 열 명쯤. 다 젖었다. 문이 열릴 때마다 맨 앞 한 사람이 들어간다.<br><br>
    들어간 사람은 다시 안 나온다. 문 너머가 출구라고 다들 믿는다.<br>
    줄을 센다. 그리고 신발을 본다. 다 젖었다. 한 사람만 말랐다.<br><br>
    마른 신발은 줄 한가운데 서 있다. 앞으로 가지 않는다. 뒤에 선 사람이 생길 때마다 한 칸 물러난다.`,
  o:[
    { l:'① 마른 신발의 사람이 무엇을 하는지 가린다.', k:'gaze', dc:20,
      ok:`줄 밖에서 오래 봤다. 마른 신발은 문이 열릴 때마다 맨 앞사람 등을 본다. 그리고 손가락 하나를 접는다.<br><br>세는 사람이다. 줄에 서서 줄을 센다. 숫자가 차면 문이 닫힐 것이다. 줄 선 사람들이 출구라고 믿는 그 문이.<br>줄에 서지 않았다. 줄 옆 담을 따라 문 반대쪽 배수로를 찾았다. 마른 신발이 손가락 접는 걸 멈추고 이쪽을 봤다. 줄 밖 사람은 셀 수가 없다.`,
      ng:`보다가 마른 신발과 눈이 마주쳤다. 그가 손가락 하나를 접었다. 이쪽을 보며.<br><br>줄에 안 섰는데 세어졌다. 다리가 무겁다. 줄 쪽으로 발이 끌린다.<br>일행이 팔을 잡아 끌어냈다. 다리가 한참 남의 것 같았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 줄 맨 끝에 서서 차례를 기다리며 지켜본다.', k:'hide', dc:21,
      doom:{ title:'줄', what:'줄 맨 앞으로 끌려갑니다', dc:17, sec:55,
        text:`맨 끝에 섰다. 사람들 틈에 숨어 지켜보면 안전할 줄 알았다.<br><br>문이 열릴 때마다 줄이 한 칸씩 당겨진다. 이쪽 발이 저절로 따라간다. 멈추려 해도 앞사람과 뒷사람 사이에 끼여 밀린다. 뒷사람이 생겼다. 언제 왔는지 모른다.<br>마른 신발이 이쪽 옆을 지나 뒤로 간다. 손가락을 접는다. 문이 가까워진다.<br><br>문 너머가 보인다. 출구가 아니다. 다음 줄이다.`,
        dieText:`나가는 철문 앞에 사람들이 줄을 섰다. 열 명쯤. 다 젖었다.<br><br>줄 한가운데 마른 신발이 서 있다.<br>그 옆에 젖은 신발 한 켤레가 비어 놓였다. 줄은 그 신발을 피해 선다.` },
      ok:`맨 끝에 서기 전에 신발을 벗어 손에 들었다. 맨발로 섰다.<br><br>마른 신발이 뒤로 와 손가락을 접으려다 멈춘다. 이쪽 발을 본다. 신발이 없다. 세는 법이 안 맞는다. 그는 신발을 센다.<br>그 사이 줄을 빠져나와 담 그늘로 갔다. 손에 든 신발이 무거웠다. 그래도 세어지지 않았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B1', t:'3번 창고 — 가지런한 고무장갑',
  x:`벽을 보고 앉은 사람의 의자 다리 옆. 하얀 고무장갑 한 짝이 떨어져 있다.<br><br>
    손가락을 가지런히 모은 채다. 떨어진 장갑은 이렇게 안 생긴다. 벗어서 놓은 것이다.<br>
    장갑 둘레 바닥이 반짝인다. 표백제 냄새.<br><br>
    장갑 하나로 사람 하나를 세울 수 있다고 믿는다. 오늘 밤 그 믿음이 필요하다.`,
  o:[
    { l:'① 장갑 하나로 장갑 주인을 세운다.', k:'gaze', dc:21,
      ok:`왼손 장갑이다. 손가락 끝이 안 닳았다. 손바닥 가운데만 닳았다. 무언가를 늘 손바닥으로 쥔다. 대걸레 자루다.<br><br>왼손을 벗었다. 오른손으로 일하는 사람은 일이 끝나면 왼손부터 벗는다. 끝났다는 뜻이다. 이 의자의 일은 끝났다. 그리고 하나를 일부러 남겼다. 다음 일 순서를 알리는 표시다. 손가락이 가리키는 쪽이 다음이다.<br>손가락은 쪽문을 가리킨다. 쪽문 밖에서 그가 다음 일을 하고 있다. 쪽문은 안 열었다. 셔터 쪽으로 갔다.<br><br>남이 일하는 순서를 장갑 하나에서 읽었다. 버릇은 증거다. 버릇을 알면 다음 수를 안다.`,
      ng:`장갑을 뒤집어 보려 집었다. 안쪽이 아직 따뜻하다.<br><br>그때 쪽문이 열렸다. 고무장화 한 짝이 문턱을 넘는다. 장갑을 찾으러 왔다.<br>장갑을 던지고 상자 뒤로 숨었다. 상자 모서리에 이마를 찧었다. 소리를 삼켰다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-14 }, wake:1 },
    { l:'② 장갑을 손 안 대고 원래대로 둔다.', k:'hide', dc:20,
      ok:`장갑을 건드리지 않았다. 둘레 반짝이는 바닥에 발자국도 안 남겼다.<br><br>그가 돌아오면 장갑을 본다. 장갑이 그대로면 아무도 안 왔다고 여긴다.<br>숨어서 봤다. 그가 와서 장갑을 집고 둘레를 둘러봤다. 고개를 끄덕이고 쪽문으로 나갔다. 이쪽은 그 반대 길을 알게 됐다.`,
      ng:`건드리지 않으려다 발끝이 반짝이는 바닥을 밟았다. 신발 바닥 무늬가 찍혔다.<br><br>그가 돌아와 그 무늬를 봤다. 쪼그려 앉아 오래.<br>그리고 수첩을 꺼내 무언가 적었다. 숨어 있는 내내 가슴이 쿵쿵 울렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 사무실 — 다시 우는 전화',
  x:`사무실 전화가 운다. 열두 번 울고 멎는다. 그리고 다시 운다.<br><br>
    벽시계는 두 시 이십 분. 시계 밑 물때표. 다섯 시 십 분에 빨간 줄.<br>
    탐정은 벨 수를 센다. 전화는 받으라고 우는 것도 있고 세라고 우는 것도 있다.<br><br>
    책상 위 장부가 펼쳐졌다. 펼쳐진 쪽에 오늘 날짜.`,
  o:[
    { l:'① 벨 수와 시계로 신호를 푼다.', k:'gaze', dc:21,
      ok:`첫 번 열두. 두 번째 열둘. 셋째는 다섯에서 끊겼다. 넷째 열. 시계를 봤다. 열둘, 열둘, 다섯, 열. 두 시, 다섯 시 십 분.<br><br>시각이다. 받으라는 게 아니라 시각을 확인하는 신호다. 사무실 사람이 있으면 받아서 말할 것이고, 없으면 시각만 맞춰 둔다. 그런데 처음 두 번은 열둘이다. 다른 시각이 아니라 같은 시각을 두 번. 두 사람이 있다. 같은 시각에 움직이는.<br>장부 오늘 칸에 『청소 2』가 적혀 있다. 하나가 아니다. 그걸 알고 나니 등 뒤가 더 추웠다.`,
      ng:`세는 사이 벨이 멈추고 철계단에서 발소리가 났다. 사무실 사람이 받으러 온다.<br><br>책상 밑에 숨었다. 그가 수화기를 들고 「응」 한마디만 하고 끊었다.<br>그가 책상 앞에 오래 서 있었다. 이쪽 손가락이 그의 구두 앞에서 떨렸다. 다리에 쥐가 났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-20, mind:-15 } },
    { l:'② 수화기를 들고 상대가 먼저 말하게 둔다.', k:'bond', dc:21,
      ok:`들었다. 숨만 쉬었다. 저쪽이 먼저 말했다. 「셋째 창고 다섯 맞나. 배는 정시.」<br><br>「다섯 아니오. 넷.」 낮게 말하고 끊었다.<br>저쪽은 숫자가 틀린 걸 고치러 사람을 하나 더 보낼 것이다. 더 보낸 사람은 엉뚱한 셈을 들고 온다. 셈이 엉키면 일하는 쪽이 느려진다.`,
      ng:`들었다. 저쪽이 먼저 말하지 않았다. 침묵이 길다.<br><br>참다 숨이 새었다. 저쪽이 웃었다. 「거기 있구나.」<br>끊기자마자 계단에서 발소리. 창문으로 나가다 유리에 손바닥을 베었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } },
    { l:'③ 수화기를 내려 두고 그 틈에 장부를 본다.', k:'sense', dc:20,
      ok:`수화기를 들어 책상에 눕혀 두었다. 벨이 멎는다. 통화 중이다.<br><br>통화 중이면 다음 벨이 안 온다. 저쪽은 누가 받았다고 여긴다. 그 사이 장부를 넘겼다. 오늘 장 맨 아래 『정문 사슬 — 05:10 자동』.<br>정문이 닫히는 시각. 그거면 됐다.`,
      ng:`수화기를 눕히자 저쪽에서 말소리가 새어 나왔다. 「왜 말이 없어.」 계속.<br><br>소리가 사무실에 울린다. 철계단 아래서 누가 그 소리를 듣고 올라온다.<br>장부를 덮지도 못하고 나왔다. 계단 난간에 정강이를 찧었다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B1', t:'야적장 — 열린 컨테이너',
  x:`문이 열린 컨테이너. 촛불이 켜졌다. 심지가 아직 길다. 방금 켰다.<br><br>
    간이침대 다섯, 물통, 양동이. 침대마다 담요가 반듯하게 개어졌다. 개어 놓은 각이 다 똑같다.<br>
    벽 달력에 날짜마다 엑스. 오늘 칸만 비었다.<br><br>
    방 하나를 보면 거기 사는 사람이 선다. 이 방은 다섯 사람 방인데 사는 사람은 하나다.`,
  o:[
    { l:'① 방 안 물건들로 사는 사람을 세운다.', k:'gaze', dc:21,
      ok:`담요 각이 똑같다. 한 사람이 다 갰다. 물통은 하나. 컵도 하나. 양동이 안쪽이 하얗게 바랬다. 표백제다.<br><br>달력 엑스는 같은 펜, 같은 힘. 매일 밤 같은 시각에 그었다. 오늘 칸이 빈 건 아직 일이 안 끝나서다. 침대 다섯은 손님 자리다. 오늘 밤 다섯을 눕힐 자리.<br>그리고 촛불. 방금 켰다. 그는 촛불을 켜 두고 나간다. 돌아올 때 방이 밝게. 돌아올 시각은 심지 길이만큼이다. 반 시간.<br><br>사는 사람의 하루를 물건으로 세우고, 그 하루의 다음 칸을 읽었다. 순서가 보이면 시간이 보인다. 반 시간 안에 이 골목을 벗어났다.`,
      ng:`물건을 하나씩 보다 촛불에 소매가 닿았다. 불이 흔들렸다.<br><br>그림자가 벽에 크게 일렁인다. 바깥 탐조등이 그 일렁임에 멈췄다.<br>컨테이너를 나오다 문짝에 이마를 박았다. 하얀 빛이 바로 뒤를 훑고 지나갔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-14 }, wake:1 },
    { l:'② 촛불을 끄고 안에서 그를 기다린다.', k:'hide', dc:21,
      doom:{ title:'컨테이너', what:'청소부에게 끌려갑니다', dc:17, sec:55,
        text:`촛불을 껐다. 침대 밑에 숨었다. 돌아오는 그를 먼저 보려고.<br><br>발소리가 온다. 뽀득. 문 앞에서 멈춘다. 꺼진 촛불을 본다.<br>그는 늘 켜 두고 나간다. 꺼져 있으면 누가 왔다. 그는 그걸 안다. 문이 밖에서 닫힌다. 쇠 빗장 소리.<br><br>어둠 속에서 고무장갑 끼는 소리가 난다. 그는 이미 안에 있었다.`,
        dieText:`컨테이너 문이 열려 있다. 촛불이 켜졌다. 심지가 아직 길다.<br><br>침대 다섯에 담요가 반듯하게 개어졌다. 하나는 새 담요다.<br>벽 달력 오늘 칸에 엑스가 그어졌다.` },
      ok:`촛불을 끄려다 멈췄다. 그는 촛불을 켜 두고 나가는 사람이다. 꺼져 있으면 안다.<br><br>촛불은 그대로 두고 담요 하나만 각을 조금 틀어 놓았다. 그리고 나와 컨테이너 위로 올라가 엎드렸다.<br>그가 돌아왔다. 들어가 담요를 본다. 각을 고친다. 고치는 데 정신이 팔렸다. 그 사이 컨테이너 지붕을 건너 골목 끝으로 내려왔다. 그는 끝까지 담요 각을 맞추고 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B1', t:'회색 밴 — 수첩의 빈칸',
  x:`회색 밴 계기판 위에 수첩이 펼쳐졌다. 이름이 적혔다. 이쪽 일행 이름이다.<br><br>
    이름 옆에 칸이 하나씩. 다 비었다. 그 옆에 만년필. 뚜껑이 열렸다.<br>
    빈칸보다 빈칸 둘레를 본다. 빈칸을 적으려던 손은 늘 무언가를 남긴다.<br><br>
    밴 뒷유리 너머 짐칸. 양동이 셋, 대걸레 둘, 표백제 통. 크기순으로.`,
  o:[
    { l:'① 빈칸 둘레 잉크 자국으로 그의 순서를 읽는다.', k:'gaze', dc:21,
      ok:`빈칸 왼쪽 위에 잉크 점이 하나씩 있다. 만년필을 대려다 뗀 자리. 점의 크기가 다르다. 첫째 이름 옆이 제일 크다. 오래 대고 있었다. 망설였다.<br><br>망설인 이름을 먼저 적을 사람은 없다. 가장 작은 점이 먼저다. 셋째 이름. 그다음 다섯째. 이 사람은 순서를 정해 두었다. 그리고 그 순서대로 일한다.<br>셋째 이름의 일행을 맨 가운데 세웠다. 다섯째를 그 옆에. 순서의 앞자리를 감싸면 순서가 막힌다.`,
      ng:`잉크 점을 보려 고개를 들이밀다 운전석 문에 기댔다. 문이 열렸다. 경보음.<br><br>짧게 울리고 멎었다. 그래도 울렸다.<br>정문 쪽에서 장화 소리가 서둘렀다. 밴 밑으로 기어들었다. 기름이 얼굴에 떨어졌다. 눈이 따가웠다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 만년필 뚜껑을 닫아 둔다.', k:'fix', dc:20,
      ok:`만년필 뚜껑을 닫았다. 소리 없이.<br><br>그는 뚜껑을 열어 두고 갔다. 곧 와서 적을 셈이다. 돌아와 뚜껑이 닫혀 있으면 펜촉을 다시 적셔야 한다. 잉크가 굳었으면 닦아야 한다.<br>일하는 사람은 도구가 어긋나면 멈춘다. 그 멈춘 시간만큼 이쪽이 앞선다.`,
      ng:`닫는데 뚜껑이 딸깍 소리를 냈다. 생각보다 크게.<br><br>밴 안 무전기가 그 소리에 지직거렸다. 누가 듣고 있다.<br>멀어지는 동안 무전기에서 이쪽 일행 이름이 하나씩 불렸다. 등줄기가 젖었다.`,
      win:{ exp:16, spirit:6 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 이름 적힌 장을 찢어 간다.', k:'break', dc:21,
      ok:`그 장을 찢었다. 찢긴 자리를 손톱으로 고르게 다듬었다. 처음부터 없던 장처럼.<br><br>그는 수첩을 보고 일한다. 수첩에 없으면 그 일은 없다. 다시 적으려면 이름을 다시 알아내야 한다.<br>찢은 장을 접어 신발 깔창 밑에 넣었다. 발이 무겁지 않았다.`,
      ng:`찢는데 수첩 제본이 단단하다. 반만 찢겼다. 남은 반에 이름 셋.<br><br>찢긴 자국이 흉하게 남았다. 그는 이걸 보면 안다.<br>그날 밤 남은 셋 이름의 일행은 계속 등 뒤가 시렸다. 실제로 손전등이 셋을 자주 찾았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B2', t:'배식 수레 — 번호만 있는 칸',
  x:`밤 열한 시. 배식은 없다. 그래도 복도에 배식 수레가 섰다.<br><br>
    윗칸 식판마다 침대 번호 스티커. 몇 칸은 번호만 붙고 식판이 없다.<br>
    탐정은 빈 칸 번호를 적는다. 있는 것보다 없는 것이 사건이다.<br><br>
    밑칸은 천으로 덮였다. 천 밑이 각졌다.`,
  o:[
    { l:'① 빈 칸 번호로 누가 빠졌는지 따진다.', k:'gaze', dc:21,
      ok:`빈 번호를 적었다. 3, 8, 13, 18. 다섯씩 건너뛴다. 정각마다 하나씩, 다섯 침대 건너. 규칙이 있다.<br><br>규칙대로라면 다음은 23. 이쪽 일행이 누운 침대 번호 하나가 23이다.<br>그 사람을 다른 침대로 옮겼다. 번호가 틀리면 다음 정각에 빈 칸이 생기지 않는다. 규칙은 번호를 보지 사람을 안 본다.<br><br>빈 데의 간격에서 다음 빈 데를 셈했다. 없는 것들을 줄 세우면 앞으로 없어질 것이 보인다. 그 셈이 이제 눈에 붙었다.`,
      ng:`적다가 연필이 부러졌다. 손톱으로 벽에 긁어 적으려는데 딸깍 소리가 다가왔다.<br><br>수레 뒤에 쪼그려 숨었다. 간호사가 수레를 밀고 간다. 이쪽은 수레에 붙은 채 몇 걸음 끌려갔다.<br>떨어져 나오며 바퀴에 손가락이 깔렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, mind:-14 }, wake:1 },
    { l:'② 천 덮인 밑칸을 들춰 본다.', k:'luck', dc:20,
      ok:`천을 들췄다. 상자다. 『환자 간식 — 반납』. 열자 작은 종지들. 꿀 종지다. 뚜껑에 침대 번호.<br><br>빈 칸 번호들이다. 먹지 못한 사람 몫이 반납됐다.<br>하나를 챙겼다. 번호 3. 3번 침대 사람이 먹었어야 할 것이다. 대신 먹고 대신 기억해 두기로 했다.`,
      ng:`천을 들추는데 상자 위에 계수기가 하나 올려져 있었다. 굴러떨어졌다.<br><br>딸깍. 떨어지며 눌렸다.<br>복도 끝 간호사실 불이 켜졌다. 숨을 데까지 기어가는 동안 무릎이 다 까졌다.`,
      win:{ exp:15, item:'꿀 한 줌' }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B2', t:'간호사실 — 빈 고리와 마른 신발',
  x:`간호사실 벽 열쇠판. 고리마다 열쇠 하나. 한 고리만 비었다.<br><br>
    고리 밑 이름표는 『비상계단』. 의자에 앉은 간호사는 서류를 본다. 한 장도 안 넘긴다.<br>
    의자 밑 간호사 신발이 말랐다. 창밖은 비가 오는데. 이 사람은 오늘 밖에 안 나갔다. 아니면 한 번도.<br><br>
    빈 고리의 열쇠가 지금 누구 주머니에 있는지 궁금하다.`,
  o:[
    { l:'① 빈 고리의 열쇠를 누가 가졌는지 따진다.', k:'gaze', dc:21,
      ok:`빈 고리 아래 벽에 손때가 진하다. 자주 걸고 뗐다. 그런데 손때 위치가 높다. 간호사 키로는 발끝을 들어야 닿는다.<br><br>키 큰 사람이 가져갔다. 이 층에서 키 큰 사람은 보호사들이다. 계단참에서 벽 보고 서는 그들. 열쇠는 계단 쪽에 있다. 비상계단은 열쇠를 가진 쪽이 지킨다.<br>계단 문으로 가지 않았다. 열쇠가 계단에 있으면 계단은 막혔다. 승강기 쪽 복도로 돌았다.`,
      ng:`손때를 보려 유리에 가까이 붙었다. 안의 간호사가 서류에서 눈을 들었다.<br><br>유리 너머로 마주 봤다. 그가 서류를 처음으로 넘겼다. 넘긴 장에 무언가 적었다.<br>정각에 딸깍 소리가 이쪽 침대 앞에서 오래 멈췄다. 숨이 막혔다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 간호사가 안 볼 때 다른 열쇠를 집는다.', k:'hide', dc:21,
      ok:`간호사는 서류를 안 넘긴다. 한 장을 오래 본다. 눈이 서류에 박혀 있다.<br><br>그 사이 간호사실 쪽창으로 손을 넣어 『약제실』 고리 열쇠를 뺐다. 비상계단 열쇠는 없지만 약제실 창은 배관으로 이어진다.<br>간호사는 끝까지 서류를 봤다. 그가 보는 건 서류가 아니다. 그건 나중에 알았다.`,
      ng:`열쇠를 빼는데 옆 열쇠가 부딪쳐 쨍 소리가 났다.<br><br>간호사가 고개를 들지 않고 손만 뻗어 이쪽 손목을 잡았다. 차다.<br>열쇠를 떨어뜨리고 손목을 비틀어 뺐다. 손목에 손가락 자국이 하얗게 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'4층 탈의실 — 먼지 없는 사물함',
  x:`철제 사물함 두 줄. 명패마다 사람 이름. 문짝마다 먼지가 앉았다. 오래 아무도 안 열었다.<br><br>
    한 칸에서 소리가 난다. 안에서 두드린다. 똑똑. 쉬었다가 똑똑.<br>
    그 칸만 먼지가 없다. 명패도 없다.<br><br>
    먼지를 믿는다. 먼지는 거짓말을 안 한다. 먼지 없는 칸은 매일 누가 연다.`,
  o:[
    { l:'① 먼지와 손잡이 자국으로 그 칸을 따진다.', k:'gaze', dc:21,
      ok:`손잡이를 봤다. 반들반들하다. 그런데 손자국이 바깥쪽이 아니라 안쪽 가장자리에 있다. 안에서 문을 밀어 연 자국이다.<br><br>매일 안에서 나온다. 그리고 다시 들어간다. 두드리는 건 열어 달라는 게 아니다. 아직 나갈 시각이 아니라고 세는 것이다. 똑똑 사이 쉼이 점점 짧아진다. 시각이 다가온다.<br>탈의실을 나왔다. 문을 밖에서 닫았다. 사물함이 열리는 소리는 복도 끝에서 들었다.`,
      ng:`손잡이를 보려 가까이 갔다. 두드림이 멎었다.<br><br>안에서 이쪽 숨소리를 듣는다. 문짝 틈으로 눈 하나가 보였다.<br>뒷걸음질 치다 벤치에 걸려 넘어졌다. 철제 모서리에 허리를 찧었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 사물함 문을 열어 안을 본다.', k:'break', dc:22,
      doom:{ title:'사물함', what:'사물함 안으로 끌려 들어갑니다', dc:17, sec:50,
        text:`손잡이를 비틀어 열었다. 문이 열린다.<br><br>안은 사물함보다 깊다. 옷걸이에 흰 가운이 걸렸다. 가운 안에 누가 있다. 아니, 가운이 서 있다.<br>소매가 이쪽 손목을 잡는다. 당긴다. 어깨가 사물함 안으로 들어간다. 가운 냄새. 다림질 냄새.<br><br>문이 등 뒤에서 닫히려 한다. 철컥 소리가 반쯤 났다.`,
        dieText:`탈의실 사물함 두 줄. 명패마다 사람 이름.<br><br>한 칸에 새 명패가 꽂혔다. 먼지가 없다.<br>안에서 두드린다. 똑똑. 쉬었다가 똑똑.` },
      ok:`열기 전에 발로 사물함 아래를 받쳤다. 문이 다 열리지 않게 한 뼘만.<br><br>한 뼘 틈으로 봤다. 흰 가운 하나가 걸렸다. 가운 주머니에 명찰. 숫자가 아니라 이름. 그리고 출입증 카드.<br>틈으로 손가락 둘만 넣어 카드를 뺐다. 소매가 그 손가락을 잡으려다 놓쳤다. 문을 닫고 사물함을 벤치로 막았다. 카드는 원무과 문을 연다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B2', t:'원무과 — 테이프로 가린 팻말',
  x:`대기실 뒤 복도에 경비원이 있다. 『오』. 5층 창가에서 봤던 사람이다.<br><br>
    「이쪽이야. 뒷문. 정문은 당직이 지켜.」 문을 가리킨다. 문 위 팻말 글씨는 테이프로 가렸다.<br>
    손에 서류를 쥐었다. 엄지 끝이 둥글게 파였다.<br><br>
    탐정은 엄지를 본다. 오래 같은 것을 누른 엄지다.`,
  o:[
    { l:'① 그의 엄지와 가린 팻말을 맞춰 본다.', k:'gaze', dc:21,
      ok:`엄지 끝이 계수기 단추 모양으로 파였다. 매일 수천 번 누른 엄지다. 이 사람은 세는 쪽이다. 직원이 아닌 직원들과 같은 쪽.<br><br>팻말 테이프 가장자리가 들렸다. 비쳐 보이는 글자 끝. 『…실』. 뒷문이면 『출구』나 『주차장』이어야 한다. 『실』로 끝나는 방은 이 층에 하나다. 안치실.<br>「먼저 가시오. 우리는 따라가리다.」 그의 웃음이 굳었다. 세는 쪽은 먼저 문을 넘지 않는다. 그는 끝내 움직이지 않았다. 이쪽도.<br><br>사람 하나와 글자 한 조각을 나란히 놓으니 문 하나가 거짓이 됐다. 맞지 않는 둘을 겹치면 하나가 맞는다.`,
      ng:`엄지를 보다 들켰다. 그가 서류로 엄지를 덮는다.<br><br>「뭘 그렇게 봐.」 웃음이 사라진다. 뒷문이 열린다. 안이 차다.<br>뒤에서 누가 등을 밀었다. 문턱에서 버텼다. 무릎이 문틀에 찍혔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-12 }, wake:1 },
    { l:'② 테이프를 떼어 팻말을 읽는다.', k:'luck', dc:20,
      ok:`그가 이쪽 일행을 세는 사이 손을 뻗어 테이프를 뜯었다.<br><br>『안치실』. 그가 아무 말 없이 이쪽을 봤다. 들킨 사람의 얼굴이 아니라 아쉬운 얼굴이다.<br>그는 숫자가 맞기를 바랐을 뿐이다. 그가 비켜섰다. 이쪽은 퇴원 수속 창구 쪽으로 갔다.`,
      ng:`테이프가 잘 안 떨어진다. 반쯤 뜯었을 때 그가 이쪽 손목을 잡았다.<br><br>「뜯지 마. 다들 놀라.」 손목을 문 쪽으로 끈다.<br>팔꿈치로 그의 명치를 쳤다. 손목이 풀렸다. 이쪽 팔꿈치도 저렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B3', t:'9호차 — 오래 씻는 손',
  x:`화장실 문에 사용 중 표시. 문 밑으로 물이 흘러나온다. 열차가 기울 때마다 이쪽으로 왔다 돌아간다.<br><br>
    안에서 수도 소리. 손 씻는 소리다. 아주 오래.<br>
    문 밑 물을 본다. 물은 안에서 무슨 일이 있었는지 들고 나온다.<br><br>
    옆 벽 하얀 구급함. 『승무원 외 열지 말 것』.`,
  o:[
    { l:'① 문 밑으로 나온 물로 안의 일을 따진다.', k:'gaze', dc:21,
      ok:`물이 맑다. 피는 없다. 그런데 물 위에 비누 거품이 아니라 하얀 가루가 뜬다. 분이다. 얼굴에 바르는 분.<br><br>손을 씻는 게 아니라 얼굴을 씻는다. 얼굴을 지우는 소리다. 아까 맨 뒷자리 남자 얼굴. 검표원이 되기 전에 쓰던 얼굴을 지운다.<br>물소리가 그치기 전에 앞 칸으로 갔다. 그치면 새 얼굴이 문을 열고 나온다. 그 얼굴을 안 보는 편이 낫다. 봐 버리면 그 얼굴을 믿게 된다.`,
      ng:`물을 보려 쪼그려 앉았다. 물이 이쪽 쪽으로 쏠려 왔다. 발목을 적신다.<br><br>수도 소리가 멎었다. 문 안에서 누가 문 밑 그림자를 본다. 이쪽 그림자.<br>일어서다 선반 모서리에 머리를 박았다. 그 사이 문이 열렸다. 다른 얼굴이 이쪽을 보고 웃었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 승무원 구급함을 연다.', k:'luck', dc:20,
      ok:`뚜껑을 열었다. 붕대, 소독약, 말린 약초 뭉치. 그리고 승무원 수첩 한 장.<br><br>『9호차 화장실 — 03:00 이후 사용 금지. 사용 중 표시 시 무시할 것.』<br>무시하라고 적은 사람이 있다. 이 열차에 아직 사람이 있었을 때. 약초를 챙기고 구급함을 닫았다.`,
      ng:`여는데 경첩이 울었다. 수도 소리가 멎었다.<br><br>화장실 손잡이가 돌아간다. 구급함 뚜껑에 손가락이 끼었다.<br>빼내고 물러났다. 손가락이 퍼렇게 부었다. 문은 열리다 말았다.`,
      win:{ exp:15, item:'약초 뭉치' }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B3', t:'7호차 차장실 — 옷장의 소매',
  x:`차장실 문이 반쯤 열렸다. 접이식 의자, 무전기, 벽에 시간표.<br><br>
    지나간 역마다 연필로 줄을 그었다. 물안, 저녁재.<br>
    구석 철제 옷장이 한 뼘 열렸다. 그 틈으로 차장 제복 소매. 소매 끝에 손. 움직이지 않는다.<br><br>
    언제를 먼저 묻는다. 누구보다 언제가 쉽다.`,
  o:[
    { l:'① 연필 줄과 소매로 언제 바뀌었는지 따진다.', k:'gaze', dc:21,
      ok:`연필 줄은 물안까지 굵고 곧다. 저녁재 줄은 가늘고 비뚤다. 다른 손이 그었다. 연필을 쥐는 법을 모르는 손.<br><br>옷장 소매 끝 손에 연필 심 가루가 묻었다. 물안을 지운 손은 이 손이다. 차장은 물안을 지나고 저녁재 전에 옷장에 들어갔다. 그 사이 그것이 차장이 됐다.<br>물안과 저녁재 사이 열차에 탄 사람만 의심하면 된다. 9호차에서 그 사이 탄 사람은 하나. 맨 뒷자리 남자. 범위가 하나로 줄었다.<br><br>사람 대신 시각부터 좁혔다. 언제를 세우면 누구는 따라온다. 그 순서가 손에 익었다.`,
      ng:`연필 줄을 보다 무전기가 갑자기 울렸다. 「차장. 차장.」<br><br>대답할 사람이 없다. 옷장 안 손가락이 무전기 소리에 움찔했다. 움직였다.<br>차장실을 뛰쳐나왔다. 문틀에 어깨를 부딪쳤다. 등 뒤에서 옷장 문이 끽 열렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-20, spirit:-16 }, wake:1 },
    { l:'② 무전기를 들어 다른 칸 소리를 엿듣는다.', k:'sense', dc:20,
      ok:`무전기를 귀에 댔다. 지직거림 사이로 숨소리. 그리고 아주 작게 다른 목소리. 「기관실. 기관실.」<br><br>기관실에서 누가 차장을 부른다. 진짜 기관사다. 아직 살아 있다. 그리고 그 목소리 뒤에 같은 목소리가 하나 더 겹친다. 「기관실 이상 없음.」<br>기관실에 둘이 있다. 그걸 알고 앞 칸으로 갔다.`,
      ng:`귀에 대는 순간 무전기 저쪽 숨소리가 이쪽 귀에 바로 붙었다.<br><br>「차장. 거기 있나.」 이쪽을 차장으로 부른다.<br>무전기를 떨어뜨렸다. 귀가 한참 울렸다. 이쪽 이름이 기억나지 않았다. 잠깐.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B3', t:'특실 7호실 — 불만 붙인 꽁초',
  x:`젖은 외투의 남자. 모자챙에서 물이 떨어진다. 무릎 위에 권총.<br><br>
    「아홉 역째 쫓고 있소. 그놈은 기관실로 가요. 문 좀 지켜 주시오. 누가 와도 열지 말고.」<br>
    탁자 재떨이에 꽁초가 여럿. 다 불만 붙이고 안 피웠다. 필터가 하얗다.<br><br>
    탐정은 재떨이를 본다. 사람은 재떨이에서 제일 많이 털어놓는다.`,
  o:[
    { l:'① 꽁초로 남자를 따진다.', k:'gaze', dc:21,
      ok:`꽁초가 아홉. 아홉 역째 쫓는다고 했다. 역마다 하나씩 불을 붙였다. 세는 것이다. 피우는 사람이 아니다. 피우는 사람은 필터가 누렇게 젖는다.<br><br>쫓는 사람은 잠이 모자라 담배를 피운다. 이 사람은 안 피운다. 대신 센다. 이 열차에서 세는 것은 쫓는 쪽이 아니다. 그런데 구두가 젖었다. 쓴 얼굴이 아닌 진짜다. 젖은 사람이 센다. 그것을 쫓으려 그것처럼 세는 법을 배운 사람.<br>「문은 못 지키겠소. 대신 같이 가지.」 남자가 이쪽을 오래 봤다. 그리고 권총을 외투에 넣었다. 「셈이 밝은 사람이군.」`,
      ng:`재떨이를 보는데 남자가 꽁초 하나를 집어 이쪽 쪽으로 밀었다.<br><br>「궁금하면 하나 피우시오.」 눈이 웃지 않는다.<br>거절하자 그의 손이 권총 손잡이에 얹혔다. 물러나 문을 나섰다. 등 뒤에서 그가 문을 잠갔다. 이쪽을 밖에 두고.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-15, spirit:-14 } },
    { l:'② 남자 말대로 문을 지킨다.', k:'steady', dc:21,
      ok:`문 앞에 섰다. 누가 와도 안 열기로 했다.<br><br>복도에서 발소리. 문을 두드린다. 남자 목소리. 「나요. 열어 주시오.」 열지 않았다. 진짜 남자는 열지 말라고 했다.<br>두드림이 멎었다. 한참 뒤 진짜 남자가 돌아왔다. 열쇠로 열고. 「누가 왔소?」 「당신이 왔소.」 남자가 고개를 끄덕였다. 그것은 기관실로 가는 중이다.`,
      ng:`두드림이 남자 목소리였다. 열지 않았다. 그런데 문 밑으로 남자 구두가 보였다. 젖은 구두.<br><br>열었다. 서 있는 것이 웃는다. 구두는 젖었는데 얼굴이 말랐다.<br>문을 닫으려다 손이 문틈에 끼었다. 그것이 물러난 뒤에도 손가락이 펴지지 않았다.`,
      win:{ exp:18, spirit:6 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 남자가 나간 뒤 몰래 따라간다.', k:'hide', dc:20,
      ok:`남자가 나가자 문을 닫고 거리를 두고 따라갔다.<br><br>그는 앞 칸으로 가지 않았다. 복도 끝 번호 없는 문 앞에서 멈춰 성냥을 그었다. 꽁초 하나에 불을 붙여 문틈에 끼웠다. 그리고 앞 칸으로 갔다.<br>번호 없는 문틈의 담배 연기가 안쪽으로 빨려 들어간다. 그는 문 안에 무엇이 있는지 표시를 해 두고 갔다. 그 문은 열지 않았다.`,
      ng:`따라가다 카펫에서 발소리가 났다. 카펫인데.<br><br>남자가 돌아본다. 권총이 이쪽을 향했다. 「문 지키라고 했잖소.」<br>총구를 내릴 때까지 숨을 못 쉬었다. 그는 다시 돌아보지 않았다. 이쪽은 길을 잃었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B3', t:'기관실 문 — 기관사가 둘',
  x:`기관실 문 작은 창. 기관사가 둘이다. 같은 모자, 같은 얼굴, 같은 기름때.<br><br>
    둘이 동시에 이쪽을 본다. 동시에 말한다. 「저놈이 가짜요. 들어와서 도와주시오.」<br>
    둘 다 구두가 젖었다. 화실 열기에 둘 다 김이 오른다. 구두로는 못 가린다.<br><br>
    시계는 04:38. 종착 불빛이 창 가득 다가온다.`,
  o:[
    { l:'① 손톱 밑 기름때로 진짜를 가린다.', k:'gaze', dc:22,
      doom:{ title:'기관실', what:'가짜 기관사에게 끌려갑니다', dc:18, sec:45,
        text:`창에 얼굴을 대고 둘의 손을 봤다. 둘 다 기름때. 왼쪽 손톱 밑이 더 검다. 왼쪽이다.<br><br>문을 열고 왼쪽에게 갔다. 「저자를 붙잡으시오.」 왼쪽이 웃는다. 오른쪽이 아니라 이쪽 팔을 붙잡는다.<br>손톱 밑 기름은 긁어서 넣을 수 있다. 얹힌 기름은 그렇게 못 넣는다. 그걸 늦게 봤다. 화실 문 쪽으로 끌린다. 열기가 얼굴을 덮는다.<br><br>오른쪽 기관사가 바닥에 쓰러져 비상 손잡이를 가리킨다. 손이 닿지 않는다.`,
        dieText:`기관실 안이다. 기관사가 하나 레버 앞에 섰다.<br><br>얼굴이 바뀐다. 검표원, 면도하던 남자, 웨이터. 마지막에 한 얼굴에서 멈춘다.<br>이번 운행에 탔던 탐정 얼굴이다.` },
      ok:`창에 얼굴을 대고 둘의 손을 봤다. 둘 다 기름때. 왼쪽 손톱 밑이 더 검다. 그런데 손톱 위 기름은 고르게 얹혔다. 손톱 밑만 검은 건 긁어 넣은 것이다. 일한 손은 손톱 밑보다 손가락 마디 주름이 먼저 검어진다.<br><br>오른쪽 손 마디 주름이 검다. 오른쪽이다. 문을 열자마자 왼쪽 무릎 뒤를 찼다. 왼쪽이 넘어지며 얼굴이 흔들렸다. 다른 얼굴들이 스쳐 갔다.<br>오른쪽 기관사가 비상 손잡이를 잡았다. 「같이!」 둘이 당겼다. 쇳소리가 길게 울렸다. 맞지 않는 것 하나가 끝까지 남는다. 일한 손의 주름은 빌릴 수 없다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 둘 다 들이지 않고 문을 밖에서 잠근다.', k:'fix', dc:21,
      ok:`문을 열지 않았다. 문고리에 허리띠를 감아 난간에 묶었다.<br><br>안의 둘이 같은 목소리로 화를 낸다. 하나는 정말 화가 났고 하나는 화난 척한다. 둘 다 못 나온다. 진짜는 안에서 제동을 걸 수 있다. 가짜는 진짜를 막느라 바쁘다.<br>시간을 번 사이 기관실 옆 발판으로 돌아 선로 전환 표지를 봤다. 녹슨 지선 쪽 레버가 바깥에 있다. 그게 다음 일이다.`,
      ng:`허리띠를 감는데 안에서 둘 중 하나가 문을 확 당겼다. 허리띠가 손에서 빠졌다.<br><br>문이 한 뼘 열렸다. 기름 묻은 손이 나와 이쪽 손목을 잡는다. 어느 쪽 손인지 모른다.<br>빼냈다. 손목에 기름과 살갗이 같이 묻어났다. 문은 다시 닫혔다. 열기가 얼굴을 쳤다.`,
      win:{ exp:18, spirit:6 }, lose:{ hp:-30, mind:-12 } }
  ] }
]);
